package com.hcimprogression.companion;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;

/** Reads the same four Fossil Island varps used by RuneLite's Time Tracking plugin. */
public class BirdhouseTracker
{
    private static final long DURATION_SECONDS = 50 * 60L;
    private static final String CONFIG_GROUP = "hcimprogression.birdhouses";
    private static final HouseDef[] HOUSES = {
        new HouseDef("Mushroom Meadow (North)", VarPlayerID.BIRDHOUSE_TRANSMIT_A),
        new HouseDef("Mushroom Meadow (South)", VarPlayerID.BIRDHOUSE_TRANSMIT_B),
        new HouseDef("Verdant Valley (Northeast)", VarPlayerID.BIRDHOUSE_TRANSMIT_C),
        new HouseDef("Verdant Valley (Southwest)", VarPlayerID.BIRDHOUSE_TRANSMIT_D)
    };

    private final ConfigManager configManager;
    private final Map<Integer, State> states = new LinkedHashMap<>();

    public BirdhouseTracker(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public boolean update(Client client)
    {
        long now = System.currentTimeMillis() / 1000L;
        boolean changed = false;
        for (HouseDef house : HOUSES)
        {
            int value = client.getVarpValue(house.varp);
            State previous = states.get(house.varp);
            if (previous == null)
            {
                long stored = readTimestamp(house.varp, value);
                long changedAt = stored > 0 ? stored : now;
                states.put(house.varp, new State(value, changedAt));
                if (stored <= 0)
                {
                    // Persist the initial observation too. Without this, a
                    // client restart reset an unchanged birdhouse timer to
                    // another full 50 minutes and delayed the website alert.
                    writeTimestamp(house.varp, value, changedAt);
                    changed = true;
                }
            }
            else if (previous.value != value)
            {
                State next = new State(value, now);
                states.put(house.varp, next);
                writeTimestamp(house.varp, value, now);
                changed = true;
            }
        }
        return changed;
    }

    public BirdhouseSnapshot snapshot()
    {
        BirdhouseSnapshot tracked = timeTrackingSnapshot();
        if (!tracked.getHouses().isEmpty()) return tracked;
        BirdhouseSnapshot result = new BirdhouseSnapshot();
        long now = System.currentTimeMillis() / 1000L;
        long nextReady = Long.MAX_VALUE;
        for (HouseDef house : HOUSES)
        {
            State state = states.get(house.varp);
            if (state == null) continue;
            String status = status(state.value, state.changedAt, now);
            long readyAt = state.value > 0 && state.value % 3 == 0 ? state.changedAt + DURATION_SECONDS : 0;
            result.getHouses().add(new BirdhouseSnapshot.House(house.name, status, state.changedAt, readyAt));
            result.setTrackedCount(result.getTrackedCount() + 1);
            if (state.value > 0 && state.value % 3 == 0)
            {
                result.setSeededCount(result.getSeededCount() + 1);
                if (readyAt <= now) result.setReadyCount(result.getReadyCount() + 1);
                else nextReady = Math.min(nextReady, readyAt);
            }
        }
        result.setNextReadyAt(nextReady == Long.MAX_VALUE ? 0 : nextReady);
        return result;
    }

    void reset() { states.clear(); }

    /** Read RuneLite's own saved timestamps; never restart a timer on login. */
    BirdhouseSnapshot timeTrackingSnapshot()
    {
        BirdhouseSnapshot result = new BirdhouseSnapshot();
        long now = System.currentTimeMillis() / 1000L;
        long nextReady = Long.MAX_VALUE;
        for (HouseDef house : HOUSES)
        {
            String stored = configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP,
                TimeTrackingConfig.BIRD_HOUSE + "." + house.varp);
            BirdhouseSnapshot.House record = fromTimeTracking(house.name, stored, now);
            if (record == null) continue;
            result.getHouses().add(record);
            result.setTrackedCount(result.getTrackedCount() + 1);
            if (record.getReadyAt() > 0)
            {
                result.setSeededCount(result.getSeededCount() + 1);
                if ("ready".equals(record.getState())) result.setReadyCount(result.getReadyCount() + 1);
                else nextReady = Math.min(nextReady, record.getReadyAt());
            }
        }
        result.setNextReadyAt(nextReady == Long.MAX_VALUE ? 0 : nextReady);
        return result;
    }

    static BirdhouseSnapshot.House fromTimeTracking(String name, String stored, long now)
    {
        if (stored == null || stored.length() > 80) return null;
        String[] parts = stored.split(":");
        if (parts.length != 2) return null;
        try
        {
            int value = Integer.parseInt(parts[0]);
            long changed = Long.parseLong(parts[1]);
            if (value < 0 || value > 300 || changed <= 0 || changed > now + 300) return null;
            long ready = value > 0 && value % 3 == 0 ? changed + DURATION_SECONDS : 0;
            String state = value == 0 ? "empty" : ready == 0 ? "needs-seeds" : ready <= now ? "ready" : "growing";
            return new BirdhouseSnapshot.House(name, state, changed, ready);
        }
        catch (NumberFormatException ignored) { return null; }
    }

    private String status(int value, long changedAt, long now)
    {
        if (value <= 0) return "empty";
        if (value % 3 != 0) return "needs-seeds";
        return changedAt + DURATION_SECONDS <= now ? "ready" : "growing";
    }

    private long readTimestamp(int varp, int value)
    {
        String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP, key(varp));
        if (stored == null) return 0;
        String[] parts = stored.split(":");
        if (parts.length != 2) return 0;
        try { return Integer.parseInt(parts[0]) == value ? Long.parseLong(parts[1]) : 0; }
        catch (NumberFormatException ignored) { return 0; }
    }

    private void writeTimestamp(int varp, int value, long timestamp)
    {
        configManager.setRSProfileConfiguration(CONFIG_GROUP, key(varp), value + ":" + timestamp);
    }

    private String key(int varp) { return "house." + varp; }

    private static class HouseDef
    {
        private final String name;
        private final int varp;
        private HouseDef(String name, int varp) { this.name = name; this.varp = varp; }
    }

    private static class State
    {
        private final int value;
        private final long changedAt;
        private State(int value, long changedAt) { this.value = value; this.changedAt = changedAt; }
    }
}

package com.hcimprogression.companion;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/** Reads only inventory/equipment, on the client thread. Notes are not usable supplies. */
final class CarriedItemSnapshot
{
    static Map<String, Long> capture(ItemManager manager, ItemContainer inventory, ItemContainer equipment)
    {
        Map<String, Long> result = new HashMap<>();
        add(result, manager, inventory); add(result, manager, equipment);
        return Collections.unmodifiableMap(result);
    }

    private static void add(Map<String, Long> result, ItemManager manager, ItemContainer container)
    {
        if (container == null) return;
        for (Item item : container.getItems())
        {
            if (item == null || item.getId() < 0 || item.getQuantity() <= 0) continue;
            ItemComposition composition = manager.getItemComposition(item.getId());
            supply(result, composition.getName(), item.getQuantity(), composition.getNote() != -1,
                composition.getPlaceholderTemplateId() != -1);
        }
    }

    static void supply(Map<String, Long> result, String name, int quantity, boolean noted, boolean placeholder)
    {
        if (noted || placeholder || quantity <= 0 || name == null || name.isEmpty() || "null".equals(name)) return;
        result.merge(PackingChecklist.name(name), (long) quantity, Long::sum);
    }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Captures collection-log data from pages the player opens in game.
 *
 * The game only constructs item widgets for the currently visible page, so a
 * complete historical import requires opening each Treasure Trails page once.
 */
public class CollectionLogCaptureService
{
    private static final int ACTIVE_TAB_VARBIT = 6905;
    private static final Pattern NUMBER_PATTERN = Pattern.compile("([0-9][0-9,]*)");

    private final Map<String, CapturedPage> pages = new LinkedHashMap<>();
    private final Map<String, Integer> clueCounts = new LinkedHashMap<>();

    public synchronized void reset()
    {
        pages.clear();
        clueCounts.clear();
    }

    public synchronized CaptureResult captureCurrentPage(Client client, ItemManager itemManager)
    {
        Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
        Widget itemsContainer = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
        if (header == null || itemsContainer == null)
        {
            return null;
        }

        Widget[] headerChildren = header.getDynamicChildren();
        if (headerChildren == null || headerChildren.length == 0)
        {
            return null;
        }

        String pageTitle = clean(headerChildren[0].getText());
        if (pageTitle.isEmpty())
        {
            return null;
        }

        String tabName = activeTabName(client);
        List<AccountSnapshot.CollectionLogItemSnapshot> obtainedItems = new ArrayList<>();
        Widget[] itemWidgets = itemsContainer.getDynamicChildren();
        if (itemWidgets != null)
        {
            for (Widget itemWidget : itemWidgets)
            {
                int itemId = itemWidget.getItemId();
                if (itemId <= 0 || itemWidget.getOpacity() != 0)
                {
                    continue;
                }

                ItemComposition composition = itemManager.getItemComposition(itemId);
                String itemName = composition == null ? "Item " + itemId : composition.getMembersName();
                if (itemName == null || itemName.trim().isEmpty())
                {
                    itemName = "Item " + itemId;
                }

                int quantity = Math.max(1, itemWidget.getItemQuantity());
                obtainedItems.add(new AccountSnapshot.CollectionLogItemSnapshot(
                    itemId,
                    itemName,
                    pageTitle,
                    quantity
                ));
            }
        }

        pages.put(pageTitle.toLowerCase(Locale.ENGLISH), new CapturedPage(pageTitle, tabName, obtainedItems));
        captureClueCount(pageTitle, headerChildren);
        return new CaptureResult(pageTitle, obtainedItems.size(), pages.size(), getObtainedItemCount());
    }

    public synchronized void applyTo(AccountSnapshot snapshot)
    {
        snapshot.getClueCounts().putAll(clueCounts);
        for (CapturedPage page : pages.values())
        {
            snapshot.getCollectionLogItems().addAll(page.items);
        }
        snapshot.getCollectionLog().put("capturedPages", pages.size());
        snapshot.getCollectionLog().put("capturedItems", getObtainedItemCount());
    }

    public synchronized int getCapturedPageCount()
    {
        return pages.size();
    }

    public synchronized int getObtainedItemCount()
    {
        int count = 0;
        for (CapturedPage page : pages.values())
        {
            count += page.items.size();
        }
        return count;
    }

    public synchronized Map<String, Integer> getClueCounts()
    {
        return new LinkedHashMap<>(clueCounts);
    }

    private void captureClueCount(String pageTitle, Widget[] headerChildren)
    {
        String tier = clueTier(pageTitle);
        if (tier == null)
        {
            return;
        }

        for (int i = 1; i < headerChildren.length; i++)
        {
            Widget child = headerChildren[i];
            if (child == null)
            {
                continue;
            }
            String text = clean(child.getText());
            String lower = text.toLowerCase(Locale.ENGLISH);
            if (!lower.contains("clue") && !lower.contains("completed"))
            {
                continue;
            }
            Matcher matcher = NUMBER_PATTERN.matcher(text);
            int last = -1;
            while (matcher.find())
            {
                try
                {
                    last = Integer.parseInt(matcher.group(1).replace(",", ""));
                }
                catch (NumberFormatException ignored)
                {
                    // Ignore malformed widget text.
                }
            }
            if (last >= 0)
            {
                clueCounts.put(tier, last);
                return;
            }
        }
    }

    private String activeTabName(Client client)
    {
        Widget tabs = client.getWidget(ComponentID.COLLECTION_LOG_TABS);
        if (tabs == null || tabs.getStaticChildren() == null)
        {
            return "Collection Log";
        }
        int index = client.getVarbitValue(ACTIVE_TAB_VARBIT);
        Widget[] children = tabs.getStaticChildren();
        if (index < 0 || index >= children.length || children[index] == null)
        {
            return "Collection Log";
        }
        String name = clean(children[index].getName());
        return name.isEmpty() ? "Collection Log" : name;
    }

    private String clueTier(String pageTitle)
    {
        String normalized = pageTitle.toLowerCase(Locale.ENGLISH);
        if (normalized.contains("beginner")) return "beginner";
        if (normalized.contains("easy")) return "easy";
        if (normalized.contains("medium")) return "medium";
        if (normalized.contains("hard") && !normalized.contains("shared")) return "hard";
        if (normalized.contains("elite")) return "elite";
        if (normalized.contains("master")) return "master";
        return null;
    }

    private String clean(String value)
    {
        return value == null ? "" : Text.removeTags(value).trim();
    }

    private static final class CapturedPage
    {
        private final String title;
        private final String tab;
        private final List<AccountSnapshot.CollectionLogItemSnapshot> items;

        private CapturedPage(String title, String tab, List<AccountSnapshot.CollectionLogItemSnapshot> items)
        {
            this.title = title;
            this.tab = tab;
            this.items = items;
        }
    }

    public static final class CaptureResult
    {
        private final String pageTitle;
        private final int pageItems;
        private final int totalPages;
        private final int totalItems;

        private CaptureResult(String pageTitle, int pageItems, int totalPages, int totalItems)
        {
            this.pageTitle = pageTitle;
            this.pageItems = pageItems;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public String getPageTitle() { return pageTitle; }
        public int getPageItems() { return pageItems; }
        public int getTotalPages() { return totalPages; }
        public int getTotalItems() { return totalItems; }
    }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;

/** Client-thread-only observed rewards, not historical page imports. */
final class CollectionUnlockSync
{
    static final class Unlock
    {
        int itemId;
        String name;
        long observedAt;
        Unlock(String name, long at) { this.name = name; observedAt = at; }
    }
    interface Sender { void send(List<Unlock> items, BiConsumer<Boolean,String> done); }
    private final Map<String, Unlock> pending = new LinkedHashMap<>();
    private final Consumer<List<Unlock>> persist;
    private long generation, readyAt, nextSendAt;
    private boolean busy;
    private int failures;

    CollectionUnlockSync(Consumer<List<Unlock>> persist) { this.persist = persist; }
    static String chatName(ChatMessageType type, String message)
    {
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM) return "";
        String clean = clean(message), prefix = "New item added to your collection log: ";
        return clean.startsWith(prefix) ? validName(clean.substring(prefix.length())) : "";
    }
    static String popupName(String title, String message)
    {
        String clean = clean(message);
        return clean(title).equalsIgnoreCase("Collection log") && clean.startsWith("New item:")
            ? validName(clean.substring("New item:".length())) : "";
    }
    static String clean(String value) { return value == null ? "" : Text.removeTags(value).replace('\u00a0', ' ').trim(); }
    static String validName(String value)
    {
        String name = clean(value);
        return name.isEmpty() || name.length() > 80 || name.matches(".*[\\x00-\\x1f<>].*") ? "" : name;
    }
    static String key(String name) { return name.toLowerCase(Locale.ROOT); }
    void reset(List<Unlock> saved, long now)
    {
        generation++; pending.clear(); busy = false; failures = 0; nextSendAt = 0; readyAt = now + 1800;
        for (Unlock item : saved)
        {
            if (item != null && !validName(item.name).isEmpty() && item.observedAt >= now - 7 * 86400000L
                && item.observedAt <= now + 300000 && pending.size() < 40)
            {
                if (item.itemId < 0 || item.itemId > 500000) item.itemId = 0;
                pending.putIfAbsent(key(item.name), item);
            }
        }
    }
    void observe(String name, long now)
    {
        name = validName(name);
        if (name.isEmpty() || pending.containsKey(key(name)) || pending.size() >= 40) return;
        pending.put(key(name), new Unlock(name, now)); readyAt = now + 1800; save();
    }
    List<Unlock> items() { return new ArrayList<>(pending.values()); }
    void resolve(String name, int id)
    {
        Unlock item = pending.get(key(name));
        if (item != null && item.itemId == 0 && id > 0 && id <= 500000) { item.itemId = id; save(); }
    }
    private void save() { persist.accept(items()); }
    void tick(long now, Sender sender)
    {
        if (pending.values().removeIf(item -> item.observedAt < now - 7 * 86400000L)) save();
        if (busy || now < Math.max(readyAt, nextSendAt)) return;
        List<Unlock> batch = new ArrayList<>();
        for (Unlock item : pending.values()) if (item.itemId > 0) batch.add(item);
        if (batch.isEmpty()) return;
        long revision = generation; busy = true; nextSendAt = now + 10000;
        sender.send(batch, (ok, error) -> {
            if (revision != generation) return;
            busy = false;
            if (!Boolean.TRUE.equals(ok))
            {
                failures = Math.min(5, failures + 1);
                long delay = Math.min(300000L, 15000L * (1L << failures));
                java.util.regex.Matcher retry = java.util.regex.Pattern.compile("Retry after (\\d+) seconds", java.util.regex.Pattern.CASE_INSENSITIVE).matcher(error == null ? "" : error);
                if (retry.find())
                {
                    try { delay = Math.max(delay, Math.min(86400L, Long.parseLong(retry.group(1))) * 1000); }
                    catch (NumberFormatException ignored) { /* Keep bounded backoff. */ }
                }
                nextSendAt = System.currentTimeMillis() + delay; return;
            }
            failures = 0;
            for (Unlock item : batch) if (pending.get(key(item.name)) == item) pending.remove(key(item.name));
            save();
        });
    }
}

package com.hcimprogression.companion;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.ButtonGroup;
import javax.swing.JPanel;
import javax.swing.JToggleButton;

/** Only the selected page participates in layout; no giant blank tab heights. */
final class CompanionSidebarDeck extends JPanel
{
    private final JPanel content = new JPanel(new BorderLayout());
    private final JPanel navigation = new JPanel(new GridLayout(1,0,4,0));
    private final ButtonGroup group = new ButtonGroup();
    private final Map<String, JPanel> pages = new LinkedHashMap<>();
    private final Map<String, JToggleButton> buttons = new LinkedHashMap<>();
    CompanionSidebarDeck()
    {
        super(new BorderLayout(0,10)); setOpaque(false); SidebarControls.stretch(this);
        content.setOpaque(false); navigation.setOpaque(false);
        add(navigation,BorderLayout.NORTH); add(content,BorderLayout.CENTER);
    }
    void page(String name, JPanel page)
    {
        pages.put(name,page);
        JToggleButton button = new JToggleButton(name);
        button.setUI(new javax.swing.plaf.basic.BasicToggleButtonUI()); button.setContentAreaFilled(false); button.setOpaque(true);
        button.setBackground(SidebarControls.SURFACE); button.setForeground(Color.LIGHT_GRAY);
        button.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
        button.setName("page-" + name); button.setFont(SidebarControls.FONT.deriveFont(11f)); button.setFocusPainted(false);
        button.setPreferredSize(new Dimension(1,32)); button.setToolTipText("Show " + name);
        button.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(SidebarControls.LINE),BorderFactory.createEmptyBorder(6,2,6,2)));
        group.add(button); buttons.put(name,button); navigation.add(button);
        button.addActionListener(event -> showPage(name));
        if (pages.size() == 1) showPage(name);
    }
    void showPage(String name)
    {
        if (!pages.containsKey(name)) return;
        content.removeAll(); content.add(pages.get(name), BorderLayout.NORTH);
        buttons.forEach((key, button) -> {
            boolean selected = key.equals(name); button.setSelected(selected);
            button.setBackground(selected ? new Color(81,66,35) : SidebarControls.SURFACE);
            button.setForeground(selected ? SidebarControls.GOLD : Color.LIGHT_GRAY);
        });
        revalidate(); repaint();
    }
}

