    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN) packingDirty = true;
        if (pendingBarrowsRewardTicks > 0 && event.getContainerId() == InventoryID.TRAIL_REWARDINV
            && client.getTopLevelInterfaceId() == InterfaceID.BARROWS_REWARD)
        {
            captureBarrowsReward(event.getItemContainer());
        }
        if (event.getContainerId() == InventoryID.TRAIL_REWARDINV
            && client.getTopLevelInterfaceId() == InterfaceID.TRAIL_REWARDSCREEN
            && config.weeklyLootTrackingEnabled())
        {
            // Do not depend on chat ordering. Stage a generic source here and
            // allow the clue-completion line to replace it with the exact tier.
            beginClueRewardCapture("Clue Scroll");
        }

        if (event.getContainerId() == InventoryID.BANK)
        {
            if (slayerPreparation != null) slayerPreparation.bankChanged(event.getItemContainer());
            if (client.getTopLevelInterfaceId() == InterfaceID.BANKMAIN) capturePersonalBank(event.getItemContainer());
        }

        if (event.getContainerId() == InventoryID.INV_GROUP_TEMP
            && client.getTopLevelInterfaceId() == InterfaceID.SHARED_BANK)
        {
            captureGroupStorage(event.getItemContainer());
        }

        if (event.getContainerId() != InventoryID.WORN)
        {
            return;
        }

        socialPresenceService.updateWornEquipment(event.getItemContainer());
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.QUESTSCROLL_SPEEDRUN && config.personalBestSyncEnabled()) questPbReadTicks = 5;
        if (event.getGroupId() == InterfaceID.BARROWS_REWARD)
        {
            // Match RuneLite's widget capture, with a bounded retry window if
            // the container or chest-count varp arrives later. Withdrawing
            // items is not a new reward and must not arm another capture.
            pendingBarrowsRewardTicks = BARROWS_REWARD_CAPTURE_TICKS;
            captureBarrowsReward(client.getItemContainer(InventoryID.TRAIL_REWARDINV));
        }

        if (event.getGroupId() == InterfaceID.TRAIL_REWARDSCREEN
            && config.weeklyLootTrackingEnabled())
        {
            // Some clients deliver the widget before the reward inventory and
            // others do the reverse. Both paths now share one capture window.
            beginClueRewardCapture("Clue Scroll");
        }

        if (event.getGroupId() == InterfaceID.BANKMAIN)
        {
            if (slayerPreparation != null) slayerPreparation.bankChanged(client.getItemContainer(InventoryID.BANK));
            capturePersonalBank(client.getItemContainer(InventoryID.BANK));
        }

        if (event.getGroupId() == InterfaceID.SHARED_BANK)
        {
            captureGroupStorage(client.getItemContainer(InventoryID.INV_GROUP_TEMP));
        }
    }

