    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            if (panel != null) SwingUtilities.invokeLater(panel::showLoggedOut);
            return;
        }

        // Resolve the character before any sync/poll can use a previous link.
        updateActiveAccountLink(currentPlayerName());
        refreshFeedbackSession();
        if (slayerPreparation != null) slayerPreparation.tick();
        handlePersonalBests(System.currentTimeMillis());
        handleCollectionUnlocks();

        if (pendingBarrowsRewardTicks > 0)
        {
            pendingBarrowsRewardTicks--;
            if (client.getTopLevelInterfaceId() == InterfaceID.BARROWS_REWARD)
            {
                captureBarrowsReward(client.getItemContainer(InventoryID.TRAIL_REWARDINV));
            }
            else pendingBarrowsRewardTicks = 0;
        }

        if (packingDirty && routeHelper != null)
        {
            packingDirty = false;
            ItemContainer inventory = client.getItemContainer(InventoryID.INV);
            boolean enabled = config.routineRoutesEnabled() && config.livePackingChecksEnabled();
            routeHelper.carriedItems(enabled ? CarriedItemSnapshot.capture(itemManager, inventory, client.getItemContainer(InventoryID.WORN))
                : java.util.Collections.emptyMap(), enabled && inventory != null);
        }

        if (!pendingClueRewardSource.isEmpty() && pendingClueRewardTicks > 0 && --pendingClueRewardTicks == 0)
        {
            capturePendingClueReward(client.getItemContainer(InventoryID.TRAIL_REWARDINV));
            // Do not allow an empty or closed reward container to leak into the
            // next casket and mislabel its contents.
            pendingClueRewardSource = "";
        }

        boolean birdhousesChanged = birdhouseTracker != null && birdhouseTracker.update(client);
        long birdhouseNow = System.currentTimeMillis();
        if (birdhousesChanged && birdhouseNow - lastBirdhouseSyncAt >= BIRDHOUSE_SYNC_COOLDOWN_MILLIS && !deviceToken().isEmpty())
        {
            lastBirdhouseSyncAt = birdhouseNow;
            // Birdhouse readiness is handled by the timer scheduler. The
            // snapshot refresh itself must not replay account-gain alerts.
            requestAutomaticAccountSync(false);
        }
        if (farmRunTracker != null && farmRunTracker.update(client))
        {
            farmRunSyncPending = true;
        }
        handleProgressionFeedback(birdhouseNow);
        if (farmRunSyncPending
            && birdhouseNow - lastFarmRunSyncAt >= FARM_RUN_SYNC_COOLDOWN_MILLIS
            && !deviceToken().isEmpty())
        {
            farmRunSyncPending = false;
            lastFarmRunSyncAt = birdhouseNow;
            requestFarmingAccountSync();
        }
        String slayerFingerprint = client.getVarpValue(VarPlayerID.SLAYER_TARGET) + ":"
            + client.getVarpValue(VarPlayerID.SLAYER_COUNT) + ":"
            + client.getVarbitValue(VarbitID.SLAYER_POINTS) + ":"
            + client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
        boolean slayerInitialized = !lastSlayerFingerprint.isEmpty();
        boolean slayerChanged = slayerInitialized && !slayerFingerprint.equals(lastSlayerFingerprint);
        lastSlayerFingerprint = slayerFingerprint;
        if (slayerChanged && birdhouseNow - lastSlayerSyncAt >= SLAYER_SYNC_COOLDOWN_MILLIS && !deviceToken().isEmpty())
        {
            lastSlayerSyncAt = birdhouseNow;
            requestAutomaticAccountSync();
        }

        if (config.automaticAccountSyncEnabled() && !deviceToken().isEmpty())
        {
            if (tickCounter == 0)
            {
                String progressFingerprint = progressFingerprint();
                if (lastProgressFingerprint.isEmpty())
                {
                    lastProgressFingerprint = progressFingerprint;
                    requestAutomaticAccountSync(false);
                }
                else if (!progressFingerprint.equals(lastProgressFingerprint))
                {
                    lastProgressFingerprint = progressFingerprint;
                    requestAutomaticAccountSync();
                }
            }

            handleAutomaticAccountSync(birdhouseNow);
        }
        else
        {
            automaticAccountSyncDirty = false;
            automaticAccountSyncNotificationEligible = false;
            automaticAccountSyncDebounceTicks = 0;
            lastProgressFingerprint = "";
        }

        handlePendingGroupStorage();
        handlePendingPersonalBank();

        tickCounter++;
        if (tickCounter < BASE_SYNC_TICKS) return;
        tickCounter = 0;

        PlayerState state = locationService.createPlayerState(client);
        if (state == null) return;
        String playerName = state.getPlayerName() == null ? "Unknown" : state.getPlayerName();
        updateActiveAccountLink(playerName);

        if (panel != null)
        {
            SwingUtilities.invokeLater(() -> {
                if (config.locationSharingEnabled()) panel.showSharingEnabled();
                else panel.showSharingDisabled();
                panel.updatePlayerInformation(
                    playerName, state.getWorld(), state.getRegionId(),
                    state.getX(), state.getY(), state.getPlane()
                );
            });
        }

        String token = deviceToken();
        if (token.isEmpty()) return;

        syncClanEventsIfVisible(token);

        long now = System.currentTimeMillis();
        if (now >= nextClanSyncAt && clanBackoff.canAttempt(now))
        {
            syncClanPresence(token);
        }

        syncLivePresence(token, state, now);
    }

    private void requestAutomaticAccountSync()
    {
        requestAutomaticAccountSync(true);
    }

    private void resetCollectionUnlocks()
    {
        if (collectionUnlockSync != null) collectionUnlockSync.reset(java.util.Collections.emptyList(), System.currentTimeMillis());
        collectionUnlockSync = null; collectionUnlockBinding = ""; collectionPopupStarted = false;
    }

    private boolean collectionConnection()
    {
        if (client.getGameState() != GameState.LOGGED_IN || !config.automaticAccountSyncEnabled()
            || deviceToken().isEmpty() || !"STANDARD".equals(PersonalBestCapture.mode(client, configManager)))
        {
            if (collectionUnlockSync != null) collectionUnlockSync.reset(java.util.Collections.emptyList(), System.currentTimeMillis());
            collectionUnlockSync = null; collectionUnlockBinding = ""; return false;
        }
        String profile = configManager.getRSProfileKey(), token = deviceToken(), api = config.apiBaseUrl();
        String binding = profile + ":" + client.getAccountHash() + ":" + token + ":" + api;
        if (!binding.equals(collectionUnlockBinding))
        {
            if (collectionUnlockSync != null) collectionUnlockSync.reset(java.util.Collections.emptyList(), System.currentTimeMillis());
            collectionUnlockBinding = binding; collectionItemSearchCursor = 0; collectionItemSearchRetryAt = 0;
            final String ownerProfile = profile;
            collectionUnlockSync = new CollectionUnlockSync(items -> {
                if (ownerProfile.equals(configManager.getRSProfileKey()))
                    configManager.setRSProfileConfiguration(HcimProgressionCompanionConfig.GROUP, "pendingCollectionUnlocks", gson.toJson(items));
            });
            List<CollectionUnlockSync.Unlock> saved = java.util.Collections.emptyList();
            try
            {
                CollectionUnlockSync.Unlock[] rows = gson.fromJson(configManager.getRSProfileConfiguration(
                    HcimProgressionCompanionConfig.GROUP, "pendingCollectionUnlocks"), CollectionUnlockSync.Unlock[].class);
                if (rows != null) saved = java.util.Arrays.asList(rows);
            }
            catch (RuntimeException invalid) { logger.debug("Ignoring invalid pending collection events"); }
            collectionUnlockSync.reset(saved, System.currentTimeMillis());
        }
        return true;
    }

    private void observeCollectionUnlock(String name)
    {
        if (name.isEmpty() || !collectionConnection()) return;
        collectionUnlockSync.observe(name, System.currentTimeMillis());
        collectionItemSearchCursor = 0; collectionItemSearchRetryAt = 0;
        requestAutomaticAccountSync();
    }

    private void handleCollectionUnlocks()
    {
        if (!collectionConnection()) return;
        List<CollectionUnlockSync.Unlock> pending = collectionUnlockSync.items();
        if (pending.isEmpty()) return;
        // Cached price search covers tradeables; inventory covers most new
        // untradeables. Only unresolved rewards scan definitions incrementally,
        // never the scene or a full item database every tick.
        for (CollectionUnlockSync.Unlock item : pending)
        {
            if (item.itemId != 0) continue;
            for (net.runelite.http.api.item.ItemPrice price : itemManager.search(item.name))
                if (item.name.equalsIgnoreCase(price.getName())) { collectionUnlockSync.resolve(item.name, price.getId()); break; }
        }
        for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN, InventoryID.BANK})
        {
            ItemContainer container = client.getItemContainer(containerId);
            if (container == null) continue;
            for (net.runelite.api.Item item : container.getItems()) if (item != null && item.getId() > 0)
                resolveCollectionItem(item.getId());
        }
        long now = System.currentTimeMillis();
        if (pending.stream().anyMatch(item -> item.itemId == 0) && now >= collectionItemSearchRetryAt)
        {
            int end = Math.min(Math.min(client.getItemCount(), 500000), collectionItemSearchCursor + 256);
            long deadline = System.nanoTime() + 2000000L;
            while (collectionItemSearchCursor < end && System.nanoTime() < deadline) resolveCollectionItem(collectionItemSearchCursor++);
            if (collectionItemSearchCursor >= client.getItemCount()) { collectionItemSearchCursor = 0; collectionItemSearchRetryAt = now + 60000; }
        }
        String name = currentPlayerName(), token = deviceToken(), api = config.apiBaseUrl();
        collectionUnlockSync.tick(now, (items, done) -> syncService.syncCollectionUnlocks(api, token, name, items,
            (ok, error) -> clientThread.invokeLater(() -> done.accept(ok, error))));
    }

    private void resolveCollectionItem(int id)
    {
        net.runelite.api.ItemComposition definition = itemManager.getItemComposition(id);
        if (definition != null && definition.getMembersName() != null && definition.getNote() == -1 && definition.getPlaceholderTemplateId() == -1)
            collectionUnlockSync.resolve(definition.getMembersName(), id);
    }

    private void handlePersonalBests(long now)
    {
        if (personalBestSync == null) return;
        if (!config.personalBestSyncEnabled())
        {
            personalBestSync.tick(now); showPersonalBestStatus(personalBestSync.status()); return;
        }
        String binding = configManager.getRSProfileKey() + ":" + client.getAccountHash() + ":" + net.runelite.client.config.RuneScapeProfileType.getCurrent(client);
        if (!binding.equals(personalBestProfileBinding) || now >= nextPersonalBestProfileCheckAt)
        {
            personalBestProfileBinding = binding;
            personalBestWorldMode = PersonalBestCapture.mode(client, configManager);
            nextPersonalBestProfileCheckAt = now + 30_000L;
        }
        String mode = personalBestWorldMode;
        if (mode.isEmpty())
        {
            personalBestSync.reset(); showPersonalBestStatus("Waiting for matching RS profile"); return;
        }
        String token = deviceToken();
        if (token.isEmpty()) { personalBestSync.reset(); showPersonalBestStatus("Link this character first"); return; }
        personalBestSync.connection(currentPlayerName(), token, config.apiBaseUrl(), configManager.getRSProfileKey() + ":" + mode);
        if (questPbReadTicks > 0)
        {
            --questPbReadTicks;
            if (questPbReadTicks < 4 && mode.equals("QUEST_SPEEDRUNNING") && captureQuestPersonalBest()) questPbReadTicks = 0;
        }
        if (personalBestsDirty || now >= nextPersonalBestReadAt)
        {
            personalBestsDirty = false; nextPersonalBestReadAt = now + 30_000L;
            personalBestSync.offer(PersonalBestCapture.read(configManager, mode), now);
        }
        personalBestSync.tick(now); showPersonalBestStatus(personalBestSync.status());
    }

    private void showPersonalBestStatus(String status)
    {
        if (status.equals(lastPersonalBestStatus)) return;
        lastPersonalBestStatus = status;
        SwingUtilities.invokeLater(() -> { if (panel != null) panel.showPersonalBestStatus(status); });
    }

    private boolean captureQuestPersonalBest()
    {
        net.runelite.api.widgets.Widget title = client.getWidget(InterfaceID.QuestscrollSpeedrun.QUEST_TITLE);
        net.runelite.api.widgets.Widget best = client.getWidget(InterfaceID.QuestscrollSpeedrun.BEST_TEXT);
        net.runelite.api.widgets.Widget time = client.getWidget(InterfaceID.QuestscrollSpeedrun.TIME_TEXT);
        if (title == null || best == null || time == null) return false;
        long milliseconds = PersonalBestCapture.parseTime(best.getText());
        int chatAge = client.getTickCount() - questPbChatTick;
        if (chatAge >= 0 && chatAge <= 5) milliseconds = PersonalBestCapture.parseTime(time.getText());
        if (milliseconds <= 0) return false;
        String heading = title.getText().replaceAll("<[^>]+>|@[^@]+@", " ").toLowerCase(Locale.ROOT);
        String quest = java.util.Arrays.stream(Quest.values()).map(Quest::getName)
            .sorted(java.util.Comparator.comparingInt(String::length).reversed())
            .filter(name -> heading.contains(name.toLowerCase(Locale.ROOT))).findFirst().orElse("");
        String key = "quest " + quest.toLowerCase(Locale.ROOT);
        if (quest.isEmpty() || !PersonalBestCapture.validKey(key)) return false;
        long previous = PersonalBestCapture.milliseconds(configManager.getRSProfileConfiguration(PersonalBestCapture.QUEST_GROUP, key));
        if (previous == 0 || milliseconds < previous)
            configManager.setRSProfileConfiguration(PersonalBestCapture.QUEST_GROUP, key, java.math.BigDecimal.valueOf(milliseconds, 3).toPlainString());
        personalBestsDirty = true;
        return true;
    }

    private void requestAutomaticAccountSync(boolean notificationEligible)
    {
        if (!config.automaticAccountSyncEnabled())
        {
            return;
        }

        automaticAccountSyncDirty = true;
        automaticAccountSyncNotificationEligible |= notificationEligible;
        automaticAccountSyncDebounceTicks = AUTOMATIC_ACCOUNT_SYNC_DEBOUNCE_TICKS;
    }

    private void requestFarmingAccountSync()
    {
        automaticAccountSyncDirty = true;
        // Farm-ready notifications come from their saved timer schedules, so
        // a patch-state upload should remain silent for account-gain alerts.
        automaticAccountSyncDebounceTicks = 5;
    }

    private void handleAutomaticAccountSync(long now)
    {
        if (!automaticAccountSyncDirty || accountSyncInFlight)
        {
            return;
        }
        if (automaticAccountSyncDebounceTicks > 0)
        {
            automaticAccountSyncDebounceTicks--;
            return;
        }
        if (now - lastAutomaticAccountSyncAt < AUTOMATIC_ACCOUNT_SYNC_COOLDOWN_MILLIS)
        {
            return;
        }

        boolean notificationEligible = automaticAccountSyncNotificationEligible;
        automaticAccountSyncDirty = false;
        automaticAccountSyncNotificationEligible = false;
        lastAutomaticAccountSyncAt = now;
        syncAccountNow(false, false, notificationEligible);
    }

    private String accountSnapshotFingerprintKey(String playerName, String token)
    {
        return ACCOUNT_SNAPSHOT_FINGERPRINT_KEY_PREFIX
            + accountKey(playerName)
            + "."
            + AccountSnapshotFingerprint.linkKey(token);
    }

    private static long parseRetryAfter(String message)
    {
        if (message == null) return 0L;
        Matcher matcher = RETRY_AFTER_PATTERN.matcher(message);
        if (!matcher.find()) return 0L;
        try
        {
            return Math.max(1L, Long.parseLong(matcher.group(1)));
        }
        catch (NumberFormatException ignored)
        {
            return 0L;
        }
    }

    private String progressFingerprint()
    {
        StringBuilder fingerprint = new StringBuilder(512);
        for (net.runelite.api.Skill skill : net.runelite.api.Skill.values())
        {
            if (skill == net.runelite.api.Skill.OVERALL)
            {
                continue;
            }
            // XP changes at low levels are frequent and do not need a network
            // snapshot. Track each level transition once a skill is
            // meaningfully progressed; the server expands a multi-level
            // snapshot into one deduplicated notification per level.
            int level = client.getRealSkillLevel(skill);
            // Below 40, the periodic heartbeat is sufficient. Above 40, an
            // exact level transition is retained so no real level-up is
            // silently skipped by two-level bucketing.
            // Opt-in completion feedback includes early progression milestones
            // too. The normal debounce and five-minute upload cap still apply.
            int trackedLevel = level > 40 || config.progressionPopupsEnabled() ? level : 0;
            fingerprint.append(trackedLevel).append('|');
        }

        fingerprint.append(client.getVarpValue(net.runelite.api.VarPlayer.QUEST_POINTS)).append('|')
            .append(client.getVarpValue(net.runelite.api.VarPlayer.CLOG_LOGGED)).append('|')
            .append(client.getVarpValue(net.runelite.api.VarPlayer.CLOG_TOTAL)).append('|');

        for (Quest quest : Quest.values())
        {
            try
            {
                fingerprint.append(quest.getState(client).ordinal());
            }
            catch (RuntimeException ignored)
            {
                fingerprint.append('?');
            }
        }

        int[] diaryVarbits = {
            VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
            VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE,
            VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
            VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE,
            VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
            VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE,
            VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
            VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE,
            VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
            VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE,
            VarbitID.KARAMJA_EASY_COUNT, VarbitID.KARAMJA_MED_COUNT,
            VarbitID.KARAMJA_HARD_COUNT, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE,
            VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
            VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE,
            VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
            VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE,
            VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
            VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE,
            VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
            VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE,
            VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
            VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE,
            VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
            VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE
        };
        for (int varbitId : diaryVarbits)
        {
            fingerprint.append(client.getVarbitValue(varbitId)).append('|');
        }
        return fingerprint.toString();
    }

    private void syncLivePresence(String token, PlayerState state, long now)
    {
        boolean locationEnabled = config.locationSharingEnabled();
        boolean presenceEnabled = config.socialPresenceEnabled();
        if (!presenceEnabled && panel != null)
        {
            SwingUtilities.invokeLater(panel::showSocialPresenceDisabled);
        }
        if (!locationEnabled && !presenceEnabled)
        {
            return;
        }

        SocialPresenceSnapshot presence = presenceEnabled
            ? socialPresenceService.createSnapshot(client, itemManager, locationEnabled)
            : null;
        if (presenceEnabled && presence == null)
        {
            return;
        }

        String fingerprint = liveFingerprint(state, presence, locationEnabled, presenceEnabled);
        boolean changed = !fingerprint.equals(lastLiveFingerprint);
        boolean changeAllowed = changed && now - lastLiveSuccessAt >= LIVE_CHANGE_COOLDOWN_MILLIS;
        if ((!changeAllowed && now < nextLiveSyncAt) || liveSyncInFlight || !liveBackoff.canAttempt(now))
        {
            return;
        }

        liveSyncInFlight = true;
        if (presenceEnabled && panel != null)
        {
            SwingUtilities.invokeLater(() -> panel.showSocialPresenceSyncing(
                presence.getRegionName(), presence.getActivity(),
                presence.getCombatLevel(), presence.getEquipment().size()));
        }

        syncService.syncLive(
            config.apiBaseUrl(), token, state, presence,
            locationEnabled, presenceEnabled, error ->
        {
            liveSyncInFlight = false;
            long completedAt = System.currentTimeMillis();
            if (error == null)
            {
                liveBackoff.recordSuccess();
                lastLiveFingerprint = fingerprint;
                lastLiveSuccessAt = completedAt;
                nextLiveSyncAt = completedAt + LIVE_HEARTBEAT_MILLIS + randomJitter(30_000L);
            }
            else
            {
                nextLiveSyncAt = liveBackoff.recordFailure(completedAt, randomJitter(15_000L));
            }
            SwingUtilities.invokeLater(() -> {
                if (panel == null) return;
                if (locationEnabled)
                {
                    if (error == null) panel.showSyncSuccess();
                    else panel.showSyncError(error);
                }
                if (presenceEnabled)
                {
                    if (error == null) panel.showSocialPresenceSuccess();
                    else panel.showSocialPresenceError(error);
                }
            });
        });
    }

    private String liveFingerprint(
        PlayerState state,
        SocialPresenceSnapshot presence,
        boolean locationEnabled,
        boolean presenceEnabled)
