    private void syncClanPresence(String token)
    {
        long now = System.currentTimeMillis();
        if (!config.socialClanSyncEnabled())
        {
            nextClanSyncAt = now + CLAN_HEARTBEAT_MILLIS;
            if (panel != null) SwingUtilities.invokeLater(panel::showClanRosterDisabled);
            return;
        }
        if (clanSyncInFlight)
        {
            return;
        }

        SocialClanSnapshot clanSnapshot = socialClanService.createSnapshot(client);
        if (clanSnapshot == null)
        {
            nextClanSyncAt = now + (5 * 60_000L);
            return;
        }

        if (config.clanSkillWeekSyncEnabled() && latestAccountSnapshot != null)
        {
            syncService.syncClanSkillWeek(config.apiBaseUrl(), token, clanSnapshot.getClanName(), latestAccountSnapshot, error -> {
                if (error != null) logger.debug("Clan Skill of the Week sync failed: {}", error);
            });
        }

        String fingerprint = clanFingerprint(clanSnapshot);
        if (fingerprint.equals(lastClanFingerprint))
        {
            nextClanSyncAt = now + CLAN_HEARTBEAT_MILLIS + randomJitter(60_000L);
            return;
        }
        clanChangeCooldown.recordAttempt(now);
        clanSyncInFlight = true;
        syncService.syncSocialClan(config.apiBaseUrl(), token, clanSnapshot, error -> {
            clanSyncInFlight = false;
            long completedAt = System.currentTimeMillis();
            if (error == null)
            {
                clanBackoff.recordSuccess();
                lastClanFingerprint = fingerprint;
                nextClanSyncAt = completedAt + CLAN_HEARTBEAT_MILLIS + randomJitter(60_000L);
            }
            else
            {
                long retryAt = clanBackoff.recordFailure(completedAt, randomJitter(30_000L));
                nextClanSyncAt = clanChangeCooldown.nextAllowedAt(completedAt, retryAt);
            }
            SwingUtilities.invokeLater(() -> {
                if (panel == null) return;
                if (error == null)
                {
                    panel.showClanRosterSuccess(clanSnapshot.getMembers().size());
                }
                else
                {
                    panel.showClanRosterError(error);
                }
            });
            if (error != null)
            {
                logger.debug("Social clan roster sync failed: {}", error);
            }
        });
    }

    private void scheduleClanChangeSync()
    {
        long now = System.currentTimeMillis();
        long scheduledAt = clanChangeCooldown.nextAllowedAt(now, clanBackoff.getRetryAtMillis());
        if (nextClanSyncAt <= 0L || scheduledAt < nextClanSyncAt)
        {
            nextClanSyncAt = scheduledAt;
        }
    }

    private String clanFingerprint(SocialClanSnapshot snapshot)
    {
        StringBuilder value = new StringBuilder()
            .append(snapshot.getClanName()).append('|')
            .append(snapshot.getPlayerRank());
        for (SocialClanSnapshot.ClanMemberSnapshot member : snapshot.getMembers())
        {
            value.append('|').append(member.getName())
                .append(':').append(member.getRank())
                .append(':').append(member.getWorld())
                .append(':').append(member.isOnline());
        }
        return value.toString();
    }

    private long randomJitter(long maximumMillis)
    {
        if (maximumMillis <= 0L)
        {
            return 0L;
        }
        return ThreadLocalRandom.current().nextLong(maximumMillis + 1L);
    }

    private void syncClanEventsIfVisible(String token)
    {
        if (!config.socialClanEventsSyncEnabled())
        {
            clanEventsWidgetOpen = false;
            lastClanEventsFingerprint = "";
            if (panel != null) SwingUtilities.invokeLater(panel::showClanEventsDisabled);
            return;
        }

        SocialClanEventSnapshot snapshot = socialClanEventService.createSnapshot(client);
        if (snapshot == null)
        {
            if (clanEventsWidgetOpen)
            {
                clanEventsWidgetOpen = false;
                // Reopening the interface should always force one fresh import,
                // even when the visible rows have not changed.
                lastClanEventsFingerprint = "";
            }
            return;
        }

        boolean newlyOpened = !clanEventsWidgetOpen;
        clanEventsWidgetOpen = true;
        String fingerprint = snapshot.fingerprint();
        if (clanEventsSyncInFlight || (!newlyOpened && fingerprint.equals(lastClanEventsFingerprint)))
        {
            return;
        }

        clanEventsSyncInFlight = true;
        int eventCount = snapshot.getEvents().size();
        if (panel != null)
        {
            SwingUtilities.invokeLater(() -> panel.showClanEventsSyncing(eventCount));
        }

        syncService.syncClanEvents(config.apiBaseUrl(), token, snapshot, error -> {
            clanEventsSyncInFlight = false;
            if (error == null)
            {
                lastClanEventsFingerprint = fingerprint;
            }
            SwingUtilities.invokeLater(() -> {
                if (panel == null) return;
                if (error == null)
                {
                    panel.showClanEventsSuccess(eventCount);
                }
                else
                {
                    panel.showClanEventsError(error);
                }
            });
            if (error != null)
            {
                logger.debug("Clan event import failed: {}", error);
            }
        });
    }

    private String deviceToken()
    {
        String key = activePlayerKey == null ? "" : activePlayerKey;
        if (key.isEmpty())
        {
            return "";
        }
        String value = configManager.getConfiguration(HcimProgressionCompanionConfig.GROUP, TOKEN_KEY_PREFIX + key);
        if (value == null || value.trim().isEmpty())
        {
            String legacyName = configManager.getConfiguration(HcimProgressionCompanionConfig.GROUP, DISPLAY_NAME_KEY);
            String legacyToken = configManager.getConfiguration(HcimProgressionCompanionConfig.GROUP, TOKEN_KEY);
            if (key.equals(accountKey(legacyName)) && legacyToken != null && !legacyToken.trim().isEmpty())
            {
                value = legacyToken.trim();
                configManager.setConfiguration(HcimProgressionCompanionConfig.GROUP, TOKEN_KEY_PREFIX + key, value);
                configManager.setConfiguration(HcimProgressionCompanionConfig.GROUP, DISPLAY_NAME_KEY_PREFIX + key, legacyName);
            }
        }
        return value == null ? "" : value.trim();
    }

    private String currentPlayerName()
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return "";
        }
        String name = client.getLocalPlayer().getName();
        return name == null ? "" : name.trim();
    }

    private String accountKey(String playerName)
    {
        if (playerName == null)
        {
            return "";
        }
        return playerName.replace('\u00a0', ' ')
            .trim()
            .toLowerCase(Locale.ROOT)
            .replaceAll("[^a-z0-9]+", "_")
            .replaceAll("^_+|_+$", "");
    }

    private void refreshFeedbackSession()
    {
        String packingName = currentPlayerName();
        if (!packingName.equals(packingCharacter)) { packingCharacter = packingName; packingDirty = true; }
        if (sessionGoals != null) sessionGoals.session(packingName);
        if (sessionGoals != null) sessionGoals.connection(packingName,deviceToken(),config.apiBaseUrl());
        if (routeHelper != null && routeHelper.session(
            client.getGameState() == GameState.LOGGED_IN ? currentPlayerName() : "", deviceToken(), config.apiBaseUrl())) packingDirty = true;
        progressionFeedback.categories(config.questCompletionPopups(), config.diaryCompletionPopups(), config.milestoneCompletionPopups());
        String name = currentPlayerName();
        String token = deviceToken();
        String session = feedbackRunning && !name.isEmpty()
            ? accountKey(name) + ":" + token + ":" + config.apiBaseUrl()
                + ":" + config.progressionPopupsEnabled() + ":" + config.pinnedGoalEnabled()
                + ":" + config.routineRemindersEnabled()
            : "";
        long revision = progressionFeedback.session(session);
        if (revision != feedbackRevision)
        {
            feedbackRevision = revision;
            nextGoalPollAt = 0L;
            goalPollInFlight = false;
            goalPollFailures = 0;
            nextRoutineCheckAt = 0L;
            routineReminderTracker.reset();
            goalReadStatus = "Waiting to check your pinned website task.";
        }
    }

    private void handleProgressionFeedback(long now)
    {
        if (sessionGoals != null) sessionGoals.tick(now);
        progressionFeedback.muted(sessionGoals != null && sessionGoals.muted(now));
        if (config.routineRemindersEnabled() && now >= nextRoutineCheckAt)
        {
            nextRoutineCheckAt = now + 10_000L;
            for (String message : routineReminderTracker.observe(
                birdhouseTracker == null ? null : birdhouseTracker.timeTrackingSnapshot(),
                farmRunTracker == null ? null : farmRunTracker.timeTrackingSnapshot(), now / 1000L))
            {
                progressionFeedback.routine(message);
            }
        }
        String popup = progressionFeedback.tick(now, config.progressionPopupSeconds());
        ProgressionFeedback.View view = progressionFeedback.view(now);
        boolean notify = view.routinePopup
            ? config.routineRemindersEnabled() && config.routineDesktopNotifications()
            : config.progressionPopupsEnabled() && config.progressionDesktopNotifications();
        if (!popup.isEmpty() && notify)
        {
            notifier.notify("Progression Path: " + popup + (view.routinePopup ? "" : " — complete!"));
        }
        updateFeedbackPanel();
        if (!config.pinnedGoalEnabled() || !progressionFeedback.current(feedbackRevision)
            || deviceToken().isEmpty() || goalPollInFlight || now < nextGoalPollAt) return;
        goalPollInFlight = true;
        goalReadStatus = "Checking the website for this character's pinned task…";
        nextGoalPollAt = now + 60_000L;
        final long revision = feedbackRevision;
        final String token = deviceToken();
        final String name = currentPlayerName();
        syncService.fetchPinnedGoal(config.apiBaseUrl(), token, name, (goal, error) ->
            clientThread.invokeLater(() -> {
                refreshFeedbackSession();
                if (!progressionFeedback.current(revision) || !token.equals(deviceToken())
                    || !accountKey(name).equals(accountKey(currentPlayerName()))) return;
                goalPollInFlight = false;
                progressionFeedback.goal(revision, error == null ? goal : null, System.currentTimeMillis());
                if (error != null)
                {
                    goalPollFailures = Math.min(4, goalPollFailures + 1);
                    long retryAfter = parseRetryAfter(error) * 1000L;
                    nextGoalPollAt = System.currentTimeMillis() + Math.max(retryAfter, 60_000L * (1L << goalPollFailures));
                    goalReadStatus = "Pinned task unavailable. Retrying in "
                        + Math.max(1, (nextGoalPollAt - System.currentTimeMillis()) / 60_000L) + " min.";
                    logger.debug("Pinned goal refresh failed; backing off");
                }
                else
                {
                    goalPollFailures = 0;
                    goalReadStatus = goal == null ? "No task pinned. Use Pin next task in RuneLite on your website dashboard."
                        : (!goal.activity && goal.done >= goal.total ? "Completed: " : "Pinned: ") + ProgressionFeedback.clean(goal.title);
                }
                updateFeedbackPanel();
            }));
    }

    private void previewRoutineReminder()
    {
        clientThread.invokeLater(() -> {
            if (!feedbackRunning || client.getGameState() != GameState.LOGGED_IN || !config.routineRemindersEnabled()) return;
            refreshFeedbackSession();
            progressionFeedback.routine("Test reminder — your real farm and birdhouse timers have not been changed.");
        });
    }

    private void updateFeedbackPanel()
    {
        if (panel == null) return;
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
        boolean completions = config.progressionPopupsEnabled(), auto = config.automaticAccountSyncEnabled();
        boolean pinned = config.pinnedGoalEnabled(), routines = config.routineRemindersEnabled();
        String status = !loggedIn ? "Log into RuneScape to use the in-game displays."
            : !pinned ? "Pin a task on the website, then set Account tracking to On (or enable Pinned website goal under Advanced: sync)."
            : deviceToken().isEmpty() ? "Link this character to the website to display its pinned task." : goalReadStatus;
        String fingerprint = completions + ":" + auto + ":" + pinned + ":" + routines + ":" + loggedIn + ":" + status
            + ":" + progressionFeedback.recentRevision();
        if (fingerprint.equals(lastFeedbackPanelStatus)) return;
        lastFeedbackPanelStatus = fingerprint;
        HcimProgressionCompanionPanel currentPanel = panel;
        java.util.List<ProgressionFeedback.Recent> recent = progressionFeedback.recent();
        SwingUtilities.invokeLater(() -> {
            if (panel == currentPanel && fingerprint.equals(lastFeedbackPanelStatus))
            {
                currentPanel.showProgressionDisplays(completions, auto, pinned, routines, loggedIn, status);
                currentPanel.showRecentCompletions(recent);
            }
        });
    }

    private void updateActiveAccountLink(String playerName)
    {
        String key = accountKey(playerName);
        if (key.equals(activePlayerKey))
        {
            return;
        }
        activePlayerKey = key;
        if (slayerPreparation != null) slayerPreparation.reset("Character link changed. Select Start task again.");
        pendingBarrowsRewardTicks = 0;
        if (birdhouseTracker != null) birdhouseTracker.reset();
        if (farmRunTracker != null) farmRunTracker.reset();
        automaticAccountSyncDirty = false;
        automaticAccountSyncNotificationEligible = false;
        automaticAccountSyncDebounceTicks = 0;
        lastProgressFingerprint = "";
        lastSlayerFingerprint = "";
        collectionLogCaptureService.reset();
        pendingGroupStorageSnapshot = null;
        groupStorageDirty = false;
        pendingPersonalBankSnapshot = null;
        personalBankDirty = false;
        lastLiveFingerprint = "";
        lastClanFingerprint = "";
        lastClanEventsFingerprint = "";
        liveBackoff.reset();
        clanBackoff.reset();
        if (panel == null)
        {
            return;
        }
        String token = deviceToken();
        HcimProgressionCompanionPanel currentPanel = panel;
        if (token.isEmpty())
        {
            SwingUtilities.invokeLater(() -> {
                if (panel == currentPanel) currentPanel.showUnlinked(playerName);
            });
            return;
        }
        String linkedName = configManager.getConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            DISPLAY_NAME_KEY_PREFIX + key
        );
        String shownName = linkedName == null || linkedName.trim().isEmpty() ? playerName : linkedName;
        SwingUtilities.invokeLater(() -> {
            if (panel == currentPanel) currentPanel.showLinked(shownName);
        });
    }

