package com.hcimprogression.companion;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;

/** Bounded, session-scoped presentation state. No game or network work here. */
final class ProgressionFeedback
{
    static final long POPUP_MILLIS = 8_000L;
    private String session = "";
    private long generation;
    private boolean baseline;
    private final Set<String> seen = new LinkedHashSet<>();
    private final Queue<Popup> pending = new ArrayDeque<>();
    private final ArrayDeque<Recent> recent = new ArrayDeque<>();
    private long recentRevision;
    private boolean quests = true, diaries = true, milestones = true;
    private String popup = "";
    private String popupCategory = "";
    private long popupStarted;
    private long popupUntil;
    private boolean routinePopup;
    private boolean muted;
    private Goal goal;
    private long goalUntil;

    synchronized long session(String next)
    {
        if (!session.equals(next))
        {
            session = next;
            generation++;
            baseline = false;
            seen.clear();
            pending.clear();
            recent.clear();
            recentRevision++;
            popup = "";
            goal = null;
        }
        return generation;
    }

    synchronized boolean current(long revision)
    {
        return !session.isEmpty() && revision == generation;
    }

    synchronized void baseline(long revision)
    {
        if (current(revision)) baseline = true;
    }

    synchronized void accept(long revision, boolean eligible, List<Event> events)
    {
        if (!current(revision)) return;
        boolean announce = baseline && eligible;
        baseline = true;
        if (events == null) return;
        int count = 0;
        for (Event event : events)
        {
            if (++count > 20) break;
            if (event == null || event.id == null || event.id.length() > 160) continue;
            String title = clean(event.title);
            if (title.isEmpty() || !seen.add(event.id)) continue;
            if (seen.size() > 512) seen.remove(seen.iterator().next());
            if (announce)
            {
                String category = category(event.id);
                recent.addFirst(new Recent(title, category, System.currentTimeMillis()));
                if (recent.size() > 10) recent.removeLast();
                recentRevision++;
                if (!muted && enabled(category) && pending.size() < 8) pending.add(new Popup(title, false, category));
            }
        }
    }

    /** Local presentation filters; changing them never replays or resets completion history. */
    synchronized void categories(boolean quests, boolean diaries, boolean milestones)
    {
        this.quests = quests;
        this.diaries = diaries;
        this.milestones = milestones;
        pending.removeIf(value -> !value.routine && !enabled(value.category));
        if (!routinePopup && !enabled(popupCategory)) popup = "";
    }

    private boolean enabled(String category)
    {
        return "Quest".equals(category) ? quests : "Diary".equals(category) ? diaries : milestones;
    }

    private static String category(String id)
    {
        return id.startsWith("quest:") ? "Quest" : id.startsWith("diary:") ? "Diary" : "Milestone";
    }

    synchronized List<Recent> recent() { return Collections.unmodifiableList(new ArrayList<>(recent)); }
    synchronized long recentRevision() { return recentRevision; }

    synchronized void routine(String message)
    {
        String text = clean(message);
        if (!muted && !session.isEmpty() && !text.isEmpty() && pending.size() < 8) pending.add(new Popup(text, true, "Routine"));
    }

    synchronized void muted(boolean next)
    {
        muted = next;
        if (muted) { pending.clear(); popup = ""; }
    }

    synchronized void goal(long revision, Goal next, long now)
    {
        if (!current(revision)) return;
        if (next == null || clean(next.title).isEmpty() || (!next.activity && next.total < 1) || next.total < 0 || next.total > 40)
        {
            goal = null;
            return;
        }
        goal = new Goal(clean(next.title), Math.max(0, Math.min(next.done, next.total)), next.total);
        goal.activity = next.activity;
        goalUntil = now + 90_000L;
    }

    /** Advances only on game ticks; the overlay just reads an immutable view. */
    synchronized String tick(long now)
    {
        return tick(now, 8);
    }

    synchronized String tick(long now, int seconds)
    {
        if (muted) return "";
        if (now < popupUntil && !popup.isEmpty()) return "";
        Popup next = pending.poll();
        popup = next == null ? "" : next.text;
        popupCategory = next == null ? "" : next.category;
        routinePopup = next != null && next.routine;
        popupStarted = now;
        popupUntil = now + Math.max(3, Math.min(20, seconds)) * 1000L;
        return popup;
    }

    synchronized View view(long now)
    {
        return new View(now < goalUntil ? goal : null, now < popupUntil ? popup : "", routinePopup, popupCategory,
            popupStarted, popupUntil);
    }

    static String clean(String value)
    {
        if (value == null) return "";
        String text = value.replaceAll("[<>\\p{Cntrl}]", " ").replaceAll("\\s+", " ").trim();
        return text.substring(0, Math.min(text.length(), 100));
    }

    static final class Event
    {
        String id;
        String title;
        Event(String id, String title) { this.id = id; this.title = title; }
    }

    static final class Goal
    {
        String title;
        int done;
        int total;
        boolean activity;
        Goal(String title, int done, int total) { this.title = title; this.done = done; this.total = total; }
    }

    static final class Response
    {
        boolean ok;
        Goal goal;
        List<Event> completions = Collections.emptyList();
    }

    static final class View
    {
        final Goal goal;
        final String popup;
        final boolean routinePopup;
        final String popupCategory;
        final long popupStarted;
        final long popupUntil;
        View(Goal goal, String popup, boolean routinePopup, String popupCategory, long popupStarted, long popupUntil)
        {
            this.goal = goal;
            this.popup = popup;
            this.routinePopup = routinePopup;
            this.popupCategory = popupCategory;
            this.popupStarted = popupStarted;
            this.popupUntil = popupUntil;
        }

        boolean questPopup() { return !routinePopup && "Quest".equals(popupCategory) && !popup.isEmpty(); }
    }

    private static final class Popup
    {
        final String text;
        final boolean routine;
        final String category;
        Popup(String text, boolean routine, String category) { this.text = text; this.routine = routine; this.category = category; }
    }

    static final class Recent
    {
        final String title;
        final String category;
        final long completedAt;
        Recent(String title, String category, long completedAt)
        {
            this.title = title;
            this.category = category;
            this.completedAt = completedAt;
        }
    }

    static List<String> wrap(String text, int columns)
    {
        List<String> lines = new ArrayList<>();
        String remaining = clean(text);
        while (remaining.length() > columns)
        {
            int end = remaining.lastIndexOf(' ', columns);
            if (end <= 0) end = columns;
            lines.add(remaining.substring(0, end));
            remaining = remaining.substring(end).trim();
        }
        if (!remaining.isEmpty()) lines.add(remaining);
        return lines;
    }
}

package com.hcimprogression.companion;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

final class ProgressionOverlay extends OverlayPanel
{
    private final ProgressionFeedback feedback;
    private final HcimProgressionCompanionConfig config;
    private final Client client;
    private final RoutineRouteHelper routes;
    private final SessionGoalHelper skills;
    private static final Color GOLD = new Color(235, 194, 93);

    ProgressionOverlay(HcimProgressionCompanionPlugin plugin, ProgressionFeedback feedback,
        HcimProgressionCompanionConfig config, Client client, RoutineRouteHelper routes, SessionGoalHelper skills)
    {
        super(plugin);
        this.feedback = feedback;
        this.config = config;
        this.client = client;
        this.routes = routes;
        this.skills = skills;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(240, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN) return null;
        ProgressionFeedback.View view = feedback.view(System.currentTimeMillis());
        boolean muted = skills != null && skills.muted(System.currentTimeMillis());
        boolean popup = !muted && !view.questPopup() && !view.popup.isEmpty()
            && (view.routinePopup ? config.routineRemindersEnabled() : config.progressionPopupsEnabled());
        boolean goal = config.pinnedGoalEnabled() && view.goal != null;
        RoutineRouteHelper.View route = routes == null ? null : routes.view();
        SessionGoalHelper.View skill = skills == null ? null : skills.view();
        if (!popup && !goal && route == null && skill == null) return null;
        panelComponent.getChildren().clear();
        boolean compact = config.compactProgressionOverlay();
        panelComponent.setPreferredSize(new Dimension(compact ? 220 : 240, 0));
        if (!compact) panelComponent.getChildren().add(TitleComponent.builder().text("Progression Path").color(GOLD).build());
        if (popup)
        {
            line(view.routinePopup ? "Routine ready to check" : view.popupCategory + " complete!", Color.GREEN);
            wrapped(view.popup);
        }
        if (goal)
        {
            line(view.goal.activity ? "Your pinned activity" : view.goal.done == view.goal.total ? "Pinned task complete" : "Your pinned task", GOLD);
            wrapped(view.goal.title);
            if (!view.goal.activity) line(view.goal.done + " / " + view.goal.total + " steps", Color.LIGHT_GRAY);
        }
        if (route != null) {
            line(route.title, GOLD);
            wrapped(route.text);
            if (!route.packing.isEmpty()) wrapped(route.packing);
            if (!compact) line("Use Route Helper: Back / Next", Color.LIGHT_GRAY);
        }
        if (skill != null)
        {
            line(skill.complete ? (!muted && System.currentTimeMillis() < skill.popupUntil ? "Skill goal complete!" : "Completed skill goal") : "Your skill goal", skill.complete ? Color.GREEN : GOLD);
            wrapped(skill.title); wrapped(skill.progress);
            ProgressBarComponent bar = new ProgressBarComponent();
            bar.setMaximum(100); bar.setValue(skill.percent); bar.setForegroundColor(skill.complete ? Color.GREEN : GOLD);
            bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
            bar.setCenterLabel(skill.percentage);
            panelComponent.getChildren().add(bar);
        }
        return super.render(graphics);
    }

    private void wrapped(String text)
    {
        for (String part : ProgressionFeedback.wrap(text, 27)) line(part, Color.WHITE);
    }

    private void line(String text, Color color)
    {
        panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(color).build());
    }
}

package com.hcimprogression.companion;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.FontManager;

/** Original vector artwork. No network, sprites, game access, or per-frame layout rebuilds. */
final class QuestCompletionBanner
{
    static final int MIN_WIDTH = 220;
    private static final int TEXT_X = 76;
    private static final int RIGHT_PAD = 20;
    private static final Color GOLD = new Color(230, 191, 105);
    private static final Color GREEN = new Color(138, 229, 167);
    private static final Font TITLE = FontManager.getRunescapeBoldFont();
    private static final Font LABEL = FontManager.getRunescapeSmallFont();
    private String cachedTitle = "";
    private int cachedWidth;
    private List<String> lines = Collections.emptyList();

    Dimension render(Graphics2D graphics, String title, int width, long started, long until, long now)
    {
        if (width < MIN_WIDTH) throw new IllegalArgumentException("Quest banner is too narrow");
        // A private graphics context preserves the caller's font, clip, composite and stroke.
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setFont(TITLE);
            FontMetrics metrics = g.getFontMetrics();
            if (!cachedTitle.equals(title) || cachedWidth != width)
            {
                cachedTitle = title;
                cachedWidth = width;
                lines = wrap(title, metrics, width - TEXT_X - RIGHT_PAD);
            }
            int lineHeight = metrics.getHeight();
            int height = Math.max(94, 76 + lines.size() * lineHeight);
            g.setComposite(AlphaComposite.SrcOver.derive(opacity(started, until, now)));
            g.setColor(new Color(0, 0, 0, 95));
            g.fillRoundRect(3, 8, width - 6, height - 8, 12, 12);
            g.setPaint(new GradientPaint(0, 6, new Color(35, 47, 38, 245), width, height,
                new Color(15, 20, 19, 245)));
            g.fillRoundRect(1, 4, width - 4, height - 9, 10, 10);
            g.setColor(new Color(161, 129, 65));
            g.drawRoundRect(1, 4, width - 4, height - 9, 10, 10);
            g.setColor(new Color(230, 191, 105, 40));
            g.drawRoundRect(5, 8, width - 12, height - 17, 7, 7);
            g.setColor(GOLD);
            g.drawLine(16, 4, 46, 4);
            g.drawLine(width - 48, 4, width - 18, 4);

            crest(g, height / 2);
            g.setFont(LABEL);
            shadowText(g, "QUEST COMPLETE", TEXT_X, 26, GOLD);
            g.setFont(TITLE);
            int baseline = 35 + metrics.getAscent();
            for (String line : lines)
            {
                shadowText(g, line, TEXT_X, baseline, new Color(247, 239, 214));
                baseline += lineHeight;
            }
            g.setFont(LABEL);
            shadowText(g, "PROGRESSION PATH", TEXT_X, height - 18, new Color(149, 170, 145));
            g.setColor(new Color(71, 79, 59));
            g.fillRect(TEXT_X, height - 12, width - TEXT_X - RIGHT_PAD, 2);
            g.setColor(GOLD);
            g.fillRect(TEXT_X, height - 12,
                (int) Math.round((width - TEXT_X - RIGHT_PAD) * remaining(started, until, now)), 2);
            return new Dimension(width, height);
        }
        finally
        {
            g.dispose();
        }
    }

    private static void shadowText(Graphics2D g, String text, int x, int y, Color color)
    {
        g.setColor(new Color(0, 0, 0, 190));
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }

    private static void crest(Graphics2D g, int y)
    {
        g.setPaint(new GradientPaint(16, y - 24, new Color(62, 86, 53), 62, y + 24, new Color(17, 35, 28)));
        g.fillOval(15, y - 25, 48, 48);
        g.setColor(GOLD);
        g.drawOval(15, y - 25, 48, 48);
        g.setColor(new Color(230, 191, 105, 65));
        g.drawOval(19, y - 21, 40, 40);
        // A small parchment and emerald check: intentionally independent of game assets.
        g.setColor(new Color(215, 199, 157));
        g.fillRoundRect(30, y - 15, 18, 24, 3, 3);
        g.setColor(new Color(116, 94, 56));
        g.drawLine(34, y - 9, 43, y - 9);
        g.drawLine(34, y - 4, 43, y - 4);
        Path2D check = new Path2D.Float();
        check.moveTo(35, y + 6);
        check.lineTo(40, y + 11);
        check.lineTo(51, y - 1);
        g.setStroke(new BasicStroke(4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(new Color(16, 43, 28));
        g.draw(check);
        g.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(GREEN);
        g.draw(check);
        g.setStroke(new BasicStroke(1));
    }

    static float opacity(long started, long until, long now)
    {
        if (until <= started || now < started || now >= until) return 0;
        return (float) Math.max(0, Math.min(1, Math.min((now - started) / 250.0, (until - now) / 450.0)));
    }

    static double remaining(long started, long until, long now)
    {
        if (until <= started) return 0;
        return Math.max(0, Math.min(1, (double) (until - now) / (until - started)));
    }

    /** Pixel-measured wrapping, including unusually long words; titles are never truncated. */
    static List<String> wrap(String title, FontMetrics metrics, int width)
    {
        List<String> output = new ArrayList<>();
        String text = ProgressionFeedback.clean(title);
        while (!text.isEmpty())
        {
            if (metrics.stringWidth(text) <= width)
            {
                output.add(text);
                break;
            }
            int end = 0;
            int space = -1;
            for (int offset = 0; offset < text.length();)
            {
                int next = offset + Character.charCount(text.codePointAt(offset));
                if (metrics.stringWidth(text.substring(0, next)) > width) break;
                if (text.charAt(offset) == ' ') space = offset;
                end = next;
                offset = next;
            }
            if (space > 0) end = space;
            if (end == 0) end = Character.charCount(text.codePointAt(0));
            output.add(text.substring(0, end));
            text = text.substring(end).trim();
        }
        return output;
    }
}

package com.hcimprogression.companion;

import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/** A separate toast, so a quest celebration never shifts pinned goals or skill bars. */
final class QuestCompletionOverlay extends Overlay
{
    private final Client client;
    private final ProgressionFeedback feedback;
    private final HcimProgressionCompanionConfig config;
    private final SessionGoalHelper skills;
    private final QuestCompletionBanner banner = new QuestCompletionBanner();

    QuestCompletionOverlay(HcimProgressionCompanionPlugin plugin, Client client, ProgressionFeedback feedback,
        HcimProgressionCompanionConfig config, SessionGoalHelper skills)
    {
        super(plugin);
        this.client = client;
        this.feedback = feedback;
        this.config = config;
        this.skills = skills;
        setPosition(OverlayPosition.TOP_CENTER);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        long now = System.currentTimeMillis();
        ProgressionFeedback.View view = feedback.view(now);
        if (!visible(view, client.getGameState() == GameState.LOGGED_IN,
            config.progressionPopupsEnabled(), config.questCompletionPopups(), skills != null && skills.muted(now))) return null;
        int width = Math.min(340, client.getViewportWidth() - 20);
        if (width < QuestCompletionBanner.MIN_WIDTH) return null;
        return banner.render(graphics, view.popup, width, view.popupStarted, view.popupUntil, now);
    }

    static boolean visible(ProgressionFeedback.View view, boolean loggedIn, boolean enabled, boolean quests, boolean muted)
    {
        return loggedIn && enabled && quests && !muted && view.questPopup();
    }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Local-only edge detection over character-scoped Time Tracking snapshots. */
final class RoutineReminderTracker
{
    private final Map<String, Timer> timers = new HashMap<>();

    void reset() { timers.clear(); }

    List<String> observe(BirdhouseSnapshot birdhouses, FarmRunSnapshot farming, long nowSeconds)
    {
        Set<String> observed = new HashSet<>();
        int birds = 0, patches = 0;
        String firstPatch = "";
        if (birdhouses != null)
        {
            for (BirdhouseSnapshot.House house : birdhouses.getHouses())
            {
                if (observed.size() >= 200) break;
                if (changed("bird:" + house.getName(), house.getState(), house.getLastChangedAt(),
                    house.getReadyAt(), nowSeconds, observed)) birds++;
            }
        }
        if (farming != null)
        {
            for (FarmRunSnapshot.Patch patch : farming.getPatches())
            {
                if (observed.size() >= 200) break;
                if ("Compost".equalsIgnoreCase(patch.getType())) continue;
                if (changed("farm:" + patch.getId(), patch.getState(), patch.getLastChangedAt(),
                    patch.getReadyAt(), nowSeconds, observed))
                {
                    patches++;
                    if (firstPatch.isEmpty()) firstPatch = ProgressionFeedback.clean(patch.getLocation() + " " + patch.getType());
                }
            }
        }
        // Missing/disabled tracking data cannot leave an old armed timer alive.
        timers.keySet().retainAll(observed);
        List<String> messages = new ArrayList<>();
        if (birds > 0) messages.add(birds + " birdhouse" + (birds == 1 ? " is" : "s are") + " ready to check. Time for a quick Fossil Island trip!");
        if (patches > 0) messages.add(patches == 1 ? firstPatch + " is ready to check."
            : patches + " tracked farming patches are ready to check. Grab your farming kit!");
        return messages;
    }

    private boolean changed(String id, String state, long cycle, long due, long now, Set<String> observed)
    {
        if (cycle <= 0 || cycle > now + 300 || id.length() > 160) return false;
        observed.add(id);
        Timer previous = timers.get(id);
        boolean growing = "growing".equals(state) && due > now;
        boolean ready = "ready".equals(state) || ("growing".equals(state) && due > 0 && due <= now);
        if (growing)
        {
            if (previous == null || previous.cycle != cycle) timers.put(id, new Timer(cycle, true));
            return false;
        }
        // A ready patch first seen at login is a baseline, not a new alert.
        boolean notify = ready && previous != null && previous.armed;
        timers.put(id, new Timer(cycle, false));
        return notify;
    }

    private static final class Timer
    {
        private final long cycle;
        private final boolean armed;
        private Timer(long cycle, boolean armed) { this.cycle = cycle; this.armed = armed; }
    }
}

package com.hcimprogression.companion;

import com.google.gson.Gson;
import java.awt.Color;
import java.util.HashSet;
import java.util.Set;
import java.util.Collections;
import java.util.Map;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

/** User-driven routine checklist. No scene scans, movement, menus or game input. */
final class RoutineRouteHelper
{
    private final ConfigManager manager;
    private final HcimProgressionCompanionConfig config;
    private final SyncService service;
    private final Gson gson;
    private final ClientThread clientThread;
    private final JPanel panel = SidebarControls.column();
    private final JComboBox<String> kind = new JComboBox<>(new String[]{"Farm run", "Birdhouse run"});
    private final JTextArea items = new JTextArea(6, 18), stops = new JTextArea(7, 18);
    private final JTextArea status = SidebarControls.text("");
    private final JTextArea packing = SidebarControls.text("");
    private final JPanel packingRows = SidebarControls.column();
    private final JButton start = SidebarControls.button("Start route","Start or restart the manual route checklist",true);
    private final JButton next = SidebarControls.button("Next","Next manual route step",false);
    private final JButton back = SidebarControls.button("Back","Previous route step",false);
    private final JButton stop = SidebarControls.button("Stop","Stop this checklist; keep your saved setup",false);
    private Map<String, Long> carried = Collections.emptyMap(); // EDT-owned immutable snapshot.
    private boolean inventoryAvailable;
    private final JButton download = SidebarControls.button("Load route","Load this character's route from the website",false);
    private final JButton upload = SidebarControls.button("Save route","Save this character's route to the website",false);
    private final Set<String> loaded = new HashSet<>();
    private volatile String session = "", name = "", token = "", api = "";
    private volatile long generation;
    private volatile View view;
    private String selectedKind = "farm";
    private volatile String editorSession = "";
    private String editorName = "";
    private RoutineRoutePlan plan = RoutineRoutePlan.defaults("farm");
    private final RoutineRouteRun run = new RoutineRouteRun();
    private boolean busy;

    RoutineRouteHelper(ConfigManager manager, HcimProgressionCompanionConfig config, SyncService service, Gson gson, ClientThread clientThread)
    {
        this.manager = manager; this.config = config; this.service = service; this.gson = gson; this.clientThread = clientThread;
        SidebarControls.field(kind);
        panel.add(kind); SidebarControls.gap(panel); panel.add(status); SidebarControls.gap(panel);
        panel.add(start); SidebarControls.gap(panel); panel.add(SidebarControls.row(back,next,stop)); SidebarControls.gap(panel);
        panel.add(packing); SidebarControls.gap(panel);
        panel.add(SidebarControls.fold("Packing details",SidebarControls.scroll(packingRows,150))); SidebarControls.gap(panel);
        JPanel edit = SidebarControls.column();
        edit.add(SidebarControls.text("Packing list")); edit.add(SidebarControls.editor(items,105)); SidebarControls.gap(edit);
        edit.add(SidebarControls.text("Exact names: Oak logs x 4. Notes stay manual.")); SidebarControls.gap(edit);
        edit.add(SidebarControls.text("Stops · one location | note per line")); edit.add(SidebarControls.editor(stops,125)); SidebarControls.gap(edit);
        JButton local = SidebarControls.button("Save locally","Save this profile's setup without uploading",false); edit.add(local);
        edit.add(SidebarControls.text("Edits apply when you start or restart."));
        panel.add(SidebarControls.fold("Edit route",edit)); SidebarControls.gap(panel);
        JPanel sync = SidebarControls.column(); sync.add(download); SidebarControls.gap(sync); sync.add(upload); SidebarControls.gap(sync);
        sync.add(SidebarControls.text("Needs a linked character and Route setup sync. Load before your first save."));
        panel.add(SidebarControls.fold("Website sync",sync)); SidebarControls.gap(panel);
        panel.add(SidebarControls.fold("How it works",SidebarControls.text("Steps are manual. Check travel unlocks and supply charges yourself. Inventory and worn gear count; notes and bank items do not.")));
        kind.addActionListener(event -> {
            if (!session.isEmpty() && session.equals(editorSession)) saveLocal();
            run.stop(); view = null;
            selectedKind = kind.getSelectedIndex() == 0 ? "farm" : "birdhouse";
            loadLocal(); updateControls();
        });
        local.addActionListener(event -> { if (saveLocal()) message("Saved for this RuneScape profile and character. Website unchanged."); });
        start.addActionListener(event -> {
            if (!config.routineRoutesEnabled()) { message("Set In-game helpers to On in plugin settings, or enable Local route helper under Advanced: helpers."); return; }
            if (!saveLocal()) return;
            run.start(plan); updateView();
        });
        next.addActionListener(event -> {
            if (!run.active()) return;
            run.next();
            if (!run.active()) { view = null; updateControls(); message("Route complete. Timers unchanged."); }
            else updateView();
        });
        back.addActionListener(event -> { if (run.active()) { run.back(); updateView(); } });
        stop.addActionListener(event -> { run.stop(); view = null; updateControls(); message("Route stopped. Setup kept."); });
        download.addActionListener(event -> sync(false)); upload.addActionListener(event -> sync(true));
        items.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent event) { updatePacking(); }
            public void removeUpdate(DocumentEvent event) { updatePacking(); }
            public void changedUpdate(DocumentEvent event) { updatePacking(); }
        });
        loadLocal();
    }

    JPanel panel() { return panel; }

    /** Called on the client thread. Stale EDT and network work is generation-guarded. */
    boolean session(String nextName, String nextToken, String nextApi)
    {
        String next = nextName.isEmpty() ? "" : nextName + ":" + nextToken + ":" + nextApi;
        name = nextName; token = nextToken; api = nextApi;
        if (next.equals(session)) return false;
        session = next; long revision = ++generation; view = null;
        SwingUtilities.invokeLater(() -> {
            if (revision != generation) return;
            editorSession = session; editorName = name;
            run.stop(); busy = false; carried = Collections.emptyMap(); inventoryAvailable = false;
            loaded.clear(); kind.setEnabled(true); download.setEnabled(true); upload.setEnabled(true); loadLocal();
        });
        return true;
    }
    void reset() { session("", "", ""); }
    private String key() { return "route_" + editorName.toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9]", "_") + "_" + selectedKind; }

    private void loadLocal()
    {
        plan = RoutineRoutePlan.defaults(selectedKind);
        if (!session.isEmpty()) {
            try {
                RoutineRoutePlan saved = gson.fromJson(manager.getRSProfileConfiguration("hcimprogression.routes", key()), RoutineRoutePlan.class);
                if (saved != null && selectedKind.equals(saved.kind) && saved.valid()) plan = saved;
            } catch (RuntimeException ignored) { /* Keep safe local defaults for malformed legacy data. */ }
        }
        items.setText(session.isEmpty() ? "" : plan.items); stops.setText(session.isEmpty() ? "" : plan.stops);
        items.setEnabled(!session.isEmpty()); stops.setEnabled(!session.isEmpty());
        updatePacking();
        updateControls(); message(session.isEmpty() ? "Log in to use your route." : "Choose a route, then Start when ready.");
    }
    private boolean saveLocal()
    {
        if (session.isEmpty() || !session.equals(editorSession)) { message("Character changed. Wait for this character’s route to load."); return false; }
        RoutineRoutePlan next = new RoutineRoutePlan(selectedKind, items.getText(), stops.getText(), plan.revision);
        if (!next.valid()) { message("Use 1–24 stops and up to 32 items, at most 160 characters per line."); return false; }
        plan = next; manager.setRSProfileConfiguration("hcimprogression.routes", key(), gson.toJson(plan)); return true;
    }
    private void sync(boolean save)
    {
        if (busy) return;
        if (!config.routineRoutesSyncEnabled() || session.isEmpty() || !session.equals(editorSession) || token.isEmpty()) { message("Link this character and set Account tracking to On, or enable Route setup sync under Advanced: sync. Local routes work offline."); return; }
        if (save && !loaded.contains(selectedKind)) { message("Load from website once before uploading, so newer saved edits are not overwritten."); return; }
        if (save && !saveLocal()) return;
        if (!save && (!items.getText().equals(plan.items) || !stops.getText().equals(plan.stops))
            && JOptionPane.showConfirmDialog(panel, "Load the website route and replace unsaved editor changes?", "Load route", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION) return;
        long revision = generation; String expectedSession = session, selected = selectedKind;
        RoutineRoutePlan sending = new RoutineRoutePlan(selected, plan.items, plan.stops, plan.revision);
        String expectedName = name, expectedToken = token, expectedApi = api;
        String originalItems = items.getText(), originalStops = stops.getText();
        busy = true; kind.setEnabled(false); download.setEnabled(false); upload.setEnabled(false); message(save ? "Saving route to website…" : "Loading website route…");
        clientThread.invokeLater(() -> {
            if (revision != generation || !expectedSession.equals(session) || !config.routineRoutesSyncEnabled()) {
                SwingUtilities.invokeLater(() -> { if (revision == generation) { busy = false; kind.setEnabled(true); download.setEnabled(true); upload.setEnabled(true); message("Route sync cancelled."); } }); return;
            }
            service.syncRoutineRoute(expectedApi, expectedToken, expectedName, selected, save ? sending : null, (result, error) -> SwingUtilities.invokeLater(() -> {
                if (revision != generation || !expectedSession.equals(session)) return;
                busy = false; kind.setEnabled(true); download.setEnabled(true); upload.setEnabled(true);
                if (!config.routineRoutesSyncEnabled()) { message("Route sync disabled. Local route kept."); return; }
                if (error != null) { message(error); return; }
                loaded.add(selected);
                if (!selected.equals(selectedKind)) { message("Route synced. Select that route again to review it."); return; }
                if (save) { plan.revision = result.revision; saveLocal(); message("Saved to this character’s website route."); }
                else {
                    if (!originalItems.equals(items.getText()) || !originalStops.equals(stops.getText())) {
                        loaded.remove(selected); message("You edited during loading. Those changes were kept; load again when ready."); return;
                    }
                    plan = result == null ? RoutineRoutePlan.defaults(selected) : result;
                    items.setText(plan.items); stops.setText(plan.stops); saveLocal(); run.stop(); view = null; updateControls();
                    message(result == null ? "No website route yet. Edit this starter setup and Save to website." : "Website route loaded. Review packing items, then Start route.");
                }
            }));
        });
    }
    private void updateView()
    {
        if (!run.active() || !session.equals(editorSession)) { view = null; return; }
        view = new View(run.title(), run.text(), activePackingSummary());
        updateControls(); message(run.position() < 0 ? "Check packing, then Next to begin." : run.title() + "\n" + run.text());
    }
    View view() { return config.routineRoutesEnabled() && !session.isEmpty() && session.equals(editorSession) ? view : null; }
    void carriedItems(Map<String, Long> snapshot, boolean available)
    {
        long revision = generation;
        SwingUtilities.invokeLater(() -> {
            if (revision != generation || !session.equals(editorSession)) return;
            carried = snapshot; inventoryAvailable = available; updatePacking();
        });
    }
    private void updatePacking()
    {
        if (!config.livePackingChecksEnabled() || !config.routineRoutesEnabled() || session.isEmpty() || !session.equals(editorSession))
        {
            packing.setText("Packing checks off"); packingRows.removeAll();
            packingRows.add(SidebarControls.text("Set In-game helpers to On for routes and packing checks. Individual choices are under Advanced: helpers."));
        }
        else
        {
            PackingChecklist.Result result = PackingChecklist.check(items.getText(), carried, inventoryAvailable);
            packing.setText(result.summary); packingRows.removeAll();
            for (PackingChecklist.Row row : result.rows)
            {
                JTextArea entry = SidebarControls.text(row.item + "\n" + row.status);
                entry.setForeground(row.state == PackingChecklist.State.READY ? new Color(104,211,145)
                    : row.state == PackingChecklist.State.MISSING ? new Color(246,173,85) : SidebarControls.MUTED);
                packingRows.add(entry); SidebarControls.gap(packingRows);
            }
        }
        packingRows.revalidate(); packingRows.repaint();
        if (run.active() && session.equals(editorSession)) view = new View(run.title(), run.text(), activePackingSummary());
    }
    private String activePackingSummary()
    {
        return config.livePackingChecksEnabled() && run.position() < 0
            ? PackingChecklist.check(run.packingItems(), carried, inventoryAvailable).summary : "";
    }
    private void updateControls()
    {
        start.setText(run.active()?"Restart route":"Start route");
        back.setEnabled(run.active()); next.setEnabled(run.active()); stop.setEnabled(run.active());
    }
    private void message(String text)
    {
        status.setText(String.valueOf(text));
    }
    static final class View {
        final String title, text, packing;
        View(String title, String text, String packing) { this.title = title; this.text = text; this.packing = packing; }
    }
}

package com.hcimprogression.companion;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/** Plain user-authored checklist data; never game input, coordinates or code. */
final class RoutineRoutePlan
{
    String kind;
    String items;
    String stops;
    int revision;

    RoutineRoutePlan(String kind, String items, String stops, int revision)
    {
        this.kind = kind; this.items = items; this.stops = stops; this.revision = revision;
    }

    static List<String> lines(String value)
    {
        return Arrays.stream((value == null ? "" : value).split("\\r?\\n"))
            .map(line -> line.replaceAll("[<>\\p{Cntrl}]", " ").trim())
            .filter(line -> !line.isEmpty()).collect(Collectors.toList());
    }

    boolean valid()
    {
        return ("farm".equals(kind) || "birdhouse".equals(kind)) && revision >= 0
            && items != null && items.length() <= 2400 && stops != null && stops.length() <= 3200
            && lines(items).size() <= 32 && !lines(stops).isEmpty() && lines(stops).size() <= 24
            && lines(items).stream().allMatch(line -> line.length() <= 160)
            && lines(stops).stream().allMatch(line -> line.length() <= 160);
    }

    static RoutineRoutePlan defaults(String kind)
    {
        if ("farm".equals(kind)) return new RoutineRoutePlan(kind,
            "Spade\nSeed dibber unless bare-handed planting unlocked\nRake unless patches stay weed-free\n4 herb seeds of your choice\n4 ultracompost uses or charged bottomless compost bucket\nMagic secateurs if owned\nYour chosen teleports",
            "Falador herb patch | Travel from Falador\nCatherby herb patch | Travel from Catherby\nArdougne herb patch | Travel from Ardougne\nHosidius herb patch | Use your unlocked travel method", 0);
        return new RoutineRoutePlan("birdhouse",
            "Hammer\nChisel\n4 logs matching your Hunter and Crafting levels\n40 low-level hop seeds\n4 clockworks for the first run; reuse returned clockworks on repeats\nDigsite pendant if Fossil Island teleport unlocked",
            "Verdant Valley east | Fossil Island pendant then unlocked Mushtree\nVerdant Valley west | Walk to the other birdhouse\nMushroom Meadow north | Use unlocked Mushtree\nTar Swamp entrance | Walk south to the final birdhouse", 0);
    }

    static final class Response { boolean ok; RoutineRoutePlan plan; }
}

package com.hcimprogression.companion;

import java.util.List;

/** Pure, manual checklist state. Completion never changes game timers or progress. */
final class RoutineRouteRun
{
    private RoutineRoutePlan plan;
    private int position = -1;
    boolean start(RoutineRoutePlan next)
    {
        if (next == null || !next.valid()) return false;
        plan = new RoutineRoutePlan(next.kind, next.items, next.stops, next.revision);
        position = -1; return true;
    }
    boolean active() { return plan != null; }
    int position() { return position; }
    String packingItems() { return plan == null ? "" : plan.items; }
    void stop() { plan = null; position = -1; }
    void next() { if (plan != null && ++position >= RoutineRoutePlan.lines(plan.stops).size()) stop(); }
    void back() { if (plan != null) position = Math.max(-1, position - 1); }
    String title()
    {
        if (plan == null) return "";
        return ("farm".equals(plan.kind) ? "Farm run" : "Birdhouse run")
            + (position < 0 ? " · packing" : " · " + (position + 1) + "/" + RoutineRoutePlan.lines(plan.stops).size());
    }
    String text()
    {
        if (plan == null) return "";
        List<String> entries = RoutineRoutePlan.lines(position < 0 ? plan.items : plan.stops);
        return position < 0 ? "Review the packing list in Route Helper, then Next." : entries.get(position);
    }
}

