/** Width-constrained sidebar widgets. Never reads or operates the game. */
final class SidebarControls
{
    static final Color MUTED = new Color(164,173,184), GOLD = new Color(235,194,93);
    static final Color SURFACE = new Color(29,33,39), INPUT = new Color(22,25,30), LINE = new Color(54,61,71);
    static final Font FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
    static JPanel column()
    {
        JPanel result = new JPanel()
        {
            @Override public Dimension getMaximumSize()
            {
                // BoxLayout's empty maximum height is zero. Do not freeze that
                // value before controls are added; nested cards would disappear.
                return new Dimension(Integer.MAX_VALUE,getPreferredSize().height);
            }
        };
        result.setOpaque(false);
        result.setLayout(new BoxLayout(result,BoxLayout.Y_AXIS)); stretch(result); return result;
    }
    static void stretch(JComponent component)
    {
        component.setAlignmentX(0f);
        component.setMinimumSize(new Dimension(0,component.getMinimumSize().height));
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE,component.getMaximumSize().height));
    }
    static void gap(JPanel panel) { panel.add(Box.createVerticalStrut(6)); }
    static JButton button(String title, String tooltip, boolean primary)
    {
        JButton result = new JButton(title); stretch(result);
        result.setUI(new javax.swing.plaf.basic.BasicButtonUI());
        result.setFont(FONT.deriveFont(11f)); result.setToolTipText(tooltip);
        result.setMaximumSize(new Dimension(Integer.MAX_VALUE,30)); result.setPreferredSize(new Dimension(1,30));
        result.setMargin(new Insets(3,4,3,4)); result.setFocusPainted(false);
        result.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        result.setForeground(Color.WHITE); result.setBackground(primary ? new Color(45,100,76) : new Color(39,45,54));
        result.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(primary ? new Color(71,143,109) : LINE),BorderFactory.createEmptyBorder(4,4,4,4)));
        return result;
    }
    static JPanel row(JComponent... controls)
    {
        JPanel result = new JPanel(new GridLayout(1,controls.length,4,0)); result.setOpaque(false); stretch(result);
        result.setMaximumSize(new Dimension(Integer.MAX_VALUE,30));
        for (JComponent control : controls) result.add(control); return result;
    }
    static JTextArea text(String value)
    {
        JTextArea result = new WrappedText(); result.setText(value); result.setEditable(false); result.setFocusable(false);
        result.setLineWrap(true); result.setWrapStyleWord(true); result.setOpaque(false); result.setForeground(MUTED);
        result.setFont(FONT.deriveFont(11f)); result.setBorder(BorderFactory.createEmptyBorder()); stretch(result); return result;
    }
    static JTextArea heading(String value)
    {
        JTextArea result = text(value); result.setFont(FONT.deriveFont(Font.BOLD, 12f)); result.setForeground(GOLD); return result;
    }
    static JPanel card(String title, JComponent body)
    {
        JPanel result = column(); result.setOpaque(true); result.setBackground(SURFACE);
        result.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),BorderFactory.createEmptyBorder(8,8,8,8)));
        if (!title.isEmpty()) { result.add(heading(title)); gap(result); }
        result.add(body); return result;
    }
    static void field(JComponent field)
    {
        stretch(field); field.setFont(FONT); field.setBackground(INPUT); field.setForeground(Color.WHITE);
        field.setMaximumSize(new Dimension(Integer.MAX_VALUE,30));
        if (field instanceof javax.swing.JTextField)
            field.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),BorderFactory.createEmptyBorder(4,6,4,6)));
    }
    static JScrollPane editor(JTextArea field, int height)
    {
        field.setRows(0); field.setColumns(0); field.setLineWrap(true); field.setWrapStyleWord(true);
        field.setFont(FONT.deriveFont(11f)); field.setForeground(Color.WHITE); field.setCaretColor(Color.WHITE);
        field.setBackground(new Color(36,36,36)); field.setBorder(BorderFactory.createEmptyBorder(5,5,5,5));
        return scroll(field,height);
    }
    static JScrollPane scroll(JComponent body, int height)
    {
        JScrollPane pane = new JScrollPane(body,JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        stretch(pane); pane.setPreferredSize(new Dimension(1,height)); pane.setMinimumSize(new Dimension(0,height));
        pane.setMaximumSize(new Dimension(Integer.MAX_VALUE,height)); pane.setBorder(BorderFactory.createLineBorder(new Color(58,58,58)));
        return pane;
    }
    static Fold fold(String title, JComponent body)
    {
        return new Fold(title, body);
    }
    static final class Fold extends JPanel
    {
        private final JButton toggle;
        private final JComponent body;
        private final JPanel inset = column();
        private final String title;
        Fold(String title, JComponent body)
        {
            super(new BorderLayout()); this.title = title; this.body = body;
            setOpaque(true); setBackground(SURFACE); stretch(this);
            setBorder(BorderFactory.createLineBorder(LINE));
            toggle = button("", "", false); toggle.setHorizontalAlignment(SwingConstants.LEFT);
            toggle.setFont(FONT.deriveFont(Font.BOLD,10f)); toggle.setForeground(GOLD);
            toggle.setName("fold-" + title);
            inset.setBorder(BorderFactory.createEmptyBorder(7,7,8,7)); inset.add(body);
            add(toggle,BorderLayout.NORTH); add(inset,BorderLayout.CENTER);
            toggle.addActionListener(event -> setExpanded(!body.isVisible())); setExpanded(false);
        }
        void setExpanded(boolean value)
        {
            body.setVisible(value); inset.setVisible(value);
            toggle.setText((value ? "▾ " : "▸ ") + title);
            toggle.setToolTipText((value ? "Collapse " : "Expand ") + title); revalidate(); repaint();
        }
    }
    private static final class WrappedText extends JTextArea
    {
        WrappedText()
        {
            // These are labels, not editors. Even a non-focusable JTextArea's
            // default caret scrolls its ancestors when background text changes.
            DefaultCaret stationary = new DefaultCaret()
            {
                @Override protected void adjustVisibility(java.awt.Rectangle bounds)
                {
                    // Display-only updates must never move the user's viewport.
                }
            };
            stationary.setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
            setCaret(stationary);
        }
        @Override public void setText(String value)
        {
            String next = value == null ? "" : value;
            if (getDocument() != null && next.equals(getText())) return;
            super.setText(next);
        }
        @Override public Dimension getPreferredSize()
        {
            if (getUI() == null) return new Dimension(1,16);
            int width = getWidth() > 0 ? getWidth() : getParent() != null && getParent().getWidth() > 0 ? getParent().getWidth() : 190;
            Insets insets = getInsets(); View root = getUI().getRootView(this);
            root.setSize(Math.max(1,width-insets.left-insets.right),Integer.MAX_VALUE);
            return new Dimension(1,(int)Math.ceil(root.getPreferredSpan(View.Y_AXIS))+insets.top+insets.bottom);
        }
        @Override public Dimension getMaximumSize() { return new Dimension(Integer.MAX_VALUE,getPreferredSize().height); }
    }
}

package com.hcimprogression.companion;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import java.util.function.BiConsumer;
import java.util.function.BooleanSupplier;

/** Client-thread state: bounded coalescing, explicit opt-in, immutable upload snapshots. */
final class SkillGoalSync
{
    interface Sender { void send(String name,String token,String api,Goal goal,BiConsumer<Response,String> callback); }
    private final BooleanSupplier enabled;
    private final Sender sender;
    private final Map<String,Goal> pending = new LinkedHashMap<>();
    private String name = "", token = "", api = "", identity = "";
    private long generation, nextSendAt, nextProgressAt;
    private boolean busy;
    private Goal current;
    private String savedId = "";
    private int savedSequence;
    private volatile String status = "Website sync off · goals stay local";

    SkillGoalSync(BooleanSupplier enabled,Sender sender) { this.enabled = enabled; this.sender = sender; }
    boolean connection(String nextName,String nextToken,String nextApi)
    {
        String next = nextName+":"+nextToken+":"+nextApi;
        if (identity.equals(next)) return false;
        generation++; pending.clear(); current = null; savedId = ""; savedSequence = 0; busy = false; nextSendAt = nextProgressAt = 0;
        name = nextName; token = nextToken; api = nextApi; identity = next;
        status = enabled.getAsBoolean() ? "Start a goal to sync this character" : "Website sync off · goals stay local";
        return true;
    }
    void reset() { connection("","",""); }
    Goal snapshot() { return current==null ? null : current.copy(); }
    void restore(Goal saved)
    {
        if (!SavedSkillGoals.valid(saved)) return;
        current=saved.copy(); current.sequence++;
        if ("active".equals(current.status) && current.currentXp>=current.targetXp) current.status="completed";
        // Keep the original website UUID. A stopped website goal stays stopped.
        if (!"stopped".equals(current.status)) request();
    }
    void start(String skill,boolean level,int levelNumber,int xp,int target)
    {
        stop(); current = new Goal(); current.id = UUID.randomUUID().toString(); current.skill = skill;
        current.mode = level ? "level" : "xp"; current.level = level ? levelNumber : null;
        current.startXp = current.currentXp = xp; current.targetXp = target; current.sequence = 1; current.status = "active";
        request();
    }
    void progress(int xp,boolean completed)
    {
        if (current == null || !"active".equals(current.status) || xp == current.currentXp) return;
        if (xp < current.currentXp) { stop(); return; }
        current = current.copy(); current.currentXp = xp; current.sequence++;
        if (completed) { current.status = "completed"; request(); }
    }
    void stop()
    {
        if (current == null || !"active".equals(current.status)) return;
        current = current.copy(); current.status = "stopped"; current.sequence++; enqueue();
    }
    void request()
    {
        if (!enabled.getAsBoolean()) { status = "Set Account tracking to On to sync"; return; }
        if (name.isEmpty() || token.isEmpty()) { status = "Link this character before syncing"; return; }
        if (current == null) { status = "Start a new local goal first"; return; }
        enqueue();
    }
    private void enqueue()
    {
        if (!enabled.getAsBoolean() || name.isEmpty() || token.isEmpty() || current == null) return;
        if (current.id.equals(savedId) && current.sequence <= savedSequence) return;
        if (pending.size() >= 8 && !pending.containsKey(current.id)) { status = "Sync backlog · retry this goal later"; return; }
        pending.put(current.id,current.copy()); status = "Goal queued for website";
    }
    void tick(long now)
    {
        if (!enabled.getAsBoolean()) { pending.clear(); status = "Website sync off · goals stay local"; return; }
        if (name.isEmpty() || token.isEmpty()) return;
        if (current != null && "active".equals(current.status) && now >= nextProgressAt) { enqueue(); nextProgressAt = now + 120_000L; }
        if (busy || pending.isEmpty() || now < nextSendAt) return;
        Goal sending = pending.values().iterator().next().copy(); long revision = generation;
        busy = true; nextSendAt = now + 2000L; status = "Syncing goal…";
        sender.send(name,token,api,sending,(response,error) -> {
            if (revision != generation) return;
            busy = false;
            if (!enabled.getAsBoolean()) { pending.clear(); status = "Website sync off · goals stay local"; return; }
            if (error != null || response == null || !response.ok) { nextSendAt = System.currentTimeMillis()+60_000L; status = "Sync unavailable · goal kept locally"; return; }
            Goal queued = pending.get(sending.id);
            if (current != null && current.id.equals(sending.id)) { savedId = sending.id; savedSequence = sending.sequence; }
            if (queued != null && queued.sequence <= sending.sequence) pending.remove(sending.id);
            if (current != null && current.id.equals(sending.id) && "stopped".equals(response.status))
            { current = current.copy(); current.status = "stopped"; pending.remove(sending.id); }
            status = "stopped".equals(response.status) ? "Stopped on website · local goal unchanged" : "Saved to Journey → Active tasks";
        });
    }
    String status() { return status; }
    static final class Response { boolean ok; String status; int sequence; }
    static final class Goal
    {
        String id,skill,mode,status;
        Integer level;
        int startXp,targetXp,currentXp,sequence;
        Goal copy()
        {
            Goal next = new Goal(); next.id = id; next.skill = skill; next.mode = mode; next.status = status; next.level = level;
            next.startXp = startXp; next.targetXp = targetXp; next.currentXp = currentXp; next.sequence = sequence; return next;
        }
    }
}

package com.hcimprogression.companion;

import net.runelite.api.Experience;
import net.runelite.api.Skill;
import java.util.Locale;

/** Client-thread owned session goal; XP, never boosted levels, proves progress. */
final class SkillSessionGoal
{
    private Skill skill;
    private int start, target, current;
    private boolean announced;

    void start(Skill nextSkill, int currentXp, int targetXp)
    {
        if (nextSkill == null || nextSkill == Skill.OVERALL || currentXp < 0
            || targetXp <= currentXp || targetXp > Experience.MAX_SKILL_XP)
            throw new IllegalArgumentException("Choose a target above your current XP, up to 200 million.");
        skill = nextSkill; start = current = currentXp; target = targetXp; announced = false;
    }

    boolean update(Skill nextSkill, int xp)
    {
        if (skill == null || skill != nextSkill) return false;
        if (xp < current) { clear(); return false; } // Never carry a baseline into reset/other-account XP.
        current = Math.min(Experience.MAX_SKILL_XP, xp);
        if (current >= target && !announced) { announced = true; return true; }
        return false;
    }

    void clear() { skill = null; announced = false; }
    void restore(Skill savedSkill, int startXp, int targetXp, int liveXp)
    {
        start(savedSkill,startXp,targetXp);
        if(liveXp<startXp || liveXp>Experience.MAX_SKILL_XP) { clear(); throw new IllegalArgumentException("Wait for this character's XP to load."); }
        current=liveXp; announced=current>=target; // Login never replays a completion alert.
    }
    Skill skill() { return skill; }
    int startXp() { return start; }
    int targetXp() { return target; }
    int currentXp() { return current; }
    int gained() { return skill == null ? 0 : Math.max(0, current - start); }
    int required() { return skill == null ? 0 : target - start; }
    int remaining() { return skill == null ? 0 : Math.max(0, target - current); }
    double percent() { return skill == null ? 0 : Math.min(100.0, 100.0 * gained() / required()); }
    String percentText()
    {
        // Preserve exact XP for completion. Do not round an unfinished goal up to 100%.
        double rounded = Math.round(percent() * 10.0) / 10.0;
        return String.format(Locale.US, "%.1f%%", complete() ? 100.0 : Math.min(99.9, rounded));
    }
    boolean complete() { return skill != null && current >= target; }

    static int target(int xp, boolean level, int amount)
    {
        if (level)
        {
            if (amount < 2 || amount > Experience.MAX_REAL_LEVEL)
                throw new IllegalArgumentException("Choose a real level from 2 to 99.");
            return Experience.getXpForLevel(amount);
        }
        if (amount < 1 || (long) xp + amount > Experience.MAX_SKILL_XP)
            throw new IllegalArgumentException("Enter a positive XP gain without exceeding 200 million total XP.");
        return xp + amount;
    }
}

package com.hcimprogression.companion;

/** Login establishes a baseline; only a newly observed assignment starts a tracker. */
final class SlayerAssignmentWatch
{
    private String baseline, candidate;
    private boolean noTask;
    private int stableTicks;

    boolean observe(String assignment, int remaining)
    {
        if (baseline == null)
        {
            // Login can deliver an empty task before the real assignment vars.
            // Settle the initial state without treating it as a new assignment.
            String initial = assignment + (remaining > 0 ? ":active" : ":none");
            if (initial.equals(candidate)) stableTicks++;
            else { candidate = initial; stableTicks = 1; }
            if (stableTicks < 2) return false;
            baseline = assignment;
            noTask = remaining <= 0;
            candidate = null;
            stableTicks = 0;
            return false;
        }
        if (remaining <= 0)
        {
            baseline = assignment;
            noTask = true;
            candidate = null;
            stableTicks = 0;
            return false;
        }
        // Count changes, task extensions, point spending and chat reminders alone
        // are not proof of a new assignment. Never restart a stopped current task.
        if (!noTask && baseline.equals(assignment))
        {
            candidate = null;
            stableTicks = 0;
            return false;
        }
        if (assignment.equals(candidate)) stableTicks++;
        else { candidate = assignment; stableTicks = 1; }
        // Assignment vars can arrive separately. Require two settled game ticks.
        if (stableTicks < 2) return false;
        baseline = assignment;
        noTask = false;
        candidate = null;
        stableTicks = 0;
        return true;
    }

    void reset()
    {
        baseline = candidate = null;
        noTask = false;
        stableTicks = 0;
    }
}

