import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;

/** Compact, movable top-left panel for manually started, resumed or new assignments. */
final class SlayerTaskOverlay extends OverlayPanel
{
    private final Client client;
    private final SlayerTaskProgress progress;
    SlayerTaskOverlay(HcimProgressionCompanionPlugin plugin, Client client, SlayerTaskProgress progress)
    {
        super(plugin); this.client = client; this.progress = progress;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(185,0));
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN) return null;
        SlayerTaskProgress.View view = progress.view(System.currentTimeMillis());
        if (view == null) return null;
        panelComponent.getChildren().clear();
        String title = view.task.length() > 27 ? view.task.substring(0,26) + "…" : view.task;
        panelComponent.getChildren().add(LineComponent.builder().left(title).leftColor(SidebarControls.GOLD).build());
        panelComponent.getChildren().add(LineComponent.builder().left(view.remaining == 0 ? "Task complete" : "Task progress")
            .right(view.done + " / " + view.total).leftColor(Color.LIGHT_GRAY).rightColor(Color.WHITE).build());
        ProgressBarComponent bar = new ProgressBarComponent();
        bar.setMaximum(100); bar.setValue(view.percent);
        bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
        bar.setCenterLabel(view.barLabel);
        bar.setForegroundColor(view.remaining == 0 ? new Color(104,211,145) : SidebarControls.GOLD);
        panelComponent.getChildren().add(bar);
        panelComponent.getChildren().add(LineComponent.builder().left(view.remaining + " remaining").right("Slayer XP")
            .leftColor(Color.LIGHT_GRAY).rightColor(Color.LIGHT_GRAY).build());
        return super.render(graphics);
    }
}

package com.hcimprogression.companion;

import java.util.Locale;
import net.runelite.api.Experience;

/** Assignment-count progress, not lifetime KC or a count of attack animations. */
final class SlayerTaskProgress
{
    static final class Saved
    {
        final String task;
        final int total,remaining,xpGained,lastXp;
        Saved(String task,int total,int remaining,int xpGained,int lastXp)
        { this.task=task; this.total=total; this.remaining=remaining; this.xpGained=xpGained; this.lastXp=lastXp; }
        boolean valid()
        {
            return task!=null && !task.isEmpty() && task.length()<=120 && task.chars().noneMatch(Character::isISOControl)
                && total>0 && total<=1_000_000 && remaining>0 && remaining<=total
                && xpGained>=0 && lastXp>=xpGained && lastXp<=Experience.MAX_SKILL_XP;
        }
    }
    static final class View
    {
        final String task;
        final int total, remaining, done, xpGained;
        final double percent;
        final String barLabel;
        final long until;
        View(String task, int total, int remaining, int xpGained, long until)
        {
            this.task = task; this.total = total; this.remaining = remaining; this.until = until;
            done = Math.max(0,total - remaining);
            percent = total <= 0 ? 0 : Math.min(100.0,100.0 * done / total);
            this.xpGained = xpGained;
            double rounded = remaining == 0 ? 100.0 : Math.min(99.9,Math.round(percent * 10.0) / 10.0);
            barLabel = String.format(Locale.US,"%.1f%% · +%,d XP",rounded,xpGained);
        }
    }
    private volatile View view;
    private int startXp, currentXp;
    void start(String task, int remaining, int slayerXp)
    {
        startXp = currentXp = slayerXp;
        view = remaining > 0 && slayerXp >= 0 ? new View(ProgressionFeedback.clean(task),remaining,remaining,0,Long.MAX_VALUE) : null;
    }
    void experience(int slayerXp, long now)
    {
        View previous = view(now);
        if (previous == null) return;
        if (slayerXp < currentXp) { stop(); return; }
        if (slayerXp == currentXp) return;
        currentXp = slayerXp;
        view = new View(previous.task,previous.total,previous.remaining,Math.max(0,currentXp-startXp),previous.until);
    }
    void observe(int count, long now)
    {
        View previous = view;
        if (previous == null || previous.remaining == 0) return;
        int remaining = Math.max(0,count);
        // If a task is extended, preserve progress already credited and enlarge
        // its target instead of letting the bar become negative or over 100%.
        int total = previous.total + Math.max(0,remaining - previous.remaining);
        view = new View(previous.task,total,remaining,previous.xpGained,remaining == 0 ? now + 8000L : Long.MAX_VALUE);
    }
    View view(long now) { View current = view; return current != null && now < current.until ? current : null; }
    Saved save(long now)
    {
        View current=view(now);
        return current==null || current.remaining<=0 ? null : new Saved(current.task,current.total,current.remaining,current.xpGained,currentXp);
    }
    boolean restore(Saved saved,int liveRemaining,int liveXp)
    {
        if(saved==null || !saved.valid() || liveRemaining<=0 || liveRemaining>saved.remaining
            || liveXp<saved.lastXp || liveXp>Experience.MAX_SKILL_XP) return false;
        // Preserve proven tracked XP; unrelated/other-client XP while absent is not backfilled.
        startXp=liveXp-saved.xpGained; currentXp=liveXp;
        view=new View(saved.task,saved.total,liveRemaining,saved.xpGained,Long.MAX_VALUE);
        return true;
    }
    void stop() { view = null; startXp = currentXp = 0; }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.HttpUrl;

/** Bounded factual fields only: no downloaded code, HTML rendering or combat instructions. */
final class SlayerWikiGuide
{
    static final String HOST = "oldschool.runescape.wiki";
    static final class Variant
    {
        final String name, stats;
        final Map<String, String> fields;
        Variant(String name, String stats, Map<String, String> fields)
        {
            this.name = name; this.stats = stats;
            this.fields = Collections.unmodifiableMap(new LinkedHashMap<>(fields));
        }
        @Override public String toString() { return name; }
    }
    final String title, url, locations;
    final long revision;
    final List<Variant> variants;
    SlayerWikiGuide(String title, long revision, String locations, List<Variant> variants)
    {
        this.title = title; this.url = url(title); this.revision = revision;
        this.locations = locations; this.variants = Collections.unmodifiableList(variants);
    }
    static String validTitle(String title)
    {
        String value = title == null ? "" : title.trim().replace('_', ' ');
        if (value.isEmpty() || value.length() > 100 || value.contains(":") || value.contains("/")
            || value.contains("\\") || value.contains("@") || value.contains("<") || value.contains(">")
            || value.chars().anyMatch(Character::isISOControl)) throw new IllegalArgumentException("Enter a monster's Wiki page name, not a URL.");
        return value;
    }
    static String url(String title)
    {
        return new HttpUrl.Builder().scheme("https").host(HOST).addPathSegment("w").addPathSegment(validTitle(title).replace(' ', '_')).build().toString();
    }
    /** Only unambiguous common task labels; broad categories stay editable. */
    static String monsterTitle(String task)
    {
        String name = validTitle(task);
        switch (name.toLowerCase(java.util.Locale.ROOT))
        {
            case "bloodveld": return "Bloodveld";
            case "nechryael": return "Nechryael";
            case "cockatrice": return "Cockatrice";
            case "ankou": return "Ankou";
            case "dagannoth": return "Dagannoth";
            case "dust devils": return "Dust devil";
            case "smoke devils": return "Smoke devil";
            case "aberrant spectres": return "Aberrant spectre";
            case "abyssal demons": return "Abyssal demon";
            case "black demons": return "Black demon";
            case "greater demons": return "Greater demon";
            case "lesser demons": return "Lesser demon";
            case "blue dragons": return "Blue dragon";
            case "black dragons": return "Black dragon";
            case "green dragons": return "Green dragon";
            case "red dragons": return "Red dragon";
            case "bronze dragons": return "Bronze dragon";
            case "iron dragons": return "Iron dragon";
            case "steel dragons": return "Steel dragon";
            case "basilisks": return "Basilisk";
            case "gargoyles": return "Gargoyle";
            case "jellies": return "Jelly";
            case "hellhounds": return "Hellhound";
            case "dark beasts": return "Dark beast";
            case "fire giants": return "Fire giant";
            case "hill giants": return "Hill giant";
            case "moss giants": return "Moss giant";
            case "ice giants": return "Ice giant";
            case "wyrms": return "Wyrm";
            case "drakes": return "Drake";
            case "hydras": return "Hydra";
            default: return name;
        }
    }
    static SlayerWikiGuide parse(String title, long revision, String source)
    {
        if (source == null || source.length() > 500_000) throw new IllegalArgumentException("Wiki page is too large.");
        Matcher start = Pattern.compile("\\{\\{\\s*Infobox[ _]Monster\\b", Pattern.CASE_INSENSITIVE).matcher(source);
        if (!start.find()) throw new IllegalArgumentException("This page has no monster infobox. Enter an exact monster page, such as Dust devil or Greater Nechryael.");
        int at = start.end(), depth = 1, end = at;
        while (end + 1 < source.length() && depth > 0)
        {
            String pair = source.substring(end, end + 2);
            if ("{{".equals(pair)) { depth++; end += 2; }
            else if ("}}".equals(pair)) { depth--; end += 2; }
            else end++;
        }
        if (depth != 0) throw new IllegalArgumentException("Wiki infobox was incomplete.");
        Map<String, String> fields = new LinkedHashMap<>();
        Matcher params = Pattern.compile("(?m)^\\|\\s*([^=\\n]+?)\\s*=\\s*([^\\n]*)").matcher(source.substring(at, end - 2));
        while (params.find()) fields.put(params.group(1).trim().toLowerCase(java.util.Locale.ROOT), clean(params.group(2)));
        List<Variant> variants = new ArrayList<>();
        int count = 0;
        for (String key : fields.keySet()) if (key.matches("version[0-9]{1,2}")) count = Math.max(count, Integer.parseInt(key.substring(7)));
        count = Math.max(1, Math.min(32, count));
        String[][] stats = {{"combat","Combat"},{"hitpoints","HP"},{"att","Attack"},{"str","Strength"},{"def","Defence"},
            {"mage","Magic"},{"range","Ranged"},{"slaylvl","Slayer required"},{"max hit","Max hit"},
            {"attack style","Attack style"},{"dstab","Stab defence"},{"dslash","Slash defence"},{"dcrush","Crush defence"},
            {"dmagic","Magic defence"},{"drange","Ranged defence"},{"dlight","Light ranged defence"},
            {"dstandard","Standard ranged defence"},{"dheavy","Heavy ranged defence"},{"weakness","Weakness"},
            {"elementalweaknesstype","Elemental weakness"},{"elementalweaknesspercent","Elemental weakness bonus (%)"}};
        for (int i = 1; i <= count; i++)
        {
            StringBuilder text = new StringBuilder();
            Map<String, String> values = new LinkedHashMap<>();
            for (String[] field : stats)
            {
                String value = fields.getOrDefault(field[0] + i, fields.get(field[0]));
                if (value != null && !value.isEmpty())
                {
                    text.append(field[1]).append(": ").append(value).append('\n');
                    values.put(field[1], value);
                }
            }
            if (!fields.containsKey("weakness" + i) && !fields.containsKey("weakness")
                && !fields.containsKey("elementalweaknesstype" + i) && !fields.containsKey("elementalweaknesstype"))
                text.append("Weakness: not listed in the parsed infobox. Defence values are not a DPS ranking.\n");
            variants.add(new Variant(fields.getOrDefault("version" + i, fields.getOrDefault("name", title)), text.toString().trim(), values));
        }
        List<String> locations = new ArrayList<>();
        Matcher loc = Pattern.compile("\\{\\{LocLine\\b([^}]{0,25000})}}", Pattern.CASE_INSENSITIVE).matcher(source);
        while (loc.find() && locations.size() < 12)
        {
            Matcher location = Pattern.compile("(?m)^\\|\\s*(?:location|loc)\\s*=([^\\n]+)", Pattern.CASE_INSENSITIVE).matcher(loc.group(1));
            if (location.find()) { String value = clean(location.group(1)); if (!value.isEmpty() && !locations.contains(value)) locations.add(value); }
        }
        String listed = fields.get("location");
        if (locations.isEmpty() && listed != null && !listed.isEmpty()) locations.add(listed);
        for (int i = 1; i <= count && locations.size() < 12; i++)
        {
            String value = fields.get("location" + i);
            if (value != null && !value.isEmpty() && !locations.contains(value)) locations.add(value);
        }
        return new SlayerWikiGuide(validTitle(title), revision, locations.isEmpty()
            ? "No structured locations found. Open the Wiki's Locations section; variant names may identify specific areas."
            : String.join("\n", locations), variants);
    }
    static String clean(String value)
    {
        String text = value.replaceAll("(?is)<ref\\b[^>]*>.*?</ref>", "").replaceAll("<[^>]*>", "")
            .replaceAll("\\[\\[([^]\\n|]+)\\|([^]\\n]+)]]", "$2").replaceAll("\\[\\[([^]\\n]+)]]", "$1")
            .replaceAll("\\{\\{[^}]*}}", "[see Wiki]").replace("'''", "").replace("''", "")
            .replace("&nbsp;", " ").replace("&amp;", "&").replaceAll("\\s+", " ").trim();
        return text.length() > 350 ? text.substring(0, 350) + "… [see Wiki]" : text;
    }
}

package com.hcimprogression.companion;

import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.Map;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTextArea;

/** EDT-only, plain-text Wiki facts. Never renders downloaded HTML. */
final class SlayerWikiPanel
{
    private final JPanel root = SidebarControls.column();
    private final JTextArea state = SidebarControls.text("Start a task, then load its optional Wiki facts. Stats and locations load together.");
    private final JComboBox<SlayerWikiGuide.Variant> variants = new JComboBox<>();
    private final JPanel facts = SidebarControls.column();
    private final JPanel statsBody = SidebarControls.column();
    private final JPanel locationBody = SidebarControls.column();
    private final JTextArea source = SidebarControls.text("");
    private final SidebarControls.Fold stats = SidebarControls.fold("Stats & weaknesses", statsBody);
    private final SidebarControls.Fold locations = SidebarControls.fold("Locations", locationBody);
    private SlayerWikiGuide current;

    SlayerWikiPanel()
    {
        root.add(state); SidebarControls.gap(root);
        SidebarControls.field(variants); variants.setToolTipText("Choose the exact monster level / variant");
        facts.add(SidebarControls.text("Monster variant")); facts.add(variants); SidebarControls.gap(facts);
        facts.add(stats); SidebarControls.gap(facts); facts.add(locations); SidebarControls.gap(facts);
        source.setFont(SidebarControls.FONT.deriveFont(10f)); facts.add(source);
        root.add(facts); facts.setVisible(false);
        variants.addActionListener(event -> renderVariant());
    }
    JPanel panel() { return root; }
    void show(SlayerWikiGuide guide, String message, boolean loading)
    {
        state.setText(message);
        state.setForeground(loading ? SidebarControls.GOLD : guide == null ? SidebarControls.MUTED : new Color(113,206,158));
        if (guide == current) return;
        current = guide; variants.removeAllItems(); statsBody.removeAll(); locationBody.removeAll();
        facts.setVisible(guide != null);
        if (guide != null)
        {
            for (SlayerWikiGuide.Variant variant : guide.variants) variants.addItem(variant);
            // Explicit render as well as the selection event: never depend on
            // a particular Look-and-Feel firing an event for the first item.
            renderVariant();
            locationBody.add(SidebarControls.text("Possible locations; your assignment's area restriction still applies."));
            for (String place : guide.locations.split("\n"))
            {
                SidebarControls.gap(locationBody);
                JTextArea row = SidebarControls.text("• " + place);
                row.setForeground(place.toLowerCase(java.util.Locale.ROOT).contains("wilderness") ? new Color(237,160,115) : Color.LIGHT_GRAY);
                locationBody.add(row);
            }
            SidebarControls.gap(locationBody);
            locationBody.add(SidebarControls.text("Open the Wiki page for access requirements and travel instructions."));
            source.setText("OSRS Wiki contributors · revision " + guide.revision + "\n" + guide.title);
            stats.setExpanded(true); locations.setExpanded(true);
        }
        root.revalidate(); root.repaint();
    }
    private void renderVariant()
    {
        SlayerWikiGuide.Variant selected = (SlayerWikiGuide.Variant) variants.getSelectedItem();
        if (current == null || selected == null) return;
        statsBody.removeAll(); Map<String, String> values = selected.fields;
        String element = values.get("Elemental weakness");
        String percent = values.get("Elemental weakness bonus (%)");
        JTextArea weakness = SidebarControls.heading(element == null ? values.getOrDefault("Weakness", "No explicit weakness listed")
            : element + (percent == null ? " weakness" : " · +" + percent + "% weakness"));
        statsBody.add(weakness); SidebarControls.gap(statsBody);
        JPanel metrics = new JPanel(new GridLayout(0,2,6,6)); metrics.setOpaque(false); SidebarControls.stretch(metrics);
        for (String key : new String[]{"Combat", "HP", "Attack", "Strength", "Defence", "Magic", "Ranged", "Max hit"})
        {
            if (!values.containsKey(key)) continue;
            JPanel cell = SidebarControls.column();
            JTextArea number = SidebarControls.heading(values.get(key)); number.setForeground(Color.WHITE);
            number.setFont(SidebarControls.FONT.deriveFont(Font.BOLD,14f)); cell.add(number);
            cell.add(SidebarControls.text(key)); metrics.add(cell);
        }
        statsBody.add(metrics); SidebarControls.gap(statsBody);
        for (String key : new String[]{"Attack style", "Slayer required"}) if (values.containsKey(key)) statsBody.add(SidebarControls.text(key + ": " + values.get(key)));
        JPanel defence = SidebarControls.column();
        for (Map.Entry<String,String> field : values.entrySet()) if (field.getKey().endsWith("defence")) defence.add(SidebarControls.text(field.getKey() + ": " + field.getValue()));
        defence.add(SidebarControls.text("Defence bonuses are not a DPS ranking. Match the correct level / variant."));
        statsBody.add(SidebarControls.fold("Defence details", defence));
        statsBody.revalidate(); statsBody.repaint();
    }
}

package com.hcimprogression.companion;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.function.BiConsumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/** Explicit user lookup: only a public page title, never bank/account data. */
final class SlayerWikiService
{
    private final OkHttpClient http;
    private final Gson gson;
    SlayerWikiService(OkHttpClient http, Gson gson) { this.http = http; this.gson = gson; }
    Call load(String title, BiConsumer<SlayerWikiGuide, String> done)
    {
        HttpUrl url = new HttpUrl.Builder().scheme("https").host(SlayerWikiGuide.HOST).addPathSegment("api.php")
            .addQueryParameter("action", "query").addQueryParameter("titles", SlayerWikiGuide.validTitle(title))
            .addQueryParameter("prop", "revisions").addQueryParameter("rvprop", "content|ids").addQueryParameter("rvslots", "main")
            .addQueryParameter("format", "json").addQueryParameter("redirects", "1").build();
        Call call = http.newCall(new Request.Builder().url(url).header("User-Agent", "ProgressionPath (Slayer preparation; public Wiki lookup)").build());
        call.timeout().timeout(15, java.util.concurrent.TimeUnit.SECONDS);
        call.enqueue(new Callback()
        {
            @Override public void onFailure(Call call, IOException error) { done.accept(null, "Wiki lookup unavailable; your local bank setup is unchanged."); }
            @Override public void onResponse(Call call, Response response)
            {
                try (Response reply = response)
                {
                    if (!reply.isSuccessful()) throw new IllegalArgumentException("Wiki returned HTTP " + reply.code() + ". Open the Wiki page or try again later.");
                    if (reply.body() == null || !SlayerWikiGuide.HOST.equals(reply.request().url().host())) throw new IOException();
                    okio.BufferedSource source = reply.body().source();
                    if (source.request(500_001)) throw new IllegalArgumentException("Wiki response exceeded the safe size limit. Use Open Wiki page.");
                    JsonObject json = gson.fromJson(source.getBuffer().readUtf8(), JsonObject.class);
                    done.accept(parseResponse(json), null);
                }
                catch (IllegalArgumentException error) { done.accept(null, error.getMessage()); }
                catch (Exception error) { done.accept(null, "Wiki returned an unreadable response. Open the Wiki page or retry the exact monster name."); }
            }
        });
        return call;
    }
    static SlayerWikiGuide parseResponse(JsonObject json)
    {
        if (json == null || json.has("error") || !json.has("query")) throw new IllegalArgumentException("Wiki could not return this page. Try the exact monster name.");
        JsonElement pages = json.getAsJsonObject("query").get("pages");
        if (pages == null || pages.isJsonNull()) throw new IllegalArgumentException("Wiki returned no monster page.");
        JsonObject page;
        if (pages.isJsonArray())
        {
            if (pages.getAsJsonArray().size() == 0) throw new IllegalArgumentException("Wiki returned no monster page.");
            page = pages.getAsJsonArray().get(0).getAsJsonObject();
        }
        else
        {
            if (pages.getAsJsonObject().entrySet().isEmpty()) throw new IllegalArgumentException("Wiki returned no monster page.");
            page = pages.getAsJsonObject().entrySet().iterator().next().getValue().getAsJsonObject();
        }
        if (page.has("missing") || !page.has("revisions") || page.getAsJsonArray("revisions").size() == 0)
            throw new IllegalArgumentException("No Wiki page found. Use an exact monster name, not a Slayer category.");
        JsonObject revision = page.getAsJsonArray("revisions").get(0).getAsJsonObject();
        JsonObject main = revision.getAsJsonObject("slots").getAsJsonObject("main");
        JsonElement content = main.has("*") ? main.get("*") : main.get("content");
        if (content == null || content.isJsonNull()) throw new IllegalArgumentException("Wiki page content was unavailable.");
        return SlayerWikiGuide.parse(page.get("title").getAsString(), revision.get("revid").getAsLong(), content.getAsString());
    }
}

package com.hcimprogression.companion;

import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

public class SocialClanEventService
{
    private static final int MAX_EVENTS = 100;
    private static final DateTimeFormatter DATE_FORMAT = new DateTimeFormatterBuilder()
        .parseCaseInsensitive()
        .appendPattern("d-MMM-uuuu")
        .toFormatter(Locale.ENGLISH);
    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("H:mm", Locale.ENGLISH);

    public SocialClanEventSnapshot createSnapshot(Client client)
    {
        Widget worldWidget = client.getWidget(InterfaceID.ClansEvents.LIST_CONTENTS_WORLD);
        if (worldWidget == null)
        {
            return null;
        }

        Widget[] worlds = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_WORLD);
        Widget[] dates = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_DATE);
        Widget[] times = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_TIME);
        Widget[] durations = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_DURATION);
        Widget[] types = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_TYPE);
        Widget[] activities = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_ACTIVITY);
        Widget[] subTypes = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_SUBTYPE);
        Widget[] ranks = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_RANK_TO_VIEW);
        Widget[] creators = dynamicChildren(client, InterfaceID.ClansEvents.LIST_CONTENTS_CREATOR);

        SocialClanEventSnapshot snapshot = new SocialClanEventSnapshot();
        snapshot.setClanName(clanName(client));
        snapshot.setImportedBy(localPlayerName(client));
        snapshot.setTimestamp(System.currentTimeMillis());

        int count = minLength(worlds, dates, times, activities);
        count = Math.min(count, MAX_EVENTS);
        for (int i = 0; i < count; i++)
        {
            String title = cleanText(activities[i]);
            if (title.isEmpty())
            {
                continue;
            }

            String dateText = valueAfterLabel(cleanText(dates[i]), "Date");
            String timeText = valueAfterLabel(cleanText(times[i]), "Time").replace("UTC", "").trim();
            long startAt = parseStart(dateText, timeText);
            if (startAt <= 0)
            {
                continue;
            }

            int durationDays = clamp(parseFirstInteger(cleanTextAt(durations, i)), 1, 365);
            int world = clamp(parseFirstInteger(cleanTextAt(worlds, i)), 0, 999);
            long endAt = startAt + durationDays * 24L * 60L * 60L * 1000L;

            snapshot.getEvents().add(new SocialClanEventSnapshot.ClanEventSnapshot(
                clean(title, 100),
                clean(valueAfterLabel(cleanTextAt(types, i), "Type"), 60),
                clean(valueAfterLabel(cleanTextAt(subTypes, i), "Sub Type"), 60),
                clean(valueAfterLabel(cleanTextAt(ranks, i), "Rank"), 50),
                clean(valueAfterLabel(cleanTextAt(creators, i), "By"), 50),
                world,
                durationDays,
                startAt,
                endAt
            ));
        }

        return snapshot;
    }

    private Widget[] dynamicChildren(Client client, int componentId)
    {
        Widget widget = client.getWidget(componentId);
        Widget[] children = widget == null ? null : widget.getDynamicChildren();
        return children == null ? new Widget[0] : children;
    }

    private int minLength(Widget[]... arrays)
    {
        int minimum = Integer.MAX_VALUE;
        for (Widget[] array : arrays)
        {
            minimum = Math.min(minimum, array == null ? 0 : array.length);
        }
        return minimum == Integer.MAX_VALUE ? 0 : minimum;
    }

    private long parseStart(String dateText, String timeText)
    {
        try
        {
            LocalDate date = LocalDate.parse(dateText.trim(), DATE_FORMAT);
            LocalTime time = LocalTime.parse(timeText.trim(), TIME_FORMAT);
            return date.atTime(time).toInstant(ZoneOffset.UTC).toEpochMilli();
        }
        catch (DateTimeParseException ignored)
        {
            return 0;
        }
    }

    private int parseFirstInteger(String value)
    {
        String digits = String.valueOf(value == null ? "" : value).replaceAll("[^0-9]", " ").trim();
        if (digits.isEmpty())
        {
            return 0;
        }
        String first = digits.split("\\s+")[0];
        try
        {
            return Integer.parseInt(first);
        }
        catch (NumberFormatException ignored)
        {
            return 0;
        }
    }

    private String valueAfterLabel(String value, String label)
    {
        String cleaned = clean(value, 120);
        String prefix = label + ":";
        if (cleaned.regionMatches(true, 0, prefix, 0, prefix.length()))
        {
            return cleaned.substring(prefix.length()).trim();
        }
        return cleaned;
    }


    private String cleanTextAt(Widget[] widgets, int index)
    {
        if (widgets == null || index < 0 || index >= widgets.length)
        {
            return "";
        }
        return cleanText(widgets[index]);
    }

    private String cleanText(Widget widget)
    {
        return widget == null ? "" : clean(Text.removeTags(widget.getText()), 120);
    }

    private String clanName(Client client)
    {
        ClanChannel channel = client.getClanChannel();
        if (channel != null && channel.getName() != null && !channel.getName().trim().isEmpty())
        {
            return clean(channel.getName(), 50);
        }
        ClanSettings settings = client.getClanSettings();
        return settings == null ? "" : clean(settings.getName(), 50);
    }

    private String localPlayerName(Client client)
    {
        Player player = client.getLocalPlayer();
        return player == null ? "" : clean(player.getName(), 20);
    }

    private int clamp(int value, int minimum, int maximum)
    {
        return Math.max(minimum, Math.min(maximum, value));
    }

    private String clean(String value, int max)
    {
        String cleaned = value == null ? "" : value.replace('\u00A0', ' ').replaceAll("[\\r\\n\\t]+", " ").trim();
        return cleaned.length() <= max ? cleaned : cleaned.substring(0, max);
    }
}

