@Slf4j
public class SyncService {
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final long LINK_TIMEOUT_SECONDS = 20L;
    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public SyncService(OkHttpClient httpClient, Gson gson) {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public void exchangeCode(
            String apiBaseUrl,
            String code,
            BiConsumer<LinkResult, String> callback) {
        String normalized = code == null
                ? ""
                : code.replaceAll("[^A-Za-z0-9]", "").toUpperCase();

        String json = "{\"code\":\"" + escape(normalized) + "\"}";

        CompletableFuture<String> exchange;
        try {
            exchange = post(apiBaseUrl, "companion-link-exchange", null, json);
        } catch (RuntimeException error) {
            callback.accept(null, friendly(error));
            return;
        }

        exchange.orTimeout(LINK_TIMEOUT_SECONDS, TimeUnit.SECONDS)
                .whenComplete((body, error) ->
                {
                    if (error != null) {
                        callback.accept(null, friendly(error));
                        return;
                    }

                    String token = stringValue(body, "token");
                    String displayName = stringValue(body, "characterName");
                    if (displayName.isEmpty()) {
                        displayName = stringValue(body, "displayName");
                    }

                    if (token.isEmpty()) {
                        callback.accept(null, errorValue(body));
                    } else {
                        callback.accept(
                                new LinkResult(token, displayName),
                                null
                        );
                    }
                });
    }

    public void fetchPinnedGoal(String apiBaseUrl, String token, String playerName,
        BiConsumer<ProgressionFeedback.Goal, String> callback)
    {
        try
        {
            post(apiBaseUrl, "companion-goal", token,
                "{\"playerName\":\"" + escape(playerName) + "\"}")
                .orTimeout(20, TimeUnit.SECONDS).whenComplete((body, error) -> {
                    if (error != null) { callback.accept(null, friendly(error)); return; }
                    try
                    {
                        ProgressionFeedback.Response result = gson.fromJson(body, ProgressionFeedback.Response.class);
                        if (result == null || !result.ok) callback.accept(null, "Could not load pinned goal");
                        else callback.accept(result.goal, null);
                    }
                    catch (RuntimeException malformed) { callback.accept(null, "Invalid pinned goal response"); }
                });
        }
        catch (RuntimeException error) { callback.accept(null, friendly(error)); }
    }

    void syncRoutineRoute(String apiBaseUrl, String token, String playerName, String kind,
        RoutineRoutePlan plan, BiConsumer<RoutineRoutePlan, String> callback)
    {
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("playerName", playerName); payload.put("kind", kind);
        payload.put("action", plan == null ? "get" : "save");
        if (plan != null) { payload.put("plan", plan); payload.put("expectedRevision", plan.revision); }
        try {
            post(apiBaseUrl, "companion-route-plan", token, gson.toJson(payload))
                .orTimeout(20, TimeUnit.SECONDS).whenComplete((body, error) -> {
                    if (error != null) { callback.accept(null, friendly(error)); return; }
                    try {
                        RoutineRoutePlan.Response response = gson.fromJson(body, RoutineRoutePlan.Response.class);
                        if (response == null || !response.ok || (plan != null && response.plan == null)
                            || (response.plan != null && (!kind.equals(response.plan.kind) || !response.plan.valid()))) {
                            callback.accept(null, "Invalid route response. Local edits were kept."); return;
                        }
                        callback.accept(response.plan, null);
                    } catch (RuntimeException malformed) { callback.accept(null, "Invalid route response. Local edits were kept."); }
                });
        } catch (RuntimeException error) { callback.accept(null, friendly(error)); }
    }

    void syncSkillGoal(String api,String token,String name,SkillGoalSync.Goal goal,BiConsumer<SkillGoalSync.Response,String> callback)
    {
        Map<String,Object> payload = new LinkedHashMap<>(); payload.put("playerName",name); payload.put("goal",goal);
        try {
            post(api,"companion-skill-goal",token,gson.toJson(payload)).orTimeout(20,TimeUnit.SECONDS).whenComplete((body,error) -> {
                if (error != null) { callback.accept(null,friendly(error)); return; }
                try {
                    SkillGoalSync.Response response = gson.fromJson(body,SkillGoalSync.Response.class);
                    if (response == null || !response.ok || response.sequence < 1 || !("active".equals(response.status) || "completed".equals(response.status) || "stopped".equals(response.status)))
                        callback.accept(null,"Invalid skill goal response");
                    else callback.accept(response,null);
                } catch (RuntimeException invalid) { callback.accept(null,"Invalid skill goal response"); }
            });
        } catch (RuntimeException error) { callback.accept(null,friendly(error)); }
    }

    void syncPersonalBests(String api, String token, String name, List<PersonalBestRecord> records, BiConsumer<Integer,String> callback)
    {
        Map<String,Object> payload = new LinkedHashMap<>(); payload.put("playerName",name); payload.put("records",records);
        try {
            post(api,"companion-personal-bests",token,gson.toJson(payload)).orTimeout(20,TimeUnit.SECONDS).whenComplete((body,error) -> {
                if (error != null) { callback.accept(null,friendly(error)); return; }
                try {
                    com.google.gson.JsonObject response = gson.fromJson(body,com.google.gson.JsonObject.class);
                    if (response == null || !response.has("ok") || !response.get("ok").getAsBoolean() || !response.has("recordCount"))
                        callback.accept(null,"Invalid personal records response");
                    else callback.accept(response.get("recordCount").getAsInt(),null);
                } catch (RuntimeException invalid) { callback.accept(null,"Invalid personal records response"); }
            });
        } catch (RuntimeException error) { callback.accept(null,friendly(error)); }
    }

    public void syncLocation(
            String apiBaseUrl,
            String token,
            PlayerState state,
            Consumer<String> callback) {
        String json = "{"
                + "\"playerName\":\"" + escape(state.getPlayerName()) + "\","
                + "\"world\":" + state.getWorld() + ","
