package com.hcimprogression.companion;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Exchanges only the public, read-only messages exposed by OSRS TCG.
 *
 * <p>The string constants are intentionally copied from the TCG message API.
 * Plugin Hub plugins have separate classloaders and must not import one
 * another's implementation classes.</p>
 */
public class TcgCollectionSnapshotService
{
    private static final String NAMESPACE = "osrstcg";
    private static final String QUERY = "query-owned-names";
    private static final String REPLY = "owned-names";
    private static final String CHANGED = "owned-names-changed";
    private static final String KEY_OWNED_NAMES = "ownedNames";
    private static final int CARD_POOL = 6376;
    private static final int MAX_NAME_LENGTH = 80;

    private final EventBus eventBus;
    private volatile TcgCollectionSnapshot latestSnapshot = TcgCollectionSnapshot.unavailable();

    public TcgCollectionSnapshotService(EventBus eventBus)
    {
        this.eventBus = eventBus;
    }

    /** Requests a fresh snapshot from OSRS TCG, if that plugin is running. */
    public void requestSnapshot()
    {
        eventBus.post(new PluginMessage(NAMESPACE, QUERY));
    }

    /**
     * Accepts OSRS TCG replies and collection-change broadcasts.
     *
     * @return true when the event contained a valid TCG collection snapshot
     */
    public boolean handle(PluginMessage event)
    {
        if (event == null || !NAMESPACE.equals(event.getNamespace())
            || (!REPLY.equals(event.getName()) && !CHANGED.equals(event.getName())))
        {
            return false;
        }

        TcgCollectionSnapshot parsed = parse(event.getData());
        if (parsed == null)
        {
            return false;
        }
        latestSnapshot = parsed;
        return true;
    }

    public TcgCollectionSnapshot getLatestSnapshot()
    {
        return latestSnapshot;
    }

    private TcgCollectionSnapshot parse(Map<String, Object> data)
    {
        if (data == null || !(data.get(KEY_OWNED_NAMES) instanceof Iterable))
        {
            return null;
        }

        TcgCollectionSnapshot snapshot = new TcgCollectionSnapshot();
        Set<String> uniqueNames = new HashSet<>();
        for (Object value : (Iterable<?>) data.get(KEY_OWNED_NAMES))
        {
            if (!(value instanceof String))
            {
                continue;
            }
            String name = ((String) value).trim();
            String normalized = name.toLowerCase(java.util.Locale.ROOT);
            if (name.isEmpty() || name.length() > MAX_NAME_LENGTH || !uniqueNames.add(normalized))
            {
                continue;
            }
            snapshot.getCards().add(new TcgCollectionSnapshot.CardSnapshot(name, false, 1));
        }

        int owned = snapshot.getCards().size();
        snapshot.setAvailable(true);
        snapshot.setSchemaVersion(1);
        snapshot.setTotalCardsOwned(owned);
        snapshot.setUniqueOwned(owned);
        snapshot.setTotalCardPool(CARD_POOL);
        snapshot.setCompletionPct(owned * 100d / CARD_POOL);
        snapshot.setUpdatedAt(System.currentTimeMillis());
        return snapshot;
    }
}

package com.hcimprogression.companion;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/**
 * Keeps monotonic, RuneScape-profile-scoped NPC and clue loot totals plus a bounded
 * local history. The history is uploaded only during normal account syncs, so
 * no per-drop network request is required and gameplay never waits on the site.
 */
public class WeeklyLootTrackerService
{
    private static final String VALUE_KEY = "weeklyLootValueTotal";
    private static final String DROP_COUNT_KEY = "weeklyLootDropCountTotal";
    private static final String TRACKED_SINCE_KEY = "weeklyLootTrackedSince";
    private static final String DROP_HISTORY_KEY = "weeklyLootDropHistory";
    private static final int MAX_STORED_DROPS = 250;
    private static final long DROP_RETENTION_MILLIS = 30L * 24L * 60L * 60L * 1000L;
    private static final Map<String, List<String>> SLAYER_SOURCE_ALIASES = createSlayerSourceAliases();

    public void recordNpcLoot(
        String source,
        int npcId,
        String slayerTask,
        Collection<ItemStack> items,
        ItemManager itemManager,
        ConfigManager configManager,
        Gson gson)
    {
        String verifiedTask = sourceMatchesSlayerTask(source, slayerTask) ? slayerTask : "";
        recordLoot(source, npcId, verifiedTask, items, itemManager, configManager, gson);
    }

    public void recordEventLoot(
        String source,
        Collection<ItemStack> items,
        ItemManager itemManager,
        ConfigManager configManager,
        Gson gson)
    {
        recordLoot(source, 0, "", items, itemManager, configManager, gson);
    }

    private void recordLoot(
        String source,
        int npcId,
        String slayerTask,
        Collection<ItemStack> items,
        ItemManager itemManager,
        ConfigManager configManager,
        Gson gson)
    {
        if (items == null || items.isEmpty())
        {
            return;
        }

        long eventValue = 0L;
        List<LootDropSnapshot.LootItemSnapshot> lootItems = new ArrayList<>();
        for (ItemStack item : items)
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            int canonicalId = itemManager.canonicalize(item.getId());
            long price = Math.max(0L, itemManager.getItemPrice(canonicalId));
            long itemValue = safeMultiply(price, item.getQuantity());
            eventValue = safeAdd(eventValue, itemValue);
            String itemName = itemManager.getItemComposition(canonicalId).getName();
            if (itemName == null || itemName.trim().isEmpty())
            {
                itemName = "Item " + canonicalId;
            }
            lootItems.add(new LootDropSnapshot.LootItemSnapshot(
                canonicalId,
                itemName,
                item.getQuantity(),
                price,
                itemValue
            ));
        }
        if (lootItems.isEmpty())
        {
            return;
        }

        long now = System.currentTimeMillis();
        long nextDropCount = safeAdd(readLong(configManager, DROP_COUNT_KEY), 1L);
        long trackedSince = readLong(configManager, TRACKED_SINCE_KEY);
        if (trackedSince <= 0L)
        {
            configManager.setRSProfileConfiguration(
                HcimProgressionCompanionConfig.GROUP,
                TRACKED_SINCE_KEY,
                now
            );
        }
        configManager.setRSProfileConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            VALUE_KEY,
            safeAdd(readLong(configManager, VALUE_KEY), eventValue)
        );
        configManager.setRSProfileConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            DROP_COUNT_KEY,
            nextDropCount
        );

        List<LootDropSnapshot> history = readDrops(configManager, gson, now);
        history.add(0, new LootDropSnapshot(
            now + "-" + nextDropCount,
            now,
            cleanLabel(source, "NPC loot"),
            Math.max(0, npcId),
            cleanSlayerTask(slayerTask),
            eventValue,
            lootItems
        ));
        if (history.size() > MAX_STORED_DROPS)
        {
            history = new ArrayList<>(history.subList(0, MAX_STORED_DROPS));
        }
        configManager.setRSProfileConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            DROP_HISTORY_KEY,
            gson.toJson(history)
        );
    }

    static boolean sourceMatchesSlayerTask(String source, String slayerTask)
    {
        String actual = normalizeSlayerName(source);
        String target = normalizeSlayerName(slayerTask);
        if (actual.isEmpty() || target.isEmpty() || target.startsWith("no active task"))
        {
            return false;
        }
        if (actual.equals(target) || (target.endsWith("s") && actual.equals(target.substring(0, target.length() - 1))))
        {
            return true;
        }
        return SLAYER_SOURCE_ALIASES.getOrDefault(target, Collections.emptyList()).contains(actual);
    }

    private static String normalizeSlayerName(String value)
    {
        if (value == null)
        {
            return "";
        }
        return value.toLowerCase(Locale.ROOT)
            .replaceAll("\\b(task|assignment)\\b", " ")
            .replaceAll("['’]", "")
            .replaceAll("[^a-z0-9]+", " ")
            .trim();
    }

    private static Map<String, List<String>> createSlayerSourceAliases()
    {
        Map<String, List<String>> aliases = new HashMap<>();
        aliases.put("abyssal demons", Arrays.asList("abyssal demon", "abyssal sire"));
        aliases.put("aviansies", Arrays.asList("aviansie", "k ril tsutsaroth", "flight kilisa", "flockleader geerin", "wingman skree"));
        aliases.put("black demons", Arrays.asList("black demon", "demonic gorilla", "tortured gorilla", "skotizo"));
        aliases.put("black dragons", Arrays.asList("black dragon", "baby black dragon", "brutal black dragon", "king black dragon"));
        aliases.put("blue dragons", Arrays.asList("blue dragon", "baby blue dragon", "brutal blue dragon"));
        aliases.put("dogs", Arrays.asList("guard dog", "wild dog"));
        aliases.put("elves", Arrays.asList("elf", "iorwerth warrior", "iorwerth archer"));
        aliases.put("fossil island wyverns", Arrays.asList("spitting wyvern", "taloned wyvern", "long tailed wyvern", "ancient wyvern"));
        aliases.put("gargoyles", Arrays.asList("gargoyle", "dusk", "dawn"));
        aliases.put("greater demons", Arrays.asList("greater demon", "k ril tsutsaroth"));
        aliases.put("hellhounds", Arrays.asList("hellhound", "cerberus"));
        aliases.put("hydras", Arrays.asList("hydra", "alchemical hydra"));
        aliases.put("kraken", Arrays.asList("cave kraken", "kraken"));
        aliases.put("lizardmen", Arrays.asList("lizardman", "lizardman brute", "lizardman shaman"));
        aliases.put("red dragons", Arrays.asList("red dragon", "brutal red dragon"));
        aliases.put("shades", Arrays.asList("loar shade", "phrin shade", "riyl shade", "asyn shade", "fiyr shade", "urium shade"));
        aliases.put("smoke devils", Arrays.asList("smoke devil", "thermonuclear smoke devil"));
        aliases.put("spiritual creatures", Arrays.asList("spiritual ranger", "spiritual warrior", "spiritual mage"));
        aliases.put("tzhaar", Arrays.asList("tzhaar ket", "tzhaar xil", "tzhaar mej", "tztok jad", "tzkal zuk"));
        aliases.put("wolves", Arrays.asList("wolf", "white wolf", "dire wolf"));
        aliases.put("zombies", Arrays.asList("zombie", "undead one"));
        return aliases;
    }

    public void applyTo(AccountSnapshot snapshot, ConfigManager configManager, Gson gson, boolean enabled)
    {
        snapshot.setLootTrackingEnabled(enabled);
        if (!enabled)
        {
            return;
        }
        snapshot.setLootValueTotal(readLong(configManager, VALUE_KEY));
        snapshot.setLootDropCountTotal(readLong(configManager, DROP_COUNT_KEY));
        snapshot.setLootTrackedSince(readLong(configManager, TRACKED_SINCE_KEY));
        snapshot.getLootDrops().addAll(readDrops(configManager, gson, System.currentTimeMillis()));
    }

    private List<LootDropSnapshot> readDrops(ConfigManager configManager, Gson gson, long now)
    {
        String value = configManager.getRSProfileConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            DROP_HISTORY_KEY,
            String.class
        );
        if (value == null || value.trim().isEmpty())
        {
            return new ArrayList<>();
        }
        try
        {
            LootDropSnapshot[] decoded = gson.fromJson(value, LootDropSnapshot[].class);
            if (decoded == null)
            {
                return new ArrayList<>();
            }
            List<LootDropSnapshot> retained = new ArrayList<>();
            long cutoff = now - DROP_RETENTION_MILLIS;
            for (LootDropSnapshot drop : Arrays.asList(decoded))
            {
                if (drop == null || drop.getDropId() == null || drop.getOccurredAt() < cutoff)
                {
                    continue;
                }
                retained.add(drop);
                if (retained.size() >= MAX_STORED_DROPS)
                {
                    break;
                }
            }
            return retained;
        }
        catch (JsonSyntaxException ignored)
        {
            return new ArrayList<>();
        }
    }

    private String cleanLabel(String value, String fallback)
    {
        String clean = value == null ? "" : value.trim();
        if (clean.isEmpty())
        {
            return fallback;
        }
        return clean.length() > 80 ? clean.substring(0, 80) : clean;
    }

    private String cleanSlayerTask(String value)
    {
        String clean = cleanLabel(value, "");
        return clean.toLowerCase().startsWith("no active task") ? "" : clean;
    }

    private long readLong(ConfigManager configManager, String key)
    {
        Long value = configManager.getRSProfileConfiguration(
            HcimProgressionCompanionConfig.GROUP,
            key,
            Long.class
        );
        return value == null || value < 0L ? 0L : value;
    }

    private long safeMultiply(long left, long right)
    {
        if (left <= 0L || right <= 0L)
        {
            return 0L;
        }
        if (left > Long.MAX_VALUE / right)
        {
            return Long.MAX_VALUE;
        }
        return left * right;
    }

    private long safeAdd(long left, long right)
    {
        if (right > 0L && left > Long.MAX_VALUE - right)
        {
            return Long.MAX_VALUE;
        }
        return Math.max(0L, left + right);
    }
}

package com.hcimprogression.companion;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

final class WorldLocationResolver
{
    private WorldLocationResolver()
    {
    }

    static WorldPoint resolve(Client client, Player player)
    {
        WorldPoint worldPoint = player == null ? null : player.getWorldLocation();
        if (player == null || !client.isInInstancedRegion())
        {
            return worldPoint;
        }

        LocalPoint localPoint = player.getLocalLocation();
        if (localPoint == null)
        {
            return worldPoint;
        }

        WorldPoint templatePoint = WorldPoint.fromLocalInstance(client, localPoint);
        return templatePoint == null ? worldPoint : templatePoint;
    }
}

package com.hcimprogression.companion;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;

public class AccountSnapshotFingerprintTest
{
    private final Gson gson = new Gson();

    @Test
    public void ignoresCaptureOnlyTimestamps()
    {
        AccountSnapshot first = snapshot(100L, 200L, "Blue dragons", 42);
        AccountSnapshot second = snapshot(101L, 201L, "Blue dragons", 42);
        first.setKingdom(new KingdomSnapshot(true, true, true, 2_000_000, 95, 300L));
        second.setKingdom(new KingdomSnapshot(true, true, true, 2_000_000, 95, 301L));

        assertEquals(
            AccountSnapshotFingerprint.create(gson, first),
            AccountSnapshotFingerprint.create(gson, second)
        );
    }

    @Test
    public void detectsMeaningfulSnapshotChanges()
    {
        AccountSnapshot first = snapshot(100L, 200L, "Blue dragons", 42);
        AccountSnapshot differentTask = snapshot(100L, 200L, "Shades", 42);
        AccountSnapshot differentCards = snapshot(100L, 200L, "Blue dragons", 43);
        AccountSnapshot differentMembership = snapshot(100L, 200L, "Blue dragons", 42);
        first.setMembershipDays(30);
        differentMembership.setMembershipDays(29);

        assertNotEquals(
            AccountSnapshotFingerprint.create(gson, first),
            AccountSnapshotFingerprint.create(gson, differentTask)
        );
        assertNotEquals(
            AccountSnapshotFingerprint.create(gson, first),
            AccountSnapshotFingerprint.create(gson, differentCards)
        );
        assertNotEquals(
            AccountSnapshotFingerprint.create(gson, first),
            AccountSnapshotFingerprint.create(gson, differentMembership)
        );
    }

    @Test
    public void createsStableNonSecretLinkKey()
    {
        String token = "private-link-token";
        String first = AccountSnapshotFingerprint.linkKey(token);

        assertEquals(first, AccountSnapshotFingerprint.linkKey(token));
        assertEquals(12, first.length());
        assertFalse(first.contains(token));
        assertNotEquals(first, AccountSnapshotFingerprint.linkKey("another-token"));
    }

    private static AccountSnapshot snapshot(long slayerUpdatedAt, long tcgUpdatedAt, String task, int totalCards)
    {
        AccountSnapshot snapshot = new AccountSnapshot();
        snapshot.setPlayerName("HP Shooter");
        snapshot.setSlayer(new SlayerSnapshot(task, 12, 100, 10, "Vannaka", 1, slayerUpdatedAt));

        TcgCollectionSnapshot tcg = new TcgCollectionSnapshot();
        tcg.setAvailable(true);
        tcg.setUpdatedAt(tcgUpdatedAt);
        tcg.setTotalCardsOwned(totalCards);
        snapshot.setTcg(tcg);
        return snapshot;
    }
}

package com.hcimprogression.companion;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import static org.junit.Assert.*;

public class BarrowsRewardTrackerTest
{
    @Test
    public void reopeningAndPartialWithdrawalsCannotRecordTheSameChestAgain()
    {
        AtomicReference<Integer> saved = new AtomicReference<>();
        AtomicInteger drops = new AtomicInteger();
        BarrowsRewardTracker tracker = new BarrowsRewardTracker(saved::get, saved::set);
        assertTrue(tracker.capture(13, drops::incrementAndGet));
        assertFalse(tracker.capture(13, drops::incrementAndGet));
        assertFalse(tracker.capture(12, drops::incrementAndGet));
        // Recreating the tracker simulates a restart, with no time-based reset.
        tracker = new BarrowsRewardTracker(saved::get, saved::set);
        assertFalse(tracker.capture(13, drops::incrementAndGet));
        assertTrue(tracker.capture(14, drops::incrementAndGet));
        assertEquals(2, drops.get());
    }

    @Test
    public void chestCountsAreIndependentForEachRuneScapeProfile()
    {
        Map<String, Integer> profiles = new HashMap<>();
        AtomicReference<String> profile = new AtomicReference<>("main");
        BarrowsRewardTracker tracker = new BarrowsRewardTracker(
            () -> profiles.get(profile.get()), chest -> profiles.put(profile.get(), chest));
        assertTrue(tracker.capture(1300, () -> {}));
        profile.set("gim");
        assertTrue(tracker.capture(13, () -> {}));
        assertFalse(tracker.capture(13, () -> {}));
        profile.set("main");
        assertFalse(tracker.capture(1300, () -> {}));
        assertTrue(tracker.capture(1301, () -> {}));
    }

    @Test
    public void uninitializedCountsAndFailedCapturesDoNotConsumeAChest()
    {
        AtomicReference<Integer> saved = new AtomicReference<>();
        BarrowsRewardTracker tracker = new BarrowsRewardTracker(saved::get, saved::set);
        assertFalse(tracker.capture(0, () -> fail("Uninitialized count")));
        assertFalse(tracker.capture(-1, () -> fail("Invalid count")));
        try
        {
            tracker.capture(13, () -> { throw new IllegalStateException("Failed recorder"); });
            fail("Expected recorder failure");
        }
        catch (IllegalStateException expected) { assertNull(saved.get()); }
        assertTrue(tracker.capture(13, () -> {}));
    }
}

