package com.hcimprogression.companion;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import static org.junit.Assert.*;

public class SavedSlayerTasksTest
{
    private static final String ASSIGNMENT="12:0:4:9:49:10:0:0";
    private static SavedSlayerTasks.Record record()
    {
        return new SavedSlayerTasks.Record(ASSIGNMENT,100,123,"crush","Greater demon",
            new SlayerTaskProgress.Saved("Greater demons",40,38,250,500250));
    }
    private static final class Values implements SavedSkillGoals.Values
    {
        final Map<String,String> data=new HashMap<>(); int writes;
        public String read(String key) { return data.get(key); }
        public void write(String key,String value) { data.put(key,value); writes++; }
        public void remove(String key) { data.remove(key); }
    }
    @Test public void restartKeepsTaskCreditXpAndPreparationChoices()
    {
        Values values=new Values(); SavedSlayerTasks first=new SavedSlayerTasks(()->"character-a",values);
        first.save("character-a",record());
        SavedSlayerTasks.Record loaded=new SavedSlayerTasks(()->"character-a",values).load("character-a");
        assertNotNull(loaded); assertEquals(40,loaded.progress.total); assertEquals(38,loaded.progress.remaining);
        assertEquals(250,loaded.progress.xpGained); assertEquals("crush",loaded.style); assertEquals("Greater demon",loaded.monster);
        assertTrue(loaded.matches(ASSIGNMENT,100,123,38));
    }
    @Test public void anotherCharacterCannotReadWriteOrClearThePreviousTrackersRecord()
    {
        Values values=new Values(); AtomicReference<String> owner=new AtomicReference<>("profile-a:character-a");
        SavedSlayerTasks store=new SavedSlayerTasks(owner::get,values); store.save(owner.get(),record());
        owner.set("profile-a:character-b"); assertNull(store.load(owner.get()));
        assertNull(store.load("profile-a:character-a")); store.clear("profile-a:character-a"); store.save("profile-a:character-a",record());
        assertEquals(1,values.writes); owner.set("profile-a:character-a"); assertNotNull(store.load(owner.get()));
        owner.set("profile-b:character-a"); assertNull(store.load(owner.get()));
    }
    @Test public void stopDeletesTheCheckpointAndUnchangedTicksDoNotRewriteIt()
    {
        Values values=new Values(); SavedSlayerTasks store=new SavedSlayerTasks(()->"a",values);
        store.save("a",record()); store.save("a",record()); assertEquals(1,values.writes);
        store.clear("a"); assertNull(new SavedSlayerTasks(()->"a",values).load("a"));
    }
    @Test public void completedChangedReplacedOrAmbiguouslyExtendedAssignmentsDoNotResume()
    {
        SavedSlayerTasks.Record saved=record();
        assertFalse(saved.matches(ASSIGNMENT,100,123,0));
        assertFalse(saved.matches("13:0:4:9:49:10:0:0",100,123,38));
        assertFalse(saved.matches("12:0:5:9:49:10:0:0",100,123,38));
        assertFalse(saved.matches("12:0:4:9:50:10:0:0",100,123,38));
        assertFalse(saved.matches("12:0:4:9:49:11:0:0",100,123,38));
        assertFalse(saved.matches(ASSIGNMENT,120,123,38));
        assertFalse(saved.matches(ASSIGNMENT,100,93,38)); // Paid cancellation while not observed.
        assertFalse(saved.matches(ASSIGNMENT,100,123,39));
        assertTrue(saved.matches(ASSIGNMENT,100,123,30));
    }
    @Test public void malformedOrUnboundedRecordsAreIgnored()
    {
        String valid=SavedSlayerTasks.encode(record());
        for(String invalid:new String[]{null,"",valid.replaceFirst("1\\|","2|"),valid+"|extra",valid.replace("|crush|","|invalid|"),
            valid.replace("|40|38|","|40|41|"),valid.replace("|250|500250","|250|200000001"),"x".repeat(2049)})
            assertNull(SavedSlayerTasks.decode(invalid));
    }
    @Test public void unknownIdentityCannotLoadOrPersistATracker()
    {
        Values values=new Values(); SavedSlayerTasks store=new SavedSlayerTasks(()->"",values);
        store.save("",record()); assertNull(store.load("")); assertEquals(0,values.writes);
    }
}

package com.hcimprogression.companion;

import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class SessionSummaryTest
{
    @Test public void countsLiveXpAndRealLevelsNotExistingProgress()
    {
        SessionSummary summary = new SessionSummary();
        int start = Experience.getXpForLevel(60), end = Experience.getXpForLevel(62);
        summary.start(Map.of(Skill.MINING,start,Skill.FISHING,1000),1000);
        assertEquals(0,summary.xp()); assertEquals(0,summary.levels());
        summary.update(Skill.MINING,end); summary.update(Skill.FISHING,1001);
        assertEquals(end - start + 1,summary.xp()); assertEquals(2,summary.levels());
        assertEquals(2,summary.minutes(121000));
    }

    @Test public void characterResetAndManualRestartDiscardAllPreviousCounters()
    {
        SessionSummary summary = new SessionSummary(); summary.start(Map.of(Skill.MINING,0),0);
        summary.update(Skill.MINING,1000); summary.goalCompleted(); assertEquals(1,summary.goals());
        summary.clear(); assertFalse(summary.active()); assertEquals(0,summary.xp()); assertEquals(0,summary.goals());
        summary.start(Map.of(Skill.MINING,1000),1000); summary.update(Skill.MINING,1010);
        assertEquals(10,summary.xp()); assertEquals(0,summary.goals()); assertEquals(0,summary.minutes(0));
    }

    @Test public void resetXpAndUnknownSkillsNeverInventProgress()
    {
        SessionSummary summary = new SessionSummary(); summary.start(Map.of(Skill.MINING,1000),0);
        summary.update(Skill.MINING,10); summary.update(Skill.FISHING,1000);
        assertEquals(0,summary.xp()); summary.update(Skill.MINING,20); assertEquals(10,summary.xp());
        summary.update(Skill.MINING,-1); assertEquals(10,summary.xp());
    }

    @Test public void virtualLevelsAreNotCountedAsRealLevels()
    {
        SessionSummary summary = new SessionSummary();
        summary.start(Map.of(Skill.MINING,Experience.getXpForLevel(99)),0);
        summary.update(Skill.MINING,Experience.MAX_SKILL_XP); assertEquals(0,summary.levels());
    }

    @Test public void totalXpAcrossSkillsUsesLongCounters()
    {
        java.util.EnumMap<Skill,Integer> xp = new java.util.EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) if (skill != Skill.OVERALL) xp.put(skill,0);
        SessionSummary summary = new SessionSummary(); summary.start(xp,0);
        for (Skill skill : xp.keySet()) summary.update(skill,Experience.MAX_SKILL_XP);
        assertEquals((long) xp.size() * Experience.MAX_SKILL_XP, summary.xp());
    }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class SettingsPresetControllerTest
{
    private static final String[] ACCOUNT = {"automaticAccountSyncEnabled", "weeklyLootTrackingEnabled", "personalBestSyncEnabled",
        "pinnedGoalEnabled", "routineRoutesSyncEnabled", "skillGoalSyncEnabled", "tcgCollectionSyncEnabled"};
    private static final String[] HELPERS = {"progressionPopupsEnabled", "routineRemindersEnabled", "routineRoutesEnabled",
        "livePackingChecksEnabled", "sessionSkillGoalsEnabled", "sessionSummaryEnabled"};
    private static final String[] ALERTS = {"progressionDesktopNotifications", "routineDesktopNotifications", "skillGoalDesktopNotifications"};
    private static final String[] SOCIAL = {"socialPresenceEnabled", "socialClanSyncEnabled", "clanSkillWeekSyncEnabled", "socialClanEventsSyncEnabled"};
    private static final String[] PRIVATE = {"personalBankSyncEnabled", "groupStorageSyncEnabled", "locationSharingEnabled"};

    private static final class Harness
    {
        String profile = "first";
        final Map<String, Map<String, String>> profiles = new HashMap<>();
        final List<String> writes = new ArrayList<>();
        final SettingsPresetController controller = new SettingsPresetController(key -> values().get(key), this::change, () -> profile);
        Map<String, String> values() { return profiles.computeIfAbsent(profile, ignored -> new HashMap<>()); }
        void change(String key, String value)
        {
            if (java.util.Objects.equals(value, values().get(key))) return;
            values().put(key, value);
            writes.add(key);
            // ConfigManager posts events synchronously. Exercise recursive
            // updates rather than relying on a mocked no-event configuration.
            controller.changed(key, value);
        }
        void assertFlags(boolean expected, String... keys)
        {
            for (String key : keys) assertEquals(key, expected, Boolean.parseBoolean(values().get(key)));
        }
        void mode(String selector, SettingsMode mode) { change(selector, mode.name()); }
    }

    @Test
    public void allNewModesAndExistingNetworkFeaturesAreOffByDefault()
    {
        HcimProgressionCompanionConfig config = new HcimProgressionCompanionConfig() {};
        assertEquals(SettingsMode.OFF, config.accountTrackingMode());
        assertEquals(SettingsMode.OFF, config.inGameHelpersMode());
        assertEquals(SettingsMode.OFF, config.desktopAlertsMode());
        assertEquals(SettingsMode.OFF, config.socialSharingMode());
        assertFalse(config.automaticAccountSyncEnabled()); assertFalse(config.weeklyLootTrackingEnabled());
        assertFalse(config.personalBestSyncEnabled()); assertFalse(config.pinnedGoalEnabled());
        assertFalse(config.routineRoutesSyncEnabled()); assertFalse(config.skillGoalSyncEnabled());
        assertFalse(config.tcgCollectionSyncEnabled()); assertFalse(config.socialPresenceEnabled());
        assertFalse(config.socialClanSyncEnabled()); assertFalse(config.clanSkillWeekSyncEnabled());
        assertFalse(config.socialClanEventsSyncEnabled()); assertFalse(config.personalBankSyncEnabled());
        assertFalse(config.groupStorageSyncEnabled()); assertFalse(config.locationSharingEnabled());
        Harness h = new Harness(); h.controller.initialize();
        assertEquals("OFF", h.values().get(SettingsPresetController.ACCOUNT));
        assertEquals(4, h.writes.size());
    }

    @Test
    public void migrationKeepsEveryExistingChoiceWithoutExpandingSharing()
    {
        Harness h = new Harness();
        h.values().put("automaticAccountSyncEnabled", "true");
        h.values().put("weeklyLootTrackingEnabled", "false");
        h.values().put("socialPresenceEnabled", "true");
        h.values().put("socialClanSyncEnabled", "false");
        h.values().put("personalBankSyncEnabled", "true");
        h.values().put("locationSharingEnabled", "false");
        h.values().put("questCompletionPopups", "false");
        h.values().put("apiBaseUrl", "https://example.invalid");
        h.values().put("deviceToken.character", "test-link-value");
        Map<String, String> original = new HashMap<>(h.values());
        h.controller.initialize();
        original.forEach((key, value) -> assertEquals(key, value, h.values().get(key)));
        assertEquals("CUSTOM", h.values().get(SettingsPresetController.ACCOUNT));
        assertEquals("CUSTOM", h.values().get(SettingsPresetController.SOCIAL));
        assertEquals(4, h.writes.size());
        for (String key : h.writes) assertTrue(key.endsWith("Mode"));
    }

    @Test
    public void accountPresetControlsItsFeaturesButNotOptionalSharingOrHelpers()
    {
        Harness h = new Harness(); h.controller.initialize();
        h.mode(SettingsPresetController.ACCOUNT, SettingsMode.ON);
        h.assertFlags(true, ACCOUNT); h.assertFlags(false, PRIVATE); h.assertFlags(false, SOCIAL);
        h.assertFlags(false, HELPERS); h.assertFlags(false, ALERTS);
        assertEquals("ON", h.values().get(SettingsPresetController.ACCOUNT));
        h.mode(SettingsPresetController.ACCOUNT, SettingsMode.OFF);
        h.assertFlags(false, ACCOUNT);
        assertEquals("OFF", h.values().get(SettingsPresetController.ACCOUNT));
    }

    @Test
    public void helperPresetDoesNotEnableUploadsOrUnmuteCustomPopupCategories()
    {
        Harness h = new Harness();
        h.values().put("questCompletionPopups", "false");
        h.values().put("progressionPopupSeconds", "12");
        h.values().put("compactProgressionOverlay", "true");
        h.controller.initialize();
        h.mode(SettingsPresetController.HELPERS, SettingsMode.ON);
        h.assertFlags(true, HELPERS); h.assertFlags(false, ACCOUNT); h.assertFlags(false, PRIVATE);
        h.assertFlags(false, SOCIAL); h.assertFlags(false, ALERTS);
        assertEquals("false", h.values().get("questCompletionPopups"));
        assertEquals("12", h.values().get("progressionPopupSeconds"));
        assertEquals("true", h.values().get("compactProgressionOverlay"));
        h.mode(SettingsPresetController.HELPERS, SettingsMode.OFF);
        h.assertFlags(false, HELPERS);
    }

    @Test
    public void desktopAndSocialPresetsStayWithinTheirConsentBoundaries()
    {
        Harness h = new Harness(); h.controller.initialize();
        h.mode(SettingsPresetController.ALERTS, SettingsMode.ON);
        h.assertFlags(true, ALERTS); h.assertFlags(false, HELPERS); h.assertFlags(false, ACCOUNT);
        h.mode(SettingsPresetController.SOCIAL, SettingsMode.ON);
        h.assertFlags(true, SOCIAL); h.assertFlags(false, PRIVATE); h.assertFlags(false, ACCOUNT);
        h.values().put("locationSharingEnabled", "true");
        h.mode(SettingsPresetController.SOCIAL, SettingsMode.OFF);
        h.assertFlags(false, SOCIAL);
        assertEquals("true", h.values().get("locationSharingEnabled"));
    }

    @Test
    public void detailedEditsUpdateTheSummaryWithoutChangingOtherFlags()
    {
        Harness h = new Harness(); h.controller.initialize();
        h.mode(SettingsPresetController.ACCOUNT, SettingsMode.ON);
        h.change("weeklyLootTrackingEnabled", "false");
        assertEquals("CUSTOM", h.values().get(SettingsPresetController.ACCOUNT));
        assertEquals("true", h.values().get("personalBestSyncEnabled"));
        h.change("weeklyLootTrackingEnabled", "true");
        assertEquals("ON", h.values().get(SettingsPresetController.ACCOUNT));
        int before = h.writes.size();
        h.mode(SettingsPresetController.ACCOUNT, SettingsMode.CUSTOM);
        assertEquals(before + 1, h.writes.size());
        h.assertFlags(true, ACCOUNT);
    }

    @Test
    public void profileSwitchCannotApplyAnOldOnPresetToNewFlags()
    {
        Harness h = new Harness(); h.controller.initialize();
        h.mode(SettingsPresetController.ACCOUNT, SettingsMode.ON);
        h.mode(SettingsPresetController.SOCIAL, SettingsMode.ON);
        h.profile = "second";
        h.values().put(SettingsPresetController.ACCOUNT, "ON");
        h.values().put(SettingsPresetController.SOCIAL, "ON");
        h.controller.changed(SettingsPresetController.ACCOUNT, "ON");
        h.assertFlags(false, ACCOUNT); h.assertFlags(false, SOCIAL); h.assertFlags(false, PRIVATE);
        assertEquals("OFF", h.values().get(SettingsPresetController.ACCOUNT));
        // Remaining profile-load events still contain the stale old selector.
        h.controller.changed(SettingsPresetController.SOCIAL, "ON");
        h.assertFlags(false, SOCIAL);
        h.profile = "first"; h.controller.initialize();
        h.assertFlags(true, ACCOUNT); h.assertFlags(true, SOCIAL);
    }

    @Test
    public void upgradesAndRestartsNeverFillInMissingFutureConsent()
    {
        Harness h = new Harness();
        for (String key : ACCOUNT) h.values().put(key, "true");
        h.values().remove("personalBestSyncEnabled");
        h.values().put(SettingsPresetController.ACCOUNT, "ON");
        h.controller.initialize();
        assertEquals("CUSTOM", h.values().get(SettingsPresetController.ACCOUNT));
        assertNull(h.values().get("personalBestSyncEnabled"));
        h.controller.initialize();
        assertNull(h.values().get("personalBestSyncEnabled"));
    }

    @Test
    public void invalidSelectorsAndUnrelatedKeysNeverEnableFeatures()
    {
        Harness h = new Harness(); h.controller.initialize();
        h.change(SettingsPresetController.ACCOUNT, "UNKNOWN");
        assertEquals("OFF", h.values().get(SettingsPresetController.ACCOUNT));
        h.change("apiBaseUrl", "https://example.invalid");
        h.change("lastTrackedBarrowsChest", "13");
        h.assertFlags(false, ACCOUNT); h.assertFlags(false, HELPERS); h.assertFlags(false, SOCIAL);
        assertFalse(h.controller.updating());
    }

    @Test
    public void quickControlsFitTheSettingsWidthWithoutOpeningRuneScape() throws Exception
    {
        javax.swing.SwingUtilities.invokeAndWait(() -> {
            for (String title : new String[]{"Account tracking", "In-game helpers", "Desktop alerts"})
            {
                javax.swing.JLabel label = new javax.swing.JLabel(title);
                label.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
                javax.swing.JComboBox<String> modes = new javax.swing.JComboBox<>(new String[]{"Off", "On", "Custom"});
                modes.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
                javax.swing.JPanel row = new javax.swing.JPanel(new java.awt.BorderLayout());
                row.add(label, java.awt.BorderLayout.CENTER); row.add(modes, java.awt.BorderLayout.EAST);
                for (int width : new int[]{190, 210, 225})
                {
                    row.setSize(width, 24); row.doLayout();
                    assertTrue(title, label.getWidth() >= label.getFontMetrics(label.getFont()).stringWidth(title));
                    assertTrue(title, modes.getX() + modes.getWidth() <= width);
                }
            }
        });
    }
}

package com.hcimprogression.companion;

import java.awt.Component;
import java.awt.Container;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

/** Standalone Swing layout only. Never opens or interacts with RuneScape. */
public class SidebarControlsTest
{
    @Test public void hintsWrapAtTheAvailableWidthInsteadOfShiftingRight() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            JTextArea text = SidebarControls.text("A long packing instruction with a travel note that needs several lines in a narrow sidebar.");
            text.setSize(210,100);int wide=text.getPreferredSize().height;
            text.setSize(110,100);assertTrue(text.getPreferredSize().height>wide);assertEquals(0f,text.getAlignmentX(),0f);
            text.setText("<img> untrusted & text");assertEquals("<img> untrusted & text",text.getText());
        });
    }
    @Test public void allThreeNavigationButtonsFitAndFoldsKeepDetailsHidden() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            JPanel body=SidebarControls.column();body.add(SidebarControls.text("Very long note for manual review"));
            JPanel fold=SidebarControls.fold("Packing details",body);assertFalse(body.isVisible());
            JButton toggle=(JButton)fold.getComponent(0);toggle.doClick(0);assertTrue(body.isVisible());toggle.doClick(0);assertFalse(body.isVisible());
            JPanel row=SidebarControls.row(SidebarControls.button("Back","",false),SidebarControls.button("Next","",false),SidebarControls.button("Stop","",false));
            for(int width:new int[]{170,190,210}) {row.setSize(width,30);row.doLayout();for(Component item:row.getComponents()) assertTrue(item.getX()+item.getWidth()<=width);}
        });
    }
    @Test public void helperControlsStayInsideNarrowSidebarWithoutLaunchingAClient() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            HcimProgressionCompanionConfig config=new HcimProgressionCompanionConfig(){};
            RoutineRouteHelper routes=new RoutineRouteHelper(null,config,null,null,null);
            SessionGoalHelper goals=new SessionGoalHelper(null,null,config,null);
            SlayerPreparationHelper slayer=new SlayerPreparationHelper(null,null,null,null,null,null,null);
            for(JPanel root:new JPanel[]{routes.panel(),goals.panel(),slayer.panel()}) for(boolean expanded:new boolean[]{false,true}) {
                if(expanded)expandFolds(root);
                for(int width:new int[]{170,190,210}) {
                    root.setSize(width,3000);layout(root);root.setSize(width,root.getPreferredSize().height);layout(root);
                    for(Component item:root.getComponents()) if(item.isVisible()) {assertTrue(item.getX()>=0);assertTrue(item.getX()+item.getWidth()<=width);}
                    checkButtons(root);
                }
            }
        });
    }
    private static void layout(Container parent) {parent.doLayout();for(Component item:parent.getComponents())if(item instanceof Container)layout((Container)item);}
    private static void expandFolds(Container parent) {
        for(Component item:parent.getComponents()) {
            if(item instanceof JButton && item.getName()!=null && item.getName().startsWith("fold-"))((JButton)item).doClick(0);
            if(item instanceof Container)expandFolds((Container)item);
        }
    }
    private static void checkButtons(Container parent) {
        for(Component item:parent.getComponents())if(item.isVisible()) {
            if(item instanceof JButton) {JButton button=(JButton)item;if(!button.getText().isEmpty())assertTrue(button.getText(),button.getFontMetrics(button.getFont()).stringWidth(button.getText())+button.getInsets().left+button.getInsets().right<=button.getWidth());}
            if(item instanceof Container)checkButtons((Container)item);
        }
    }
}

