import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.text.DefaultCaret;
import org.junit.Test;
import static org.junit.Assert.*;

/** Offscreen Swing only: no RuneScape window, inputs or account data. */
public class SidebarScrollTest
{
    @Test public void readOnlyLiveUpdatesDoNotDragTheOuterSidebarToTheirCaret() throws Exception
    {
        AtomicInteger requestedScrolls = new AtomicInteger();
        JPanel[] content = new JPanel[1]; JScrollPane[] scroll = new JScrollPane[1]; JTextArea[] status = new JTextArea[1];
        SwingUtilities.invokeAndWait(() -> {
            content[0] = new JPanel()
            {
                @Override public void scrollRectToVisible(Rectangle bounds) { requestedScrolls.incrementAndGet(); super.scrollRectToVisible(bounds); }
            };
            content[0].setLayout(new BoxLayout(content[0],BoxLayout.Y_AXIS));
            content[0].add(Box.createRigidArea(new Dimension(210,1000)));
            status[0] = SidebarControls.text("Waiting for a task update"); content[0].add(status[0]);
            content[0].add(Box.createRigidArea(new Dimension(210,500)));
            scroll[0] = new JScrollPane(content[0]); scroll[0].setSize(240,220); scroll[0].doLayout();
            content[0].setSize(210,1530); content[0].doLayout();
            BufferedImage image=new BufferedImage(240,220,BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D graphics=image.createGraphics(); scroll[0].printAll(graphics); graphics.dispose();
        });
        flushEdt();
        SwingUtilities.invokeAndWait(() -> {
            scroll[0].getViewport().setViewPosition(new Point(0,120)); requestedScrolls.set(0);
            status[0].setText("Wiki facts loaded. Select the exact variant; requirements and locations may differ.");
        });
        flushEdt();
        SwingUtilities.invokeAndWait(() -> {
            assertEquals("Live status must not request caret-driven scrolling",0,requestedScrolls.get());
            assertEquals(120,scroll[0].getViewport().getViewPosition().y);
            scroll[0].getViewport().setViewPosition(new Point(0,500));
            assertEquals("Manual scrolling is not locked",500,scroll[0].getViewport().getViewPosition().y);
        });
    }
    @Test public void displayTextDoesNotTrackDocumentEditsButEditablePackingListsStillDo() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            JTextArea display=SidebarControls.text("Read-only stats");
            assertEquals(DefaultCaret.NEVER_UPDATE,((DefaultCaret)display.getCaret()).getUpdatePolicy());
            JTextArea editor=new JTextArea(); SidebarControls.editor(editor,100);
            assertEquals(DefaultCaret.UPDATE_WHEN_ON_EDT,((DefaultCaret)editor.getCaret()).getUpdatePolicy());
        });
    }
    @Test public void repeatedUnchangedStatusDoesNotReplaceTheDocument() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            JTextArea display=SidebarControls.text("Wiki facts loaded"); AtomicInteger changes=new AtomicInteger();
            display.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
            {
                public void insertUpdate(javax.swing.event.DocumentEvent event) { changes.incrementAndGet(); }
                public void removeUpdate(javax.swing.event.DocumentEvent event) { changes.incrementAndGet(); }
                public void changedUpdate(javax.swing.event.DocumentEvent event) { changes.incrementAndGet(); }
            });
            display.setText("Wiki facts loaded"); assertEquals(0,changes.get());
            display.setText("Task count changed"); assertTrue(changes.get() > 0);
        });
    }
    private static void flushEdt() throws Exception { SwingUtilities.invokeAndWait(() -> {}); SwingUtilities.invokeAndWait(() -> {}); }
}

package com.hcimprogression.companion;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiConsumer;
import org.junit.Test;
import static org.junit.Assert.*;

public class SkillGoalSyncTest
{
    private static final class Harness
    {
        final AtomicBoolean enabled = new AtomicBoolean(true);
        final List<SkillGoalSync.Goal> sent = new ArrayList<>();
        final List<BiConsumer<SkillGoalSync.Response,String>> callbacks = new ArrayList<>();
        final SkillGoalSync sync = new SkillGoalSync(enabled::get,(name,token,api,goal,callback) -> {sent.add(goal); callbacks.add(callback);});
        Harness() {sync.connection("HP Shooter","fake-token","fake-api");}
        void accept(int index,String status) {SkillGoalSync.Response value = new SkillGoalSync.Response(); value.ok=true;value.status=status;value.sequence=sent.get(index).sequence;callbacks.get(index).accept(value,null);}
    }
    @Test public void startsOnceThenCoalescesXpAndSendsCompletionPromptly()
    {
        Harness h = new Harness(); h.sync.start("Mining",false,0,1000,2000); h.sync.tick(0); assertEquals(1,h.sent.size());h.accept(0,"active");
        h.sync.progress(1250,false);h.sync.progress(1500,false);h.sync.tick(3000);assertEquals(1,h.sent.size());
        h.sync.tick(120000);assertEquals(2,h.sent.size()); assertEquals(1500,h.sent.get(1).currentXp);h.accept(1,"active");
        h.sync.progress(2000,true);h.sync.tick(123000);assertEquals("completed",h.sent.get(2).status);
        assertEquals(1000,h.sent.get(0).currentXp); // In-flight snapshots are immutable.
    }
    @Test public void optOutNeverUploadsAndDisablingClearsPendingUpdates()
    {
        Harness h = new Harness();h.enabled.set(false);h.sync.start("Mining",false,0,1000,2000);h.sync.tick(0);assertTrue(h.sent.isEmpty());
        h.enabled.set(true);h.sync.request();h.sync.tick(3000);assertEquals(1,h.sent.size());
        h.sync.progress(2000,true);h.enabled.set(false);h.sync.tick(4000);h.accept(0,"active");h.sync.tick(8000);assertEquals(1,h.sent.size());
    }
    @Test public void lateCallbacksAndQueuedGoalsCannotFollowCharacterSwitch()
    {
        Harness h = new Harness();h.sync.start("Mining",false,0,1000,2000);h.sync.tick(0);
        h.sync.connection("SW Shooter","other-token","fake-api");h.accept(0,"active");h.sync.tick(130000);
        assertEquals(1,h.sent.size()); assertFalse(h.sync.status().contains("Saved to"));
        h.sync.start("Fishing",false,0,20,30);h.sync.tick(133000);assertEquals("Fishing",h.sent.get(1).skill);
    }
    @Test public void replacingAnActiveGoalStopsItBeforeSendingNewGoal()
    {
        Harness h = new Harness();h.sync.start("Mining",false,0,1000,2000);h.sync.tick(0);h.accept(0,"active");
        h.sync.start("Fishing",false,0,100,200);h.sync.tick(3000);assertEquals("stopped",h.sent.get(1).status);h.accept(1,"stopped");
        h.sync.tick(6000);assertEquals("Fishing",h.sent.get(2).skill);assertNotEquals(h.sent.get(0).id,h.sent.get(2).id);
    }
    @Test public void stoppedWebsiteGoalsAreNeverResurrectedByLaterXp()
    {
        Harness h = new Harness();h.sync.start("Mining",false,0,1000,2000);h.sync.tick(0);h.accept(0,"stopped");
        h.sync.progress(1500,false);h.sync.tick(130000);assertEquals(1,h.sent.size());
    }
    @Test public void unchangedGoalDoesNotMakeRepeatedNetworkRequests()
    {
        Harness h = new Harness();h.sync.start("Mining",false,0,1000,2000);h.sync.tick(0);h.accept(0,"active");
        h.sync.tick(130000);h.sync.tick(260000);assertEquals(1,h.sent.size());
    }

    @Test public void relogResumesTheOriginalWebsiteGoalWithoutCreatingAnotherTask()
    {
        Harness h=new Harness(); h.sync.start("Mining",false,0,1000,2000); h.sync.progress(1456,false);
        SkillGoalSync.Goal saved=h.sync.snapshot();
        h.sync.reset(); h.sync.connection("HP Shooter","fake-token","fake-api"); h.sync.restore(saved); h.sync.tick(3000);
        assertEquals(1,h.sent.size()); assertEquals(saved.id,h.sent.get(0).id);
        assertEquals(1000,h.sent.get(0).startXp); assertEquals(1456,h.sent.get(0).currentXp);
        assertTrue(h.sent.get(0).sequence>saved.sequence);
        assertEquals(saved.sequence, saved.copy().sequence);
    }

    @Test public void restoringAWebsiteStoppedGoalDoesNotResurrectItsUpload()
    {
        Harness h=new Harness(); SkillGoalSync.Goal saved=SavedSkillGoalsTest.goal(); saved.status="stopped";
        h.sync.restore(saved); h.sync.progress(saved.currentXp+1,false); h.sync.tick(3000);
        assertTrue(h.sent.isEmpty()); assertEquals("stopped",h.sync.snapshot().status);
    }

    @Test public void lateRequestsFromBeforeLogoutCannotChangeTheRestoredGoal()
    {
        Harness h=new Harness(); h.sync.start("Mining",false,0,1000,2000); h.sync.tick(0);
        SkillGoalSync.Goal saved=h.sync.snapshot(); h.sync.reset();
        h.sync.connection("HP Shooter","fake-token","fake-api"); h.sync.restore(saved);
        h.accept(0,"stopped"); assertEquals("active",h.sync.snapshot().status);
        h.sync.tick(3000); assertEquals(2,h.sent.size()); assertEquals(saved.id,h.sent.get(1).id);
    }
}

package com.hcimprogression.companion;

import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class SkillSessionGoalTest
{
    @Test public void xpGoalTracksOnlyItsSelectedSkill()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING, 1000, 2000);
        assertFalse(goal.update(Skill.WOODCUTTING, 3000)); assertEquals(0, goal.gained());
        assertFalse(goal.update(Skill.MINING, 1250)); assertEquals(25.0, goal.percent(), 0.00001);
        assertEquals(750, goal.remaining()); assertEquals(250, goal.gained());
    }

    @Test public void completionAnnouncesExactlyOnceAndOverrunClampsPercent()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.PRAYER, 1000, 2000);
        assertTrue(goal.update(Skill.PRAYER, 2200)); assertEquals(100.0, goal.percent(), 0.00001); assertEquals(0, goal.remaining());
        assertFalse(goal.update(Skill.PRAYER, 2200)); assertFalse(goal.update(Skill.PRAYER, 2300));
        assertTrue(goal.complete());
    }

    @Test public void reachingLevelUsesTheRuneLiteXpTable()
    {
        assertEquals(Experience.getXpForLevel(70), SkillSessionGoal.target(1000, true, 70));
        assertEquals(1500, SkillSessionGoal.target(1000, false, 500));
    }

    @Test public void resetAndFallingXpCannotCompleteAPreviousCharactersGoal()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING, 1000, 2000);
        goal.clear(); assertNull(goal.skill()); assertFalse(goal.update(Skill.MINING, 3000));
        goal.start(Skill.MINING, 1000, 2000); goal.update(Skill.MINING, 1200);
        assertFalse(goal.update(Skill.MINING, 1100)); assertNull(goal.skill()); assertEquals(0.0,goal.percent(),0.00001);
    }

    @Test public void invalidUnreachableOrAlreadyMetGoalsAreRejected()
    {
        for (int target : new int[]{-1, 1000, Experience.MAX_SKILL_XP + 1})
        {
            try { new SkillSessionGoal().start(Skill.MINING, 1000, target); fail(); }
            catch (IllegalArgumentException expected) { }
        }
        for (int level : new int[]{0, 1, 100, Integer.MAX_VALUE})
        {
            try { SkillSessionGoal.target(1000,true,level); fail(); }
            catch (IllegalArgumentException expected) { }
        }
        try { SkillSessionGoal.target(Experience.MAX_SKILL_XP - 1,false,100); fail(); }
        catch (IllegalArgumentException expected) { }
        try { new SkillSessionGoal().start(Skill.OVERALL,0,100); fail(); }
        catch (IllegalArgumentException expected) { }
    }

    @Test public void largeXpTargetsDoNotOverflowTheProgressBar()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING,0,Experience.MAX_SKILL_XP);
        goal.update(Skill.MINING,100_000_000); assertEquals(50.0,goal.percent(),0.00001);
    }

    @Test public void replacingCompletedGoalCreatesAFreshCompletionAndNewBaseline()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING,0,10); assertTrue(goal.update(Skill.MINING,10));
        goal.start(Skill.MINING,10,20); assertEquals(0,goal.gained()); assertFalse(goal.complete());
        assertTrue(goal.update(Skill.MINING,20));
    }

    @Test public void percentagesUseDynamicXpAndRoundToTenthsWithoutTruncatingTheBar()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING,1000,11000);
        assertEquals("0.0%",goal.percentText());
        goal.update(Skill.MINING,5564); assertEquals(45.64,goal.percent(),0.00001);
        assertEquals("45.6%",goal.percentText()); assertEquals(456,SessionGoalHelper.goalBarValue(goal.percent()));
        goal.update(Skill.MINING,5565); assertEquals("45.7%",goal.percentText());
        assertEquals(457,SessionGoalHelper.goalBarValue(goal.percent())); assertFalse(goal.complete());
    }

    @Test public void restoredGoalKeepsItsOriginalBaselineAndCountsXpFromAnotherSession()
    {
        SkillSessionGoal goal=new SkillSessionGoal(); goal.restore(Skill.MINING,1000,2000,1456);
        assertEquals(456,goal.gained()); assertEquals("45.6%",goal.percentText());
        assertFalse(goal.update(Skill.MINING,1500)); assertEquals(500,goal.gained());
        assertTrue(goal.update(Skill.MINING,2000)); assertFalse(goal.update(Skill.MINING,2000));
    }

    @Test public void completedRestoreNeverReplaysACompletionNotification()
    {
        SkillSessionGoal goal=new SkillSessionGoal(); goal.restore(Skill.MINING,1000,2000,2001);
        assertTrue(goal.complete()); assertEquals("100.0%",goal.percentText());
        assertFalse(goal.update(Skill.MINING,2001)); assertFalse(goal.update(Skill.MINING,2002));
    }

    @Test public void restoringWithInvalidXpDoesNotLeaveAHalfRestoredGoal()
    {
        SkillSessionGoal goal=new SkillSessionGoal();
        try { goal.restore(Skill.MINING,1000,2000,999); fail(); } catch(IllegalArgumentException expected) { }
        assertNull(goal.skill());
    }

    @Test public void roundingCannotMarkAnUnfinishedGoalComplete()
    {
        SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.MINING,0,Experience.MAX_SKILL_XP);
        assertFalse(goal.update(Skill.MINING,Experience.MAX_SKILL_XP-1));
        assertEquals("99.9%",goal.percentText()); assertEquals(999,SessionGoalHelper.goalBarValue(goal.percent()));
        assertFalse(goal.complete());
        assertTrue(goal.update(Skill.MINING,Experience.MAX_SKILL_XP));
        assertEquals("100.0%",goal.percentText()); assertEquals(1000,SessionGoalHelper.goalBarValue(goal.percent()));
        goal.clear(); assertEquals("0.0%",goal.percentText());
    }

    @Test public void percentageFormattingDoesNotDependOnSystemDecimalSeparator()
    {
        java.util.Locale previous = java.util.Locale.getDefault();
        try
        {
            java.util.Locale.setDefault(java.util.Locale.GERMANY);
            SkillSessionGoal goal = new SkillSessionGoal(); goal.start(Skill.FISHING,0,1000);
            goal.update(Skill.FISHING,123); assertEquals("12.3%",goal.percentText());
        }
        finally { java.util.Locale.setDefault(previous); }
    }

    @Test public void localFeaturesDefaultOffAndNeedNoNetworkSettings()
    {
        HcimProgressionCompanionConfig config = new HcimProgressionCompanionConfig() {};
        assertFalse(config.livePackingChecksEnabled()); assertFalse(config.sessionSkillGoalsEnabled());
        assertFalse(config.skillGoalDesktopNotifications()); assertFalse(config.routineRoutesSyncEnabled());
        assertFalse(config.automaticAccountSyncEnabled());
    }
}

package com.hcimprogression.companion;

import org.junit.Test;
import static org.junit.Assert.*;

public class SlayerAssignmentWatchTest
{
    private static final String FIRST = "12:0:4:9:49:10:0:0";
    private static final String NEXT = "13:0:5:9:50:10:0:0";
    private static SlayerAssignmentWatch loggedIn(String assignment,int remaining)
    {
        SlayerAssignmentWatch watch=new SlayerAssignmentWatch();
        assertFalse(watch.observe(assignment,remaining));
        assertFalse(watch.observe(assignment,remaining));
        return watch;
    }

    @Test public void loginAndTaskRemindersDoNotStartAnExistingAssignment()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,40);
        for(int i=0;i<10;i++) assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,39));
        assertFalse(watch.observe(FIRST,38));
        watch.reset();
        assertFalse(watch.observe(FIRST,38));
        assertFalse(watch.observe(FIRST,38));
        assertFalse(watch.observe(FIRST,37));
    }

    @Test public void incompleteLoginPacketsOnlyEstablishABaseline()
    {
        SlayerAssignmentWatch watch=new SlayerAssignmentWatch();
        assertFalse(watch.observe("0:0:0:0:0:0:0:0",0));
        assertFalse(watch.observe(FIRST,0));
        assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,39));
    }

    @Test public void receivingFirstAssignmentAutomaticallyStartsOnceAfterSettling()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,0);
        assertFalse(watch.observe(NEXT,150));
        assertTrue(watch.observe(NEXT,150));
        assertFalse(watch.observe(NEXT,150));
        assertFalse(watch.observe(NEXT,149));
    }

    @Test public void completionThenSameMonsterStillStartsANewTracker()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,1);
        assertFalse(watch.observe(FIRST,0));
        assertFalse(watch.observe(FIRST,100));
        assertTrue(watch.observe(FIRST,100));
        assertFalse(watch.observe(FIRST,100));
    }

    @Test public void changedMonsterAreaBossOrStreakCanStartWithoutAnEmptyCountTick()
    {
        for(String next:new String[]{NEXT,"12:1:4:9:49:10:0:0","12:0:5:9:49:10:0:0","12:0:4:9:50:10:0:0"})
        {
            SlayerAssignmentWatch watch=loggedIn(FIRST,20);
            assertFalse(watch.observe(next,100));
            assertTrue(watch.observe(next,99));
            assertFalse(watch.observe(next,98));
        }
    }

    @Test public void transientAssignmentPacketsDoNotStartAnIntermediateTask()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,20);
        assertFalse(watch.observe("13:0:4:9:49:10:0:0",100));
        assertFalse(watch.observe(NEXT,100));
        assertTrue(watch.observe(NEXT,100));
        assertFalse(watch.observe(NEXT,100));
    }

    @Test public void countExtensionsAndStoppedCurrentTasksDoNotRestart()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,20);
        assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,39));
        // Stop keeps the assignment baseline, while the next distinct task starts.
        assertFalse(watch.observe(NEXT,80));
        assertTrue(watch.observe(NEXT,80));
        watch.reset(); // Logout/profile change cannot compare against another character.
        assertFalse(watch.observe(FIRST,40));
        assertFalse(watch.observe(FIRST,40));
    }

    @Test public void cancellationAndRevertedPacketsDoNotResurrectOldTasks()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,20);
        assertFalse(watch.observe(NEXT,100));
        assertFalse(watch.observe(FIRST,20));
        assertFalse(watch.observe(FIRST,20));
        assertFalse(watch.observe(NEXT,100));
        assertFalse(watch.observe(NEXT,0));
        assertFalse(watch.observe(NEXT,0));
        assertFalse(watch.observe(NEXT,80));
        assertTrue(watch.observe(NEXT,80));
    }

    @Test public void newTrackerStartsWithItsOwnCountAndXpThenCanBeSaved()
    {
        SlayerAssignmentWatch watch=loggedIn(FIRST,20);
        SlayerTaskProgress progress=new SlayerTaskProgress();
        progress.start("Old task",20,500000);
        progress.observe(10,1); progress.experience(501000,1);
        assertFalse(watch.observe(NEXT,100));
        assertTrue(watch.observe(NEXT,100));
        progress.start("New task",100,501000);
        assertEquals(0,progress.view(2).done);
        assertEquals(0,progress.view(2).xpGained);
        progress.observe(99,3); progress.experience(501125,3);
        SlayerTaskProgress restored=new SlayerTaskProgress();
        assertTrue(restored.restore(progress.save(3),99,501125));
        assertEquals(1,restored.view(4).done);
        assertEquals(125,restored.view(4).xpGained);
    }
}

package com.hcimprogression.companion;

import com.google.gson.Gson;
import com.google.inject.Guice;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

/** Pure ownership/planning fixtures. Never opens or operates RuneScape. */
public class SlayerBankPlannerTest
{
    // Inject the same resource deserializer type as production, rather than constructing Gson.
    private final SlayerBankPlanner planner = SlayerBankPlanner.load(Guice.createInjector().getInstance(Gson.class));
    private static Map<String, Integer> levels()
    {
        Map<String, Integer> result = new HashMap<>();
        for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Slayer", "Agility", "Hitpoints"}) result.put(skill, 99);
        return result;
    }
    private static List<SlayerBankPlanner.Owned> bank(String... names)
    {
        List<SlayerBankPlanner.Owned> result = new ArrayList<>();
        // Fixture-only IDs, not live game item IDs.
        for (int i = 0; i < names.length; i++) result.add(new SlayerBankPlanner.Owned(i + 1, names[i], 1));
        return result;
    }
    private SlayerBankPlanner.Plan plan(String target, String style, String... names) { return planner.plan(target, style, bank(names), levels()); }
    @Test public void emptyBankCannotInventAWornOrUnlockedWeapon()
    {
        SlayerBankPlanner.Plan result = plan("Abyssal demon", "melee");
        assertTrue(result.blocked); assertTrue(result.gear.isEmpty()); assertTrue(result.highlights().isEmpty());
    }
    @Test public void choosesHighestSupportedOwnedUsableGear()
    {
        SlayerBankPlanner.Plan result = plan("Abyssal demon", "melee", "Rune scimitar", "Abyssal whip", "Dragon boots", "Rune boots");
        assertFalse(result.blocked); assertEquals("Abyssal whip", result.gear.get("weapon").name);
        assertEquals("Dragon boots", result.gear.get("feet").name); assertEquals(2, result.highlights().size());
    }
    @Test public void filtersRequirementsAndFailsClosedWhenLevelUnknown()
    {
        Map<String, Integer> skills = levels(); skills.put("Attack", 50);
        SlayerBankPlanner.Plan result = planner.plan("Bloodveld", "melee", bank("Abyssal whip", "Rune scimitar"), skills);
        assertEquals("Rune scimitar", result.gear.get("weapon").name);
        assertTrue(planner.plan("Bloodveld", "melee", bank("Rune scimitar"), Collections.emptyMap()).blocked);
    }
    @Test public void excludesZeroQuantitiesAndInvalidIds()
    {
        assertTrue(planner.plan("Bloodveld", "melee", Arrays.asList(
            new SlayerBankPlanner.Owned(1, "Abyssal whip", 0), new SlayerBankPlanner.Owned(-1, "Rune scimitar", 2)), levels()).blocked);
    }
    @Test public void aliasesOnlyKnownUsableVariants()
    {
        assertEquals("slayer helmet (i)", planner.canonical("Black slayer helmet (i)"));
        assertEquals("amulet of glory", planner.canonical("Amulet of glory(6)"));
        assertEquals("verac's plateskirt", planner.canonical("Verac's plateskirt 75"));
        assertEquals("verac's plateskirt 0", planner.canonical("Verac's plateskirt 0"));
        assertEquals("black mask (i)", planner.canonical("Black mask (10) (i)"));
        assertEquals("bow of faerdhinen", planner.canonical("Bow of faerdhinen (c) (red)"));
        assertEquals("unknown armour (broken)", planner.canonical("Unknown armour (broken)"));
    }
    @Test public void twoHandedWeaponNeverIncludesShield()
    {
        SlayerBankPlanner.Plan result = plan("Abyssal demon", "melee", "Soulreaper axe", "Abyssal whip", "Dragon defender");
        assertEquals("Soulreaper axe", result.gear.get("weapon").name); assertFalse(result.gear.containsKey("shield"));
    }
    @Test public void bowsRequireCompatibleArrowsRatherThanBolts()
    {
        assertTrue(plan("Bloodveld", "ranged", "Magic shortbow", "Diamond bolts (e)").blocked);
        SlayerBankPlanner.Plan result = plan("Bloodveld", "ranged", "Magic shortbow", "Dragon arrow", "Rune arrow");
        assertFalse(result.blocked); assertEquals("Rune arrow", result.gear.get("ammo").name);
    }
    @Test public void runeCrossbowCannotUseDragonBolts()
    {
        assertTrue(plan("Bloodveld", "ranged", "Rune crossbow", "Diamond dragon bolts (e)").blocked);
        SlayerBankPlanner.Plan result = plan("Bloodveld", "ranged", "Rune crossbow", "Diamond dragon bolts (e)", "Diamond bolts (e)");
        assertFalse(result.blocked); assertEquals("Diamond bolts (e)", result.gear.get("ammo").name);
    }
