package com.hcimprogression.companion;

import org.junit.Test;
import static org.junit.Assert.*;

public class SlayerTaskProgressTest
{
    @Test public void startsAtZeroFromTheRemainingAssignmentNotLifetimeKc()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress();
        assertNull(progress.view(0)); progress.start("Greater demons",124,1000);
        assertEquals(124,progress.view(0).total); assertEquals(0,progress.view(0).done); assertEquals(0.0,progress.view(0).percent,0.00001);
        progress.observe(100,1000); assertEquals(24,progress.view(1000).done); assertEquals(100,progress.view(1000).remaining);
    }
    @Test public void countCreditsHandleExpeditiousAndSlaughterWithoutInventingKills()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Greater demons",100,1000);
        progress.observe(100,1); assertEquals(0,progress.view(1).done);
        progress.observe(98,2); assertEquals(2,progress.view(2).done); assertEquals(2.0,progress.view(2).percent,0.00001);
    }
    @Test public void extensionsPreserveProgressAndCannotMakeNegativePercent()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Bloodveld",10,1000);
        progress.observe(5,0); progress.observe(15,1);
        assertEquals(20,progress.view(1).total); assertEquals(5,progress.view(1).done); assertEquals(25.0,progress.view(1).percent,0.00001);
    }
    @Test public void completionDisplaysBrieflyThenExpiresWithoutMutatingOnRender()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Bloodveld",5,1000); progress.observe(0,1000);
        assertEquals(100.0,progress.view(1000).percent,0.00001); assertEquals(5,progress.view(1000).done);
        progress.observe(0,5000); assertNull(progress.view(9000));
    }
    @Test public void slayerXpUsesTheStartedBaselineNotKillsOrLifetimeExperience()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Greater demons",100,500000);
        assertEquals(0,progress.view(0).xpGained);
        progress.experience(501234,1); assertEquals(1234,progress.view(1).xpGained);
        assertEquals(0,progress.view(1).done);
        assertEquals("0.0% · +1,234 XP",progress.view(1).barLabel);
        progress.observe(98,2); assertEquals(1234,progress.view(2).xpGained);
        progress.observe(99,3); assertEquals(1234,progress.view(3).xpGained);
        progress.experience(501234,4); assertEquals(1234,progress.view(4).xpGained);
    }

    @Test public void finalXpCanArriveAfterTheCountWithoutExtendingTheCompletionPopup()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Bloodveld",1,1000);
        progress.observe(0,1000); progress.experience(1100,1100);
        assertEquals(100,progress.view(1100).xpGained); assertEquals(100.0,progress.view(1100).percent,0.00001);
        progress.experience(1200,9000); assertNull(progress.view(9000));
    }

    @Test public void stopRestartAndFallingXpDiscardThePreviousBaseline()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Bloodveld",10,1000);
        progress.experience(1200,1); progress.stop(); progress.experience(2000,2); assertNull(progress.view(2));
        progress.start("Dust devils",10,2000); assertEquals(0,progress.view(2).xpGained);
        progress.experience(2100,3); assertEquals(100,progress.view(3).xpGained);
        progress.experience(1000,4); assertNull(progress.view(4));
        progress.start("Unknown XP",10,-1); assertNull(progress.view(4));
    }

    @Test public void taskCountPercentageAlsoKeepsTenthsAndDoesNotRoundUpToComplete()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Dust devils",3,1000);
        progress.observe(2,1); progress.experience(1110,2);
        assertEquals("33.3% · +110 XP",progress.view(2).barLabel);
        progress.start("Large task",10000,0); progress.observe(1,3);
        assertEquals("99.9% · +0 XP",progress.view(3).barLabel);
    }

    @Test public void stopOrRestartNeverCarriesThePreviousTaskCount()
    {
        SlayerTaskProgress progress = new SlayerTaskProgress(); progress.start("Bloodveld",30,1000); progress.observe(10,0);
        progress.stop(); assertNull(progress.view(0)); progress.start("Dust devil",15,1000);
        assertEquals(0,progress.view(0).done); assertEquals("Dust devil",progress.view(0).task);
        progress.start("None",0,1000); assertNull(progress.view(0));
    }

    @Test public void restoredTrackerRetainsCreditAndXpAcrossLogins()
    {
        SlayerTaskProgress first=new SlayerTaskProgress(); first.start("Greater demons",40,500000);
        first.observe(38,1); first.experience(500250,2);
        SlayerTaskProgress restored=new SlayerTaskProgress(); assertTrue(restored.restore(first.save(2),38,500250));
        assertEquals(2,restored.view(3).done); assertEquals(250,restored.view(3).xpGained);
        restored.experience(500375,4); restored.observe(37,4);
        assertEquals(3,restored.view(4).done); assertEquals(375,restored.view(4).xpGained);
    }

    @Test public void unrelatedXpBetweenClientsIsNotInventedAsTrackedTaskXp()
    {
        SlayerTaskProgress first=new SlayerTaskProgress(); first.start("Greater demons",40,500000);
        first.observe(38,1); first.experience(500250,2);
        SlayerTaskProgress restored=new SlayerTaskProgress(); assertTrue(restored.restore(first.save(2),35,510000));
        assertEquals(5,restored.view(3).done); assertEquals(250,restored.view(3).xpGained);
        restored.experience(510125,4); assertEquals(375,restored.view(4).xpGained);
    }

    @Test public void invalidCompletedOrUnsettledRestoresAreNotShown()
    {
        SlayerTaskProgress first=new SlayerTaskProgress(); first.start("Greater demons",40,500000);
        first.experience(500250,1); SlayerTaskProgress.Saved checkpoint=first.save(1);
        SlayerTaskProgress restored=new SlayerTaskProgress();
        assertFalse(restored.restore(checkpoint,40,0)); assertNull(restored.view(2));
        assertFalse(restored.restore(checkpoint,41,500250)); assertNull(restored.view(2));
        assertFalse(restored.restore(checkpoint,0,500250));
        first.observe(0,2); assertNull(first.save(2));
    }
}

package com.hcimprogression.companion;

import org.junit.Test;
import static org.junit.Assert.*;

/** Offline factual-field fixtures; no network or game access. */
public class SlayerWikiGuideTest
{
    @Test public void keepsVariantStatsSeparateAndReadsCurrentWeaknessKeys()
    {
        SlayerWikiGuide guide = SlayerWikiGuide.parse("Dust devil", 123, "{{Infobox Monster\n"
            + "|version1 = Smoke Dungeon\n|version2 = Catacombs of Kourend\n|name = Dust devil\n"
            + "|combat1 = 93\n|combat2 = 110\n|hitpoints1 = 105\n|hitpoints2 = 130\n|def1 = 80\n"
            + "|elementalweaknesstype = Air\n|elementalweaknesspercent = 35\n|dlight = 20\n}}\n"
            + "{{LocLine\n|location = [[Kourend|Catacombs of Kourend]]\n|levels=110\n}}\n");
        assertEquals(2, guide.variants.size());
        assertTrue(guide.variants.get(0).stats.contains("HP: 105"));
        assertFalse(guide.variants.get(1).stats.contains("105"));
        assertFalse(guide.variants.get(1).stats.contains("Defence: 80"));
        assertTrue(guide.variants.get(1).stats.contains("Elemental weakness: Air"));
        assertTrue(guide.variants.get(1).stats.contains("bonus (%): 35"));
        assertTrue(guide.variants.get(1).stats.contains("Light ranged defence: 20"));
        assertEquals("Catacombs of Kourend", guide.locations); assertEquals(123, guide.revision);
    }
    @Test public void readsNestedTemplatesWithoutAccidentallyUsingOtherInfoboxes()
    {
        SlayerWikiGuide guide = SlayerWikiGuide.parse("Bloodveld", 1,
            "{{Infobox Monster\n|name = Bloodveld\n|hitpoints = 120\n|max hit = {{maxhit|5}}\n}}\n"
            + "{{Infobox Monster\n|name = unrelated\n|hitpoints = 999\n}}\n");
        assertEquals(1, guide.variants.size()); assertTrue(guide.variants.get(0).stats.contains("HP: 120"));
        assertFalse(guide.variants.get(0).stats.contains("999"));
        assertTrue(guide.variants.get(0).stats.contains("Weakness: not listed"));
        assertTrue(guide.locations.contains("No structured locations"));
    }
    @Test public void numberedElementalWeaknessOverridesCommonButDoesNotLeak()
    {
        SlayerWikiGuide guide = SlayerWikiGuide.parse("Example", 1,
            "{{Infobox Monster\n|version1=A\n|version2=B\n|elementalweaknesstype1=Water\n|elementalweaknesspercent1=50\n}}\n");
        assertTrue(guide.variants.get(0).stats.contains("Water"));
        assertFalse(guide.variants.get(1).stats.contains("Water"));
        assertTrue(guide.variants.get(1).stats.contains("not listed"));
    }
    @Test public void rejectsUrlsControlCharactersAndOversizedTitles()
    {
        for (String bad : new String[]{"https://evil.example", "../Foo", "<img>", "a\nb", "a@b", "", "x".repeat(101)})
            try { SlayerWikiGuide.validTitle(bad); fail(bad); } catch (IllegalArgumentException expected) { }
        assertEquals("https://oldschool.runescape.wiki/w/Dust_devil", SlayerWikiGuide.url("Dust_devil"));
    }
    @Test public void malformedOrTooLargePagesFailWithNoInventedMonster()
    {
        for (String bad : new String[]{"No monster here", "{{Infobox Monster\n|hitpoints = 1", "x".repeat(500_001)})
            try { SlayerWikiGuide.parse("Example", 1, bad); fail("invalid input"); } catch (IllegalArgumentException expected) { }
    }
    @Test public void rendersPlainBoundedTextInsteadOfDownloadedHtml()
    {
        assertEquals("Dust devil & desert", SlayerWikiGuide.clean("'''[[Dust devil]]''' &amp; <b>desert</b><ref>footnote</ref>"));
        assertTrue(SlayerWikiGuide.clean("a".repeat(1000)).length() < 400);
    }
    @Test public void taskLabelsAreMappedOnlyWhenUnambiguous()
    {
        assertEquals("Dust devil", SlayerWikiGuide.monsterTitle("DUST DEVILS"));
        assertEquals("Blue dragon", SlayerWikiGuide.monsterTitle("Blue dragons"));
        assertEquals("Metal dragons", SlayerWikiGuide.monsterTitle("Metal dragons"));
    }
    @Test public void locationsAreUniqueAndBounded()
    {
        StringBuilder source = new StringBuilder("{{Infobox Monster\n|name = Example\n}}\n");
        for (int i = 0; i < 20; i++) source.append("{{LocLine\n|location = [[Area ").append(i / 2).append("]]\n}}\n");
        SlayerWikiGuide guide = SlayerWikiGuide.parse("Example", 1, source.toString());
        assertEquals(10, guide.locations.split("\n").length);
    }
}

package com.hcimprogression.companion;

import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

/** Standalone Swing facts only. No game client or game input. */
public class SlayerWikiPanelTest
{
    static SlayerWikiGuide greaterDemon()
    {
        // Public fields verified against OSRS Wiki revision 15315063.
        return SlayerWikiGuide.parse("Greater demon",15315063,
            "{{Infobox Monster\n|version1=Level 92\n|version2=Level 100\n|name=Greater demon\n"
            + "|combat1=92\n|combat2=100\n|hitpoints1=87\n|hitpoints2=115\n|att1=76\n|att2=90\n|str1=78\n|str2=70\n"
            + "|def1=81\n|def2=80\n|mage=1\n|range=1\n|max hit1=9\n|max hit2=8\n|attack style=[[Slash]]\n"
            + "|dstab=0\n|dslash=0\n|dcrush=0\n|dmagic=-10\n|dlight=0\n|dstandard=0\n|dheavy=0\n"
            + "|elementalweaknesstype=Water\n|elementalweaknesspercent=40\n}}\n"
            + "{{LocLine\n|location=[[Catacombs of Kourend]]\n}}\n{{LocLine\n|location=[[Chasm of Fire]]\n}}\n");
    }
    @Test public void firstVariantStatsWeaknessAndLocationsDisplayTogetherWithoutAnotherClick() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            SlayerWikiPanel view = new SlayerWikiPanel(); view.show(greaterDemon(),"Wiki facts loaded",false);
            String text = text(view.panel());
            assertTrue(text.contains("87")); assertTrue(text.contains("Water · +40%"));
            assertTrue(text.contains("Catacombs of Kourend")); assertTrue(text.contains("Chasm of Fire"));
            assertTrue(text.contains("15315063"));
            JComboBox<?> variants = components(view.panel()).stream().filter(JComboBox.class::isInstance).map(JComboBox.class::cast).findFirst().get();
            variants.setSelectedIndex(1); text = text(view.panel()); assertTrue(text.contains("115")); assertFalse(text.contains("87"));
        });
    }
    @Test public void loadingAndErrorsDoNotLeaveEmptyVariantDropdownOrPreviousMonsterFacts() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            SlayerWikiPanel view = new SlayerWikiPanel();
            view.show(greaterDemon(),"Ready",false); view.show(null,"Loading stats and locations…",true);
            assertFalse(text(view.panel()).contains("Catacombs")); assertTrue(text(view.panel()).contains("Loading stats"));
            view.show(null,"Wiki unavailable. Retry.",false); assertTrue(text(view.panel()).contains("Retry"));
            assertFalse(components(view.panel()).stream().filter(JComboBox.class::isInstance).map(JComboBox.class::cast).findFirst().get().isShowing());
        });
    }
    @Test public void populatedCardsAndAllThreePageButtonsFitNarrowWidths() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            SlayerWikiPanel view = new SlayerWikiPanel(); view.show(greaterDemon(),"Ready",false);
            for (int width : new int[]{140,170,210})
            {
                layout(view.panel(),width); checkBounds(view.panel());
            }
            CompanionSidebarDeck deck = new CompanionSidebarDeck();
            JPanel small = SidebarControls.column(); small.add(SidebarControls.text("Small"));
            JPanel large = SidebarControls.column(); large.add(SidebarControls.scroll(SidebarControls.text("Large"),700));
            deck.page("Play",small); deck.page("Account",large); deck.page("Details",SidebarControls.column());
            layout(deck,170); int before = deck.getPreferredSize().height;
            deck.showPage("Account"); layout(deck,170); assertTrue(deck.getPreferredSize().height > before + 500);
            deck.showPage("Play"); layout(deck,170); assertTrue(deck.getPreferredSize().height < 200);
            for (Component component : components(deck)) if (component instanceof javax.swing.AbstractButton && component.isVisible())
            {
                javax.swing.AbstractButton button = (javax.swing.AbstractButton)component;
                assertTrue(button.getText(),button.getFontMetrics(button.getFont()).stringWidth(button.getText()) + button.getInsets().left + button.getInsets().right <= button.getWidth());
            }
        });
    }
    static void layout(JPanel root,int width)
    {
        root.setSize(width,2000);
        for (int i=0;i<4;i++) { layoutTree(root); root.setSize(width,root.getPreferredSize().height); }
    }
    private static void layoutTree(Container parent) { parent.doLayout(); for (Component c:parent.getComponents()) if (c instanceof Container) layoutTree((Container)c); }
    private static void checkBounds(Container parent)
    {
        for (Component child:parent.getComponents()) if (child.isVisible())
        {
            assertTrue(child.getClass().getSimpleName(),child.getX() >= 0 && child.getX()+child.getWidth() <= parent.getWidth());
            if (child instanceof JTextArea && !((JTextArea)child).getText().isEmpty())
                assertTrue("Visible facts need a nonzero layout area",child.getWidth() > 0 && child.getHeight() > 0);
            if (child instanceof Container) checkBounds((Container)child);
        }
    }
    private static List<Component> components(Container root)
    {
        List<Component> result = new ArrayList<>();
        for (Component child:root.getComponents()) { result.add(child); if (child instanceof Container) result.addAll(components((Container)child)); }
        return result;
    }
    private static String text(Container root)
    {
        StringBuilder result = new StringBuilder();
        for (Component child:components(root)) if (child instanceof JTextArea && visibleInTree(child,root)) result.append(((JTextArea)child).getText()).append('\n');
        return result.toString();
    }
    private static boolean visibleInTree(Component value,Container root)
    {
        while (value != null && value != root) { if (!value.isVisible()) return false; value = value.getParent(); } return value == root;
    }
}

package com.hcimprogression.companion;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
